/// **Every lifecycle object the selected chain ACCEPTED, newest first, down to `not_before_daa`**
/// (ADR-0093 Decision 7) — back from the sink along selected parents, through each chain block's
/// acceptance data (the merged blocks' transactions it accepted, in reverse), stopping below the
/// height or after `max_chain_blocks` chain blocks. A transaction the chain did not accept, or on
/// another subnetwork, or whose payload does not decode, is never visited.
pub(crate) fn walk_accepted_lifecycle_objects_v1(
    consensus: &dyn kaspa_consensus_core::api::ConsensusApi,
    not_before_daa: u64,
    max_chain_blocks: usize,
    visit: &mut dyn FnMut(PalwConsensusObjectV2),
) {
    let mut cursor = consensus.get_sink();
    for _ in 0..max_chain_blocks {
        let Ok(header) = consensus.get_header(cursor) else { return };
        if header.daa_score < not_before_daa {
            return;
        }
        if let Ok(acceptance) = consensus.get_block_acceptance_data(cursor) {
            for merged in acceptance.iter().rev() {
                if merged.accepted_transactions.is_empty() {
                    continue;
                }
                let Ok(block) = consensus.get_block(merged.block_hash) else { continue };
                for entry in merged.accepted_transactions.iter().rev() {
                    let Some(tx) = block.transactions.get(entry.index_within_block as usize) else { continue };
                    if tx.subnetwork_id != SUBNETWORK_ID_PALW_LIFECYCLE {
                        continue;
                    }
                    if let Ok(payload) = borsh::from_slice::<PalwLifecycleTxPayloadV2>(&tx.payload) {
                        visit(payload.object);
                    }
                }
            }
        }
        let Ok(ghostdag) = consensus.get_ghostdag_data(cursor) else { return };
        if ghostdag.selected_parent == cursor {
            return;
        }
        cursor = ghostdag.selected_parent;
    }
}

/// Read one bounded page of accepted lifecycle history from `start`. `Some(next)` is the first selected-chain block not read;
/// `None` means the floor or the chain's root was reached. Missing retained data is an error, never a completed range. Callers
/// keep the page's original tip while resuming, so blocks arriving during backfill are read by the subsequent walk.
pub(crate) fn walk_accepted_lifecycle_page_v1(
    consensus: &dyn kaspa_consensus_core::api::ConsensusApi,
    start: Hash64,
    not_before_daa: u64,
    max_chain_blocks: usize,
    visit: &mut dyn FnMut(PalwConsensusObjectV2),
) -> Result<Option<Hash64>, String> {
    walk_accepted_lifecycle_page_with_block_v2(consensus, start, not_before_daa, max_chain_blocks, &mut |_, object| visit(object))
}

/// Like the paged walker, with the selected-chain fold block. A mergeset carrier's own block
/// is not the journal key; completion material must be read at the block accepting it.
pub(crate) fn walk_accepted_lifecycle_page_with_block_v2(
    consensus: &dyn kaspa_consensus_core::api::ConsensusApi,
    start: Hash64,
    not_before_daa: u64,
    max_chain_blocks: usize,
    visit: &mut dyn FnMut(Hash64, PalwConsensusObjectV2),
) -> Result<Option<Hash64>, String> {
    let mut cursor = start;
    for _ in 0..max_chain_blocks {
        let header = consensus.get_header(cursor).map_err(|e| format!("history header {cursor}: {e}"))?;
        if header.daa_score < not_before_daa {
            return Ok(None);
        }
        let acceptance = consensus.get_block_acceptance_data(cursor).map_err(|e| format!("history acceptance {cursor}: {e}"))?;
        for merged in acceptance.iter().rev() {
            if merged.accepted_transactions.is_empty() {
                continue;
            }
            let block = consensus.get_block(merged.block_hash).map_err(|e| format!("history block {}: {e}", merged.block_hash))?;
            for entry in merged.accepted_transactions.iter().rev() {
                let tx = block.transactions.get(entry.index_within_block as usize).ok_or_else(|| {
                    format!("history block {} has no accepted transaction {}", merged.block_hash, entry.index_within_block)
                })?;
                if tx.subnetwork_id == SUBNETWORK_ID_PALW_LIFECYCLE
                    && let Ok(payload) = borsh::from_slice::<PalwLifecycleTxPayloadV2>(&tx.payload)
                {
                    visit(cursor, payload.object);
                }
            }
        }
        let ghostdag = consensus.get_ghostdag_data(cursor).map_err(|e| format!("history selected parent {cursor}: {e}"))?;
        if ghostdag.selected_parent == cursor {
            return Ok(None);
        }
        cursor = ghostdag.selected_parent;
    }
    Ok(Some(cursor))
}

/// **Will the court open this root claim's output tile at `daa`?** (ADR-0119 Decision 4.)
///
/// The court opens a fused site's rows under `palw_attn_opening_cap_v1`: the structural `2^22`
/// before the held regime, the claim's ladder under it. This node's evidence is built at its
/// backend's ladder — at least the court's under the regime, for every claim this node can
/// produce — so the one filing the court would refuse is a claim past `2^22` leaves before the
/// regime, and the root claim is the one move filed without asking the chain first (a close asks
/// `palw_court_close_verdict_v2`). A root claim the court refuses buys nothing and costs a fee.
fn attn_root_claim_is_openable_v1(params: &kaspa_consensus_core::config::params::Params, daa: u64, step_leaf_count: u64) -> bool {
    params.palw_held_context_fence().is_some_and(|fence| fence.is_active(daa))
        || step_leaf_count <= kaspa_consensus_core::palw_step::PALW_STEP_MAX_LEAVES
}

/// **The accused's filing, read back off the chain** (ADR-0093 Decisions 7 and 8).
///
/// A bottom is opened against the ACCUSED's commitments, and two things about them only the accused
/// can supply once its execution has lied: its committed output tile (a fold keeps no rows) and,
/// when its execution followed the lie, the path to its anchor checkpoint. The chain made it file
/// both — the tile in either form of its root claim, the anchor in `CourtAttnRootClaimedAnchored`
/// — and the session record keeps neither, so they are read from the accepted objects
/// ([`walk_accepted_lifecycle_objects_v1`], down to the session's own opening: no root claim about
/// it is older). Every root claim filed for `session_id` in that span is returned, OLDEST first: the
/// first that stood is the one that opened the phase, and the caller keeps only one whose tile
/// proves against the claim's own root at the narrowed leaf, so a refused or foreign object is
/// never the filing.
fn attn_root_filings_from_chain_v1(
    consensus: &dyn kaspa_consensus_core::api::ConsensusApi,
    session_id: Hash64,
    not_before_daa: u64,
    max_chain_blocks: usize,
) -> Vec<kaspa_consensus_core::palw_attn_responder_v1::PalwAttnAccusedFilingV1> {
    use kaspa_consensus_core::palw_attn_responder_v1::PalwAttnAccusedFilingV1;
    let mut found = Vec::new();
    walk_accepted_lifecycle_objects_v1(consensus, not_before_daa, max_chain_blocks, &mut |object| match object {
        PalwConsensusObjectV2::CourtAttnRootClaimed { session_id: filed, binding, out_tile, .. } if filed == session_id => {
            found.push(PalwAttnAccusedFilingV1 { binding: *binding, out_tile, anchor: None });
        }
        PalwConsensusObjectV2::CourtAttnRootClaimedAnchored { session_id: filed, binding, out_tile, anchor, .. }
            if filed == session_id =>
        {
            found.push(PalwAttnAccusedFilingV1 { binding: *binding, out_tile, anchor: Some(*anchor) });
        }
        _ => {}
    });
    found.reverse();
    found
}

/// **RFC-0002 F7, option D: the accused's IR root claims for `session_id`, off the chain** — every
/// `CourtTirRootClaimed` accepted since `not_before_daa`, OLDEST first, as they rode (program empty).
/// Read, never believed: the walk returns objects the fold refused too, and the challenger's bottom
/// builder re-checks the one it uses against the claim and the phase.
fn tir_root_claims_from_chain_v1(
    consensus: &dyn kaspa_consensus_core::api::ConsensusApi,
    session_id: Hash64,
    not_before_daa: u64,
    max_chain_blocks: usize,
) -> Vec<kaspa_consensus_core::palw_tir_dissect_v1::PalwTirRootClaimV1> {
    let mut found = Vec::new();
    walk_accepted_lifecycle_objects_v1(consensus, not_before_daa, max_chain_blocks, &mut |object| {
        if let PalwConsensusObjectV2::CourtTirRootClaimed { session_id: filed, root, .. } = object
            && filed == session_id
        {
            found.push(*root);
        }
    });
    found.reverse();
    found
}

/// **The held route's paged chain reads, beside [`attn_root_filings_from_chain_v1`]** (ADR-0152 §4-ter
/// N3, C2; 4-ter.3 step 6): through the strict paged walk, every lifecycle object accepted since the
/// session's opening that is a held root claim for `session_id` (`CourtAttnRootClaimedHeld`, tag 57:
/// the accused's binding, tile, anchor and slice sub-roots — `PalwAttnHeldFilingV1::from_object_v1(&object)`
/// reads them) or the producer's disclosure of a held unit of `claim_id` (R-core+'s
/// `MaterialDisclosedV2`, the v1 court's `MaterialDisclosedHeld`). The map retains only the oldest authenticated root and one answer
/// per selected chunk; the route publishes it after completing the anchored backfill. Partial suffixes never select the first
/// standing filing. Refused objects in accepted carriers cannot enter the cache; consumers re-check the current duty when using it.
fn attn_held_objects_page_from_chain_v1(
    consensus: &dyn kaspa_consensus_core::api::ConsensusApi,
    read: held_court::PalwHeldChainReadV1,
    previous: Option<held_court::PalwHeldHistoryWalkV1>,
    duty: &kaspa_consensus_core::palw_producer_v2::PalwCourtDutyV2,
    needed: &[held_court::PalwHeldStep6UnitV1],
    opening_cap: u64,
    max_chain_blocks: usize,
) -> Result<held_court::PalwHeldHistoryPageV1, String> {
    let tip = consensus.get_sink();
    let same_branch = match previous {
        Some(walk) if walk.anchor != tip => {
            consensus.is_chain_ancestor_of(walk.anchor, tip).map_err(|e| format!("held history branch: {e}"))?
        }
        _ => true,
    };
    let selection = held_court::palw_held_history_selection_v1(duty, needed, opening_cap);
    let changed = previous.is_some_and(|walk| walk.selection != selection);
    let continuing = previous.filter(|walk| same_branch && !changed && walk.next.is_some());
    // A branch change may remove a formerly cached root filing. Re-read down to the earlier completed/active floor too,
    // even when the present request is only for a later disclosure.
    let floor = continuing.map_or_else(
        || {
            if same_branch && !changed {
                read.not_before_daa
            } else {
                previous.map_or(read.not_before_daa, |walk| walk.floor.min(read.not_before_daa))
            }
        },
        |walk| walk.floor,
    );
    let anchor = continuing.map_or(tip, |walk| walk.anchor);
    let start = continuing.and_then(|walk| walk.next).unwrap_or(tip);
    let mut found = BTreeMap::new();
    let next = walk_accepted_lifecycle_page_v1(consensus, start, floor, max_chain_blocks, &mut |object| {
        if read.session_id == duty.session_id
            && read.claim_id == duty.claim_id
            && let Some(key) = held_court::palw_held_history_object_key_v1(&object, duty, needed, opening_cap)
        {
            // The walk is newest first; the last valid root is the oldest in this page. Repeats and decoys do not grow the map.
            found.insert(key, object);
        }
    })?;
    Ok(held_court::PalwHeldHistoryPageV1 {
        walk: held_court::PalwHeldHistoryWalkV1 { floor, anchor, next, selection },
        reset: !same_branch,
        rewind: changed || !same_branch,
        objects: found,
    })
}

/// Whether an accepted lifecycle object is one [`attn_held_objects_page_from_chain_v1`] returns for the
/// session and its claim — the predicate alone, so a fixture chain filters with it too.
#[allow(dead_code)] // dormant or test-only: kept, not yet wired to a caller in this build
pub(crate) fn palw_held_chain_object_is_the_sessions_v1(
    object: &PalwConsensusObjectV2,
    session_id: &Hash64,
    claim_id: &Hash64,
) -> bool {
    match object {
        PalwConsensusObjectV2::CourtAttnRootClaimedHeld { .. } => {
            kaspa_consensus_core::palw_attn_responder_v1::PalwAttnHeldFilingV1::from_object_v1(object)
                .is_some_and(|(filed, _)| filed == *session_id)
        }
        PalwConsensusObjectV2::MaterialDisclosedV2 { claim, .. } => claim == claim_id,
        PalwConsensusObjectV2::MaterialDisclosedHeld { disclosure } => disclosure.claim == *claim_id,
        _ => false,
    }
}

/// **A backend computation runs OFF the async runtime.** A seat's re-execution, a canonical
/// inference, a refutation with its operand openings: seconds to minutes of CPU on a small host,
/// and the panel's `worker` is a tokio task. A worker thread that runs one cannot park on the I/O
/// driver, and enough of them at once leave no thread to poll the sockets — the .113 public
/// node's 2026-09-02 hang had exactly that shape (every worker in futex_wait, no epoll thread,
/// peers timing out into CLOSE-WAIT). The backend is moved into a blocking task and handed back so
/// the caller keeps using it; `Err` is a task that did not finish (a panic), which loses the
/// backend and is the caller's `continue`.
async fn offload<T, F>(
    backend: Box<dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1>,
    work: F,
) -> Result<(Box<dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1>, T), String>
where
    T: Send + 'static,
    F: FnOnce(&dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1) -> T + Send + 'static,
{
    tokio::task::spawn_blocking(move || {
        let out = work(backend.as_ref());
        (backend, out)
    })
    .await
    .map_err(|e| format!("the backend task did not finish: {e}"))
}

/// The job a challenger re-executes off the runtime: the user's for a free prompt (ADR-0073
/// Decision 1d), the block's for an attempt.
enum PalwV2SeatPathV1 {
    FullReplay,
    Waiting,
    /// SEAT-R: a partial seat's resume is not yet verified against the claim (SEAT-S4) — it files
    /// nothing.
    Abstain,
    Attested(kaspa_consensus_core::palw_verification_v2::PalwSegmentMaskV2),
    /// S3 sampled a site that disagrees — the court tries it; this seat files no receipt.
    Faulted,
}

enum ReplayWork {
    FreePrompt(kaspa_consensus_core::palw_freeprompt_v3::PalwFreePromptJobV3, Vec<usize>),
    Attempt(kaspa_consensus_core::palw_v2::PalwJobContextV2, Vec<usize>),
}

impl ReplayWork {
    fn run(
        self,
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
    ) -> Option<kaspa_consensus_core::palw_backend::PalwExecutionOutcomeV1> {
        match self {
            Self::FreePrompt(job, prompt) => backend.execute_free_prompt(&job, &prompt).ok().map(|run| run.outcome),
            Self::Attempt(job, prompt) => backend.execute(&job, &prompt).ok(),
        }
    }
}

impl AsyncService for PalwPanelService {
    fn ident(self: Arc<Self>) -> &'static str {
        PALW_PANEL
    }

    fn start(self: Arc<Self>) -> AsyncServiceFuture {
        Box::pin(async move {
            // **Registration is a precondition, not a mode.** A node registering its first bond has
            // none, so the registration job runs first — but it used to run INSTEAD, and
            // `--palw-register-bond` left in a service unit therefore replaced the panel with a
            // one-shot. `bond_registration_worker` sees the key already holds a bond, says so in one
            // INFO line, and returns; the service future completed and the seat answered nothing for
            // the rest of the process's life. Panels are derived from CHAIN state, not from whether
            // this process runs the service, so the bond kept being drawn — and `slash_silent_seats`
            // charges an absent seat `claim.reserved` at the receipt timeout and at both court
            // closes. The flag that was supposed to create a bond was quietly spending it.
            //
            // Falling through is safe in every case: `worker()` declines by itself, with its own
            // message, when there is no seat identity to run as — which is exactly the state a node
            // that has only just registered is in.
            if self.config.register_bond {
                self.bond_registration_worker().await;
            }
            self.worker().await;
            Ok(())
        })
    }

    fn signal_exit(self: Arc<Self>) {
        trace!("sending an exit signal to {}", PALW_PANEL);
        self.shutdown.trigger.trigger();
    }

    fn stop(self: Arc<Self>) -> AsyncServiceFuture {
        Box::pin(async move {
            trace!("{} stopped", PALW_PANEL);
            Ok(())
        })
    }
}

/// How many of the rolling fee chain's change outpoints `palw-fee-outpoint` remembers, newest first
/// (testnet-12 lifecycle audit T12-046).
pub(crate) const PALW_FEE_LINEAGE_KEEP_V1: usize = 16;

/// **The order the funder tries its remembered outpoints in** (review of T12-046): the one the
/// operator NAMES (`--palw-fee-outpoint`) first — an unspent named output is their choice, and the
/// warning that tells them to restart with the flag to choose another means exactly that — then the
/// rolling chain's lineage, newest first, each once. A named output that is spent (the usual state
/// of a genesis float after its first carrier) is skipped by the caller and the lineage takes over.
pub(crate) fn palw_fee_candidates_v1(configured: Option<&str>, lineage_file: &str) -> Vec<TransactionOutpoint> {
    let mut candidates: Vec<TransactionOutpoint> = Vec::new();
    if let Some(named) = configured.and_then(|c| crate::palw_producer::parse_outpoint(c).ok()) {
        candidates.push(named);
    }
    // **The rolling chain's whole recent lineage, newest first** (testnet-12 lifecycle audit
    // T12-046): the file used to hold only the LAST change, which a restart makes a ghost when the
    // carrier that created it was still unmined (a node's mempool does not survive it) — and then
    // neither memory resolved, the scan took the largest output under the key (the user's own
    // 2,499.59 MSK balance) and the consented float's live remainder, one step back in the chain, was
    // forgotten.
    for older in palw_fee_lineage_read_v1(lineage_file) {
        if !candidates.contains(&older) {
            candidates.push(older);
        }
    }
    candidates
}

/// The remembered fee lineage, newest first: one `<txid>:<index>` per line. A file a previous build
/// wrote (one line) reads as a lineage of one; a line that does not parse is skipped.
pub(crate) fn palw_fee_lineage_read_v1(text: &str) -> Vec<TransactionOutpoint> {
    text.lines().filter_map(|line| crate::palw_producer::parse_outpoint(line.trim()).ok()).collect()
}

/// `outpoint` at the head of the remembered lineage `text`, the rest after it once each, at most
/// [`PALW_FEE_LINEAGE_KEEP_V1`] — the file's next contents.
pub(crate) fn palw_fee_lineage_push_v1(text: &str, outpoint: TransactionOutpoint) -> String {
    let mut lineage = vec![outpoint];
    for older in palw_fee_lineage_read_v1(text) {
        if !lineage.contains(&older) {
            lineage.push(older);
        }
    }
    lineage.truncate(PALW_FEE_LINEAGE_KEEP_V1);
    lineage.iter().map(|o| format!("{}:{}", o.transaction_id, o.index)).collect::<Vec<_>>().join("\n")
}

#[cfg(test)]
mod fee_lineage_tests {
    use super::{PALW_FEE_LINEAGE_KEEP_V1, palw_fee_candidates_v1, palw_fee_lineage_push_v1, palw_fee_lineage_read_v1};
    use kaspa_consensus_core::tx::{TransactionId, TransactionOutpoint};

    fn op(n: u64) -> TransactionOutpoint {
        TransactionOutpoint::new(TransactionId::from_u64_word(n), 0)
    }

    /// **T12-046: a restart resumes from the consented float's live remainder.** The file used to
    /// hold only the newest change; when the carrier that made it was unmined at the restart, that
    /// outpoint was a ghost and the panel scanned the key's whole balance. The lineage keeps the one
    /// before it — the float's remainder still standing on chain — as the next candidate.
    #[test]
    fn t12_046_the_fee_file_keeps_the_lineage_newest_first() {
        let old_file = format!("{}:{}", op(1).transaction_id, op(1).index);
        assert_eq!(palw_fee_lineage_read_v1(&old_file), vec![op(1)], "a previous build's one-line file reads as a lineage of one");
        let two = palw_fee_lineage_push_v1(&old_file, op(2));
        assert_eq!(palw_fee_lineage_read_v1(&two), vec![op(2), op(1)], "newest first, the older change kept");
        let again = palw_fee_lineage_push_v1(&two, op(1));
        assert_eq!(palw_fee_lineage_read_v1(&again), vec![op(1), op(2)], "each once");
        let mut text = String::new();
        for n in 0..40 {
            text = palw_fee_lineage_push_v1(&text, op(n));
        }
        let lineage = palw_fee_lineage_read_v1(&text);
        assert_eq!(lineage.len(), PALW_FEE_LINEAGE_KEEP_V1, "bounded");
        assert_eq!(lineage[0], op(39));
        assert_eq!(palw_fee_lineage_read_v1("garbage\n\n"), vec![], "a line that does not parse is skipped");
    }

    /// **The named outpoint first, then the lineage** (review of T12-046): what the funder tries
    /// agrees with what its warning tells an operator — restart with `--palw-fee-outpoint` to choose
    /// the output carriers are funded from.
    #[test]
    fn t12_046_a_named_fee_outpoint_is_tried_before_the_remembered_lineage() {
        let spell = |o: TransactionOutpoint| format!("{}:{}", o.transaction_id, o.index);
        let file = palw_fee_lineage_push_v1(&palw_fee_lineage_push_v1("", op(1)), op(2));
        assert_eq!(palw_fee_candidates_v1(Some(&spell(op(9))), &file), vec![op(9), op(2), op(1)], "the named one leads");
        assert_eq!(palw_fee_candidates_v1(Some(&spell(op(2))), &file), vec![op(2), op(1)], "each once");
        assert_eq!(palw_fee_candidates_v1(None, &file), vec![op(2), op(1)], "no flag: the lineage");
        assert_eq!(palw_fee_candidates_v1(Some("not an outpoint"), ""), vec![], "an unparsable flag names nothing");
        let source = include_str!("palw_panel.rs");
        let funder = &source[source.find("    async fn resolve_fee_funding(").expect("the funder")..];
        let funder = &funder[..funder.find("\n    }\n").expect("its end")];
        assert!(funder.contains("palw_fee_candidates_v1("), "the funder takes its order from the one function");
        assert!(funder.contains("an unspent named output is tried before any remembered change"), "and says so");
    }
}

/// **ADR-0077 Decision 8 (workstream B2): the interval lane's two halves on this node** — the
/// server that answers openings, and the seat that asks for them. A separate `impl` block, at the
/// end of the file, so that this lane never shares a merge hunk with the panel's existing loops.
impl PalwPanelService {
    /// **Who this node will serve an opening to** (ADR-0077 SA-2, ADR-0079 SA-3 and its Decision 4
    /// table row).
    ///
    /// The transport does the shape check and the rate; this closure does the two things that
    /// need a key and a chain view, and it is the only place either is reachable from the serving
    /// path: verify the ML-DSA-87 signature under this lane's own context, and ask the chain
    /// whether that public key is a bond at all. `palw_bond_of_pubkey_v2` is the derivation — a
    /// bond key carried in the request would be the requester's own claim about itself.
    ///
    /// **Freshness before the bond lookup**, because the lookup is the expensive half: a captured
    /// request must not be a permanent serving right, and a stale one must not buy a chain read.
    ///
    /// What this does NOT check is panel membership. ADR-0077 SA-2 admits two kinds of requester —
    /// "a seat of the claim's panel or an Active bond acting as challenger" — and the second is
    /// any Active bond, so requiring panel membership would refuse exactly the party the court
    /// depends on. The bond is what bounds the requester (collateral, and a per-bond rate);
    /// membership would bound nothing further.
    fn opening_authorizer(self: &Arc<Self>, network_domain: Hash64) -> kaspa_p2p_flows::palw_gossip::PalwOpeningAuthorizer {
        let me = std::sync::Arc::downgrade(self);
        std::sync::Arc::new(move |request: &kaspa_p2p_flows::palw_gossip::PalwOpeningRequestV1<'_>| {
            use kaspa_p2p_flows::palw_gossip::{OPENING_REQUEST_FRESHNESS_DAA, PalwServeRefusalV1};
            let me = me.upgrade().ok_or(PalwServeRefusalV1::NotServing)?;
            let session = me.consensus_manager.consensus().unguarded_session();
            let here = session.get_virtual_daa_score();
            if request.requested_daa.abs_diff(here) > OPENING_REQUEST_FRESHNESS_DAA {
                return Err(PalwServeRefusalV1::Stale);
            }
            // ADR-0111 Decision 2: a leaf-evidence request signs its leaf too, under its own tag.
            let signed = match (request.leaf_index, request.interval_index) {
                (Some(leaf), Some(index)) => crate::palw_fp_seat::palw_fp_verify_leaf_request_v1(
                    request.requester_pubkey,
                    request.signature,
                    network_domain,
                    request.claim,
                    index,
                    leaf,
                    request.requested_daa,
                ),
                _ => crate::palw_fp_seat::palw_fp_verify_opening_request_v1(
                    request.requester_pubkey,
                    request.signature,
                    network_domain,
                    request.claim,
                    request.interval_index,
                    request.requested_daa,
                ),
            };
            if !signed {
                return Err(PalwServeRefusalV1::BadSignature);
            }
            // **A `Retiring` bond is still served, deliberately.** ADR-0077 SA-2 says "an Active
            // bond acting as challenger", but a bond that was seated before it asked to retire
            // still owes its live duties to resolution — retirement stops it taking NEW work, not
            // finishing old work — and its collateral is still locked, so it still bounds the
            // requester exactly as the rate limit below needs it to. Refusing it here would cut a
            // seat off from the material for a duty the chain still holds it to.
            let Some((bond, _status)) = session.palw_bond_of_pubkey_v2(request.requester_pubkey) else {
                return Err(PalwServeRefusalV1::NotBonded);
            };
            // **A private claim is served to its readers and to nobody else** (ADR-0077 Decision
            // 16's transport half; private-prompts design, 2026-09-05). Both lanes pass through
            // here — the whole-capture pull and the interval opening — and an interval opening of
            // a prefill interval carries the prompt's own embeddings, which anyone holding the
            // artifact inverts back into the ids, so the readership rule covers both. The mode is
            // read off the retained payload's prefix, never off the request: a requester does not
            // get to say whether the claim it asks about is private.
            if me.retained_material_is_private_v1(&request.claim) && !session.palw_claim_readers_v2(request.claim).contains(&bond) {
                return Err(PalwServeRefusalV1::NotAReader);
            }
            // The rate-limit key. A bond is an outpoint; hashing it gives the transport a value it
            // can key a map on without naming a consensus type.
            Ok(crate::palw_fp_seat::palw_fp_bond_rate_key_v1(&bond.0))
        })
    }

    /// **The opening this node can produce for one interval of one claim** (ADR-0077 Decision 8's
    /// executor half, as the transport reaches it).
    ///
    /// Everything comes from bytes this node already holds under its DA obligation: the retained
    /// capture, the job inside it (which is hash-bound to the claim), and the class's artifact
    /// root as the CHAIN records it. `None` at every step is "stay silent" — a node that is not
    /// this claim's executor, or does not hold the class, simply does not answer, and the asking
    /// seat re-asks elsewhere.
    ///
    /// Runs on a blocking thread (the transport arranges that): it reads a file and runs the
    /// family's opening arithmetic.
    /// **Option B's serving half: the annex of leaf `leaf` of this node's own IR claim** — the class
    /// resolved from the capture's binding, the annex built by the IR backend (a fold re-derived once,
    /// through its memo), encoded under its magic. `None` (silence) where any step fails or the annex
    /// would not fit the lane; the asking seat re-asks, then leaves the claim to the chain's demand.
    fn serve_tir_leaf_annex_v1(&self, claim: Hash64, capture: &[u8], leaf: u64) -> Option<Vec<u8>> {
        let started = std::time::Instant::now();
        let decoded = misaka_palw_sdk::lineages::tir::TirCaptureV1::decode(capture).ok()?;
        let binding = &decoded.binding;
        let class_id = binding.class.class_id(&binding.artifact_root);
        let tir = match self.backends().resolve_tir_v1(class_id, binding.artifact_root)? {
            Ok(tir) => tir,
            Err(why) => {
                info!("[{PALW_PANEL}] claim {claim}: the annex of leaf {leaf} does not open here — the IR backend: {why}");
                return None;
            }
        };
        match tir.leaf_annex(capture, leaf) {
            Ok(annex) => {
                let bytes = annex.encode();
                if bytes.len() > kaspa_p2p_flows::palw_gossip::PALW_INTERVAL_OPENING_MAX_BYTES {
                    warn!(
                        "[{PALW_PANEL}] claim {claim}: the annex of leaf {leaf} is {} bytes, past the lane's cap — not served",
                        bytes.len()
                    );
                    return None;
                }
                info!(
                    "[{PALW_PANEL}] claim {claim}: served the IR annex of leaf {leaf} ({} bytes, {:.0?}) — RFC-0002 evidence transport B",
                    bytes.len(),
                    started.elapsed()
                );
                Some(bytes)
            }
            Err(e) => {
                info!("[{PALW_PANEL}] claim {claim}: the annex of leaf {leaf} does not open here: {e}");
                None
            }
        }
    }

    /// **The serving half of D-S6 over the network**: the rows of the claim's class from `first`, as many as the lane carries, off the
    /// class this node HOLDS (the class resolved from the capture it retains for the claim, as the annex's server does). Silence where
    /// this node holds no capture of the claim, or not the class, or nothing at `first`.
    fn serve_tir_rows_v1(&self, claim: Hash64, first: u32, count: u32) -> Option<Vec<u8>> {
        let capture = self
            .retained_capture(&claim)
            .or_else(|| std::fs::read(self.config.retention_dir.join("foreign").join(format!("{claim}.material"))).ok())
            .filter(|bytes| bytes.starts_with(&misaka_palw_sdk::lineages::tir::TirCaptureV1::MAGIC))?;
        let decoded = misaka_palw_sdk::lineages::tir::TirCaptureV1::decode(&capture).ok()?;
        let binding = &decoded.binding;
        let class_id = binding.class.class_id(&binding.artifact_root);
        let tir = self.backends().resolve_tir_v1(class_id, binding.artifact_root)?.ok()?;
        let reply = misaka_palw_sdk::lineages::tir::serve_rows_v1(
            tir.artifact().as_ref(),
            first,
            count,
            kaspa_p2p_flows::palw_gossip::PALW_INTERVAL_OPENING_MAX_BYTES - (64 << 10),
        )?;
        info!(
            "[{PALW_PANEL}] claim {claim}: served {count} inventory row(s) of class {class_id} from leaf {first} ({} bytes) — RFC-0006 D-S6",
            reply.len()
        );
        Some(reply)
    }

    /// **The serving half of the off-chain run request**: the `TirStepRun { first, count }` answer of the claim's retained capture (the
    /// executor's, or a foreign copy this node holds), as borsh of the disclosure — the very object the chain's DA answer carries, so
    /// the asker verifies it with `check_tir_step_run_disclosure_v1`. Silence where this node does not hold the capture or the class.
    fn serve_tir_run_v1(&self, claim: Hash64, first: u64, count: u32) -> Option<Vec<u8>> {
        use kaspa_consensus_core::palw_da_rcore_v1::{PalwDaAnswerV1, PalwDaUnitV1};
        if count == 0 || count > kaspa_consensus_core::palw_tir_court_v1::PALW_TIR_STEP_RUN_MAX_LEAVES_V1 {
            return None;
        }
        let capture = self
            .retained_capture(&claim)
            .or_else(|| std::fs::read(self.config.retention_dir.join("foreign").join(format!("{claim}.material"))).ok())
            .filter(|bytes| bytes.starts_with(&misaka_palw_sdk::lineages::tir::TirCaptureV1::MAGIC))?;
        let decoded = misaka_palw_sdk::lineages::tir::TirCaptureV1::decode(&capture).ok()?;
        let binding = &decoded.binding;
        let class_id = binding.class.class_id(&binding.artifact_root);
        let tir = self.backends().resolve_tir_v1(class_id, binding.artifact_root)?.ok()?;
        let PalwDaAnswerV1::TirStepRun(disclosure) = tir.step_unit_answer(&capture, PalwDaUnitV1::TirStepRun { first, count }).ok()?
        else {
            return None;
        };
        let bytes = borsh::to_vec(&*disclosure).ok()?;
        (bytes.len() <= kaspa_p2p_flows::palw_gossip::PALW_INTERVAL_OPENING_MAX_BYTES).then_some(bytes)
    }

    /// **A signed off-chain request for the run `[first, first + count)`** of a claim's step leaves (the run request kind).
    pub async fn request_tir_run_v1(&self, network_domain: Hash64, claim: Hash64, first: u32, count: u32, requested_daa: u64) -> bool {
        let Some(index) = kaspa_consensus_core::palw_tir_shard_v1::palw_tir_runs_request_index_v1(first) else { return false };
        self.request_tir_rows_v1_at(network_domain, claim, index, count, requested_daa).await
    }

    fn open_retained_interval(&self, claim: Hash64, interval_index: u32, leaf_index: Option<u64>) -> Option<Vec<u8>> {
        use misaka_palw_base0::fp_interval::{base0_fp_block_leaves_request_decode_v1, base0_fp_resume_request_decode_v1};
        // **RFC-0007 §II.7: a witness-chunk request (bit 25)** — the producer serves the chunk of the claim's retained witness, on the lane's own
        // authentication; `None` (silence) where it keeps no such witness or the retained piece no longer matches its digest.
        if let Some(chunk) = kaspa_consensus_core::palw_weight_block_v1::palw_witness_chunk_request_decode_v1(interval_index) {
            let served = sketch::palw_witness_chunk_v1(&self.config.retention_dir, &claim, chunk);
            match &served {
                Some(bytes) => {
                    info!("[{PALW_PANEL}] claim {claim}: served witness chunk {chunk} ({} bytes) — RFC-0007 §II.7", bytes.len())
                }
                None => info!("[{PALW_PANEL}] claim {claim}: witness chunk {chunk} is not kept here"),
            }
            return served;
        }
        // **RFC-0007 §II.8: a weight-block request (bit 26)** — any node holding the class answers with the inventory openings of the block's bytes,
        // on the lane's own authentication. The class is named by the root tag the signature binds; the seat verifies the answer against the root.
        if let (Some((site, block)), Some(tag)) =
            (kaspa_consensus_core::palw_weight_block_v1::palw_weight_block_request_decode_v1(interval_index), leaf_index)
        {
            let entry = self.backends().tir_entry_by_root_tag_v1(tag)?;
            let started = std::time::Instant::now();
            return match refetch::palw_weight_block_serve_v1(&entry, site, block) {
                Some(bytes) => {
                    info!(
                        "[{PALW_PANEL}] claim {claim}: served block {block} of weight site {site} ({} bytes, {:.0?}) — RFC-0007 §II.8",
                        bytes.len(),
                        started.elapsed()
                    );
                    Some(bytes)
                }
                None => {
                    info!("[{PALW_PANEL}] claim {claim}: block {block} of weight site {site} does not open here");
                    None
                }
            };
        }
        // **ADR-0111 Decision 2: a leaf's evidence, on the lane's own authentication.** The seat
        // named the leaf; this node answers with the one-move court's object for it — the builder
        // the on-chain disclosure uses too, so the two paths carry one set of bytes.
        // **RFC-0006 D-S6 over the network: a shard-only seat's row request** (bit 28 of the index) — the inventory rows of the
        // claim's class from the named leaf, each a Merkle opening the asker proves against the registered root itself.
        if let Some(first) = kaspa_consensus_core::palw_tir_shard_v1::palw_tir_rows_request_decode_v1(interval_index) {
            return self.serve_tir_rows_v1(claim, first, leaf_index.unwrap_or(1).min(u64::from(u32::MAX)) as u32);
        }
        // **RFC-0006 §3 off chain: a seat's request for a RUN of step leaves** (bit 27) — answered as the chain's `TirStepRun` unit is.
        if let Some(first) = kaspa_consensus_core::palw_tir_shard_v1::palw_tir_runs_request_decode_v1(interval_index) {
            return self.serve_tir_run_v1(claim, u64::from(first), leaf_index.unwrap_or(0).min(u64::from(u32::MAX)) as u32);
        }
        if let Some(leaf) = leaf_index
            .filter(|_| kaspa_consensus_core::palw_leaf_evidence_v1::palw_leaf_evidence_request_decode_v1(interval_index).is_some())
        {
            if self.config.drill_refuse_leaf_evidence {
                warn!(
                    "[{PALW_PANEL}] PALW DRILL: refusing the evidence of leaf {leaf} of claim {claim} — the seat must demand it on chain"
                );
                return None;
            }
            // **RFC-0002's evidence transport, option B: an IR claim's leaf is served as its annex**
            // (`misaka_palw_sdk::lineages::tir::PalwTirLeafAnnexV1`) — the binding, the leaf's preimage and
            // opening, the trace summary — built from this node's own retained capture, the executor's.
            if let Some(capture) =
                self.retained_capture(&claim).filter(|bytes| bytes.starts_with(&misaka_palw_sdk::lineages::tir::TirCaptureV1::MAGIC))
            {
                return self.serve_tir_leaf_annex_v1(claim, &capture, leaf);
            }
            let session = self.consensus_manager.consensus().unguarded_session();
            let started = std::time::Instant::now();
            return match self.retained_leaf_evidence_v1(&session, claim, leaf) {
                Ok(evidence) => {
                    let bytes = borsh::to_vec(&evidence).ok()?;
                    info!(
                        "[{PALW_PANEL}] claim {claim}: served the evidence of leaf {leaf} ({} bytes, {:.0?}) — ADR-0111's fast path",
                        bytes.len(),
                        started.elapsed()
                    );
                    Some(bytes)
                }
                Err(e) => {
                    info!("[{PALW_PANEL}] claim {claim}: the evidence of leaf {leaf} does not open here: {e}");
                    None
                }
            };
        }
        let bytes = self
            .retained_capture(&claim)
            .or_else(|| std::fs::read(self.config.retention_dir.join("foreign").join(format!("{claim}.material"))).ok())?;
        let session = self.consensus_manager.consensus().unguarded_session();
        // ADR-0086 Decision 6: a block-leaves request rides the same lane under a high-bit index.
        let block_request = base0_fp_block_leaves_request_decode_v1(interval_index);
        // ADR-0103 Decision 2: so does a held class's resume request, under bit 30.
        let resume_request = base0_fp_resume_request_decode_v1(interval_index);
        let segment_request = kaspa_consensus_core::palw_segment_resume_v1::palw_segment_opening_request_decode_v1(interval_index);
        // ADR-0085 §6 item 4: the step leaves the open court sessions on this claim have narrowed
        // to, which the served interval's annex carries when they fall inside it. Read off the
        // CHAIN, never off the request: an asker names nothing here, and a leaf no session names
        // is served no tile.
        let disputed: Vec<u64> = match (block_request.or(resume_request.map(|i| (i, 0))), self.bond) {
            (None, Some(bond)) => session
                .palw_court_duties_v2(vec![PalwBondKeyV2(bond)])
                .into_iter()
                .filter(|d| d.claim_id == claim)
                .filter_map(|d| d.terminal_index)
                .collect(),
            _ => Vec::new(),
        };
        if let Some(hit) = self.cached_opening_v1(&claim, interval_index, &disputed) {
            info!(
                "[{PALW_PANEL}] claim {claim}: request {interval_index:#x} answered from this node's own opening cache ({} bytes)",
                hit.len()
            );
            return Some(hit);
        }
        let _gate = self.opening_gate.lock().unwrap_or_else(|e| e.into_inner());
        // Somebody ahead in the queue may have opened exactly this request while we waited.
        if let Some(hit) = self.cached_opening_v1(&claim, interval_index, &disputed) {
            info!("[{PALW_PANEL}] claim {claim}: request {interval_index:#x} was opened while this one queued ({} bytes)", hit.len());
            return Some(hit);
        }
        let remember = |opened: Option<Vec<u8>>| -> Option<Vec<u8>> {
            if let Some(bytes) = opened.as_deref() {
                self.remember_opening_v1(claim, interval_index, &disputed, bytes);
            }
            opened
        };
        let serve = |backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
                     capture: &[u8],
                     prompt_ids: &[u32],
                     what: &str|
         -> Option<Vec<u8>> {
            let started = std::time::Instant::now();
            let answer = match (block_request, resume_request, segment_request) {
                (Some((interval, block)), _, _) => backend
                    .open_fp_block_leaves(capture, interval, block, prompt_ids)
                    .map(|b| (b, format!("block {block} of interval {interval}"))),
                (None, Some(interval), _) => backend
                    .open_fp_resume_v1(capture, interval, prompt_ids)
                    .map(|b| (b, format!("the state interval {interval} resumes from (ADR-0103 Decision 2)"))),
                (None, None, Some((seat_count, segment))) => backend
                    .open_segment_checkpoint_v1(capture, seat_count, segment)
                    .map(|b| (b, format!("V2 segment {segment} checkpoint (ADR-0133 S1)"))),
                (None, None, None) => backend.open_fp_interval_with_close(capture, interval_index, prompt_ids, &disputed).map(|b| {
                    let named = if disputed.is_empty() {
                        format!("interval {interval_index}")
                    } else {
                        format!("interval {interval_index} with the close annex for leaves {disputed:?}")
                    };
                    (b, named)
                }),
            };
            match answer {
                Ok((bytes, named)) => {
                    info!(
                        "[{PALW_PANEL}] claim {claim}: opened {named} of the {what} ({} bytes served, {:.0?})",
                        bytes.len(),
                        started.elapsed()
                    );
                    Some(bytes)
                }
                Err(e) => {
                    // A silent refusal here left a 300-token claim unanswered for 35 minutes on the
                    // devnet with no line on either side; the reason is the operator's to read.
                    info!(
                        "[{PALW_PANEL}] claim {claim}: request {interval_index:#x} on the {what} does not open ({:.0?}): {e}",
                        started.elapsed()
                    );
                    None
                }
            }
        };
        if let Some(payload) =
            kaspa_consensus_core::palw_freeprompt_v3::palw_fp_capture_decode_v1(&bytes, self.payload_prompt_ids_form(&bytes))
        {
            let facts = session.palw_producer_facts_v2(payload.material.job.class_id, None)?;
            let backend = self.executor_backend_v1(&session, payload.material.job.class_id, facts.artifact_root).ok()?;
            // The ids the interval consumed: the user's own, hash-bound to the job by
            // `palw_fp_capture_decode_v1` before this line is reached. Never logged (SA-7).
            return remember(serve(backend.as_ref(), &payload.capture, &payload.material.prompt_token_ids, "free-prompt capture"));
        }
        // A raw family capture — the attempt lane's retention (ADR-0084 Decision 4). The prompt is
        // the anchor's derivation, which the asking seat re-derives on its own; an opening over
        // any other prompt binds to nothing there.
        let Some((backend, shape)) = self.executor_backend_for_raw_capture_v1(&session, &bytes) else {
            info!("[{PALW_PANEL}] claim {claim}: no held class reads its retained capture — request {interval_index:#x} not opened");
            return None;
        };
        let (_, prompt) = backend.job_for_anchor(shape.job_context.job_id).ok()?;
        let prompt_ids: Vec<u32> = prompt.iter().map(|t| *t as u32).collect();
        remember(serve(backend.as_ref(), &bytes, &prompt_ids, "retained capture"))
    }

    /// The opening this node already computed for exactly this request, while it still holds it.
    fn cached_opening_v1(&self, claim: &Hash64, index: u32, disputed: &[u64]) -> Option<Vec<u8>> {
        let cache = self.served_openings.lock().unwrap();
        cache.iter().find(|(c, i, d, _)| c == claim && *i == index && d.as_slice() == disputed).map(|(_, _, _, bytes)| bytes.clone())
    }

    /// Keep a served opening for the next asker; oldest out first under a byte ceiling. Sized so a
    /// whole panel's draws over a couple of live claims fit — four seats × four intervals × the
    /// ~1.1 MB a 300-token interval opens to is under 20 MB.
    fn remember_opening_v1(&self, claim: Hash64, index: u32, disputed: &[u64], bytes: &[u8]) {
        const OPENING_CACHE_BYTES: usize = 64 << 20;
        if bytes.len() > OPENING_CACHE_BYTES {
            return;
        }
        let mut cache = self.served_openings.lock().unwrap();
        cache.retain(|(c, i, d, _)| !(*c == claim && *i == index && d.as_slice() == disputed));
        cache.push((claim, index, disputed.to_vec(), bytes.to_vec()));
        let mut total: usize = cache.iter().map(|(_, _, _, b)| b.len()).sum();
        while total > OPENING_CACHE_BYTES && cache.len() > 1 {
            total -= cache.remove(0).3.len();
        }
    }

    /// Register both halves of the serving side with the gossip center. Called once, from the
    /// panel worker, beside the material resolver — the two belong together: once an authorizer
    /// exists the whole-capture pull is authenticated too (SA-2's last sentence), and a node that
    /// registers neither serves nothing and refuses nobody.
    pub fn install_fp_interval_serving(self: &Arc<Self>, network_domain: Hash64) {
        self.flow_context.palw_gossip().set_opening_authorizer(self.opening_authorizer(network_domain));
        let me = std::sync::Arc::downgrade(self);
        self.flow_context.palw_gossip().set_interval_opening_resolver(std::sync::Arc::new(move |claim, index, leaf| {
            me.upgrade()?.open_retained_interval(claim, index, leaf)
        }));
    }

    /// **May this seat judge a claim in this privacy mode?** (ADR-0077 Decision 16, P-16's seat
    /// half.) `PublicDa` always; `PanelDa` where the network carries the rule — the fence, read
    /// through `Params::palw_panel_da_admissible()` so that admission and judgement answer from
    /// one place. See [`crate::palw_fp_seat::palw_fp_seat_may_judge_mode_v1`] for why the previous
    /// hard-coded `PublicDa` test was not the safe choice it looked like.
    fn fp_privacy_mode_judgeable(&self, privacy_mode: u8) -> bool {
        crate::palw_fp_seat::palw_fp_seat_may_judge_mode_v1(privacy_mode, self.consensus_config.params.palw_panel_da_admissible())
    }

    /// **ADR-0085 Decision 3: what the served intervals give a close, or what is missing.**
    /// `Ok((held, prompt ids, output ids, work leaves))` when the interval owning `leaf` is held
    /// WITH an annex naming the leaf (and the interval before it, when there is one);
    /// `Missing(intervals)` names what to ask for; `NotThisLane` says the pull is the path (an
    /// attempt-lane claim, or a class that cannot place a leaf); `Refused` is a reason to log.
    fn close_source_from_served_intervals_v1(
        &self,
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
        claim: &Hash64,
        fp_job: Option<&kaspa_consensus_core::palw_freeprompt_v3::PalwFpMaterialV1>,
        pooled: &[Vec<u8>],
        openings: &HashMap<(Hash64, u32), Vec<Vec<u8>>>,
        leaf: u64,
    ) -> Result<(Vec<(u32, Vec<u8>)>, Vec<u32>, Vec<u32>, u64), CloseFromServedV1> {
        use kaspa_consensus_core::palw_freeprompt_v3::{palw_fp_committed_output_ids_decode_v1, palw_fp_job_material_decode_v1};
        use misaka_palw_base0::fp_interval::{Base0FpIntervalOpeningV4, base0_fp_interval_close_annex_any_v1};
        let Some(job) = fp_job else { return Err(CloseFromServedV1::NotThisLane) };
        let Some(prompt_ids) = Self::fp_prompt_for_job(backend, job, self.class_prompt_ids_form(job.job.class_id)) else {
            return Err(CloseFromServedV1::Refused("a canonical claim whose material is not its own prompt".to_string()));
        };
        // The answer's ids, off the same payloads the seat reads them from (ADR-0084 Decision 1).
        let disk = self.fp_retained_payload_paths(claim).into_iter().filter_map(|path| std::fs::read(path).ok());
        let form = self.class_prompt_ids_form(job.job.class_id);
        let Some(output_ids) = pooled.iter().cloned().chain(disk).find_map(|bytes| {
            palw_fp_job_material_decode_v1(&bytes, form)?;
            palw_fp_committed_output_ids_decode_v1(&bytes, |capture| backend.fp_committed_output_ids(capture), form)
        }) else {
            return Err(CloseFromServedV1::Refused("no served answer carries this claim's ids".to_string()));
        };
        // **The context is the run's, so the interval that owns the disputed leaf is the one that
        // exists** (ADR-0084 Decision 4, ADR-0074 Decision 7). Built at the job's ceiling this
        // located the leaf in a geometry an early-stopping claim never had; the ids are fetched
        // first now because the executed count is their length.
        let Some(ctx) = backend.fp_job_context_for_executed_v1(&job.job, output_ids.len().min(u32::MAX as usize) as u32) else {
            return Err(CloseFromServedV1::NotThisLane);
        };
        let Some(wanted) = backend.fp_interval_of_leaf_v1(&ctx, leaf) else { return Err(CloseFromServedV1::NotThisLane) };
        let primary = openings.get(&(*claim, wanted)).into_iter().flatten().find(|bytes| {
            base0_fp_interval_close_annex_any_v1(bytes).is_some_and(|annex| annex.disputed.iter().any(|d| d.leaf_index == leaf))
        });
        let previous = wanted
            .checked_sub(1)
            .and_then(|i| openings.get(&(*claim, i)).into_iter().flatten().find(|b| Base0FpIntervalOpeningV4::decode_v1(b).is_ok()));
        let mut missing = Vec::new();
        if primary.is_none() {
            missing.push(wanted);
        }
        if wanted > 0 && previous.is_none() {
            missing.push(wanted - 1);
        }
        if !missing.is_empty() {
            return Err(CloseFromServedV1::Missing(missing));
        }
        let primary = primary.expect("checked above").clone();
        let primary_v4 = Base0FpIntervalOpeningV4::decode_v1(&primary)
            .map_err(|e| CloseFromServedV1::Refused(format!("the held opening is not V4: {e:?}")))?;
        let work_leaves = primary_v4.binding.step_leaf_count;
        // **The executor's leaves for the block the disputed leaf is in** (ADR-0085 Decision 3
        // against a liar; ADR-0086 Decision 6's block-leaves lane). A V4 opening carries no leaf
        // hashes, and this seat's own replay walks to the committed root only where the executor's
        // leaves ARE its own — which a lie inside the interval rules out. So the close holds the
        // block beside the opening, and asks for it on the same lane when it does not. A leaf in a
        // block the opening does not cover whole has no block to ask for, and the close says so.
        let block = leaf >> primary_v4.range.retain_level.min(63);
        let (first_block, end_block) = primary_v4.range.whole_blocks_v1(work_leaves);
        // The request names the block by the number its class counts in (ADR-0121 Decision 3).
        let block_request = (first_block..end_block)
            .contains(&block)
            .then(|| misaka_palw_base0::fp_interval::base0_fp_block_request_number_v1(&primary_v4, block))
            .flatten()
            .and_then(|number| misaka_palw_base0::fp_interval::base0_fp_block_leaves_request_index_v1(wanted, number));
        let served_block =
            block_request.and_then(|index| openings.get(&(*claim, index)).and_then(|v| v.first()).map(|b| (index, b.clone())));
        if let (Some(index), None) = (block_request, served_block.as_ref()) {
            return Err(CloseFromServedV1::Missing(vec![index]));
        }
        let mut held = vec![(wanted, primary)];
        if let Some(prev) = previous {
            held.push((wanted - 1, prev.clone()));
        }
        held.extend(served_block);
        Ok((held, prompt_ids, output_ids, work_leaves))
    }

    /// ADR-0085 Decision 4: remember a fault this seat found, for the challenger's half. A leaf
    /// once named replaces the block it was found in (`PalwSeatFaultLedgerV1` orders the addresses).
    fn note_seat_fault_v1(&self, claim: Hash64, first_leaf_index: u64, leaf_count: u64) {
        self.seat_faults.lock().unwrap().note(claim, first_leaf_index, leaf_count);
    }

    const SAMPLE_REFUSALS_LOGGED_CAP: usize = 1_024;

    /// Whether this is the first time this seat reports that no drawn leaf of `claim`'s capture
    /// adjudicates here — see `sample_refusals_logged`.
    fn first_sample_refusal_v1(&self, claim: Hash64) -> bool {
        let mut logged = self.sample_refusals_logged.lock().unwrap();
        if logged.len() >= Self::SAMPLE_REFUSALS_LOGGED_CAP {
            logged.clear();
        }
        logged.insert(claim)
    }

    /// **ADR-0098 Decision 2: has this seat found a fault in `claim`?** When it has, the verdict
    /// block files nothing about the claim — neither a later arm's `Valid` nor the half-window
    /// `Unavailable` — and the fault goes to the court through the challenger's half.
    fn seat_found_fault_v1(&self, claim: &Hash64) -> bool {
        self.seat_faults.lock().unwrap().holds(claim)
    }

    /// **Hold one served opening, bounded** (ADR-0077 Decision 8).
    ///
    /// The transport has already refused anything this node did not ask for, anything over the
    /// lane's byte cap, and anything past a `(claim, interval)`'s slot ceiling — so what reaches
    /// here is bounded per pair. What is NOT bounded by that is the number of PAIRS, which grows
    /// with every claim this seat is drawn onto and never shrinks on its own, so the map has its
    /// own ceiling: a new pair past it is dropped rather than admitted. Dropping the newest is the
    /// right way round here, unlike the material pool: the seat asked for these, it re-asks on its
    /// own cadence, and evicting an older pair would discard an answer to a request that is still
    /// open.
    fn pool_interval_opening(pool: &mut HashMap<(Hash64, u32), Vec<Vec<u8>>>, claim: Hash64, interval_index: u32, bytes: Vec<u8>) {
        /// `PALW_FP_SEAT_INTERVAL_SAMPLES_V1` intervals for each of 128 claims in flight.
        const PAIRS: usize = 512;
        /// The lane's own per-pair slot ceiling, mirrored so this map cannot outgrow it if the
        /// transport's changes.
        const PER_PAIR: usize = 4;
        let key = (claim, interval_index);
        if !pool.contains_key(&key) && pool.len() >= PAIRS {
            return;
        }
        let slot = pool.entry(key).or_default();
        if slot.len() >= PER_PAIR {
            return;
        }
        info!("[{PALW_PANEL}] claim {claim}: holding a served opening of interval {interval_index} ({} bytes)", bytes.len());
        slot.push(bytes);
    }

    /// **The answer's ids, as the claim committed them, bound to the chain** — what ADR-0082
    /// Decision 9's recompute teacher-forces on (ADR-0084 Decisions 1 and 6).
    ///
    /// A seat needs the ids and nothing else about the answer: `4 × decode_tokens` bytes. They
    /// arrive on the answer envelope (`FPA1`) the executor's node serves in place of a capture
    /// the transport would refuse, or on an `FPC1` payload's capture read THROUGH THE SEAM
    /// (`fp_committed_output_ids`, the fold and the dense tuple alike — this used to name the
    /// dense decoder and returned nothing for every graph-v5 fold). The pooled copies first, then
    /// this node's own retention and its foreign directory, the same sources every other arm reads.
    ///
    /// **Bound before believed.** Every candidate's ids must recompute the claim's committed
    /// `output_root` under the candidate's own job (ADR-0078 X6, `fp_output_root_v1`): a forged
    /// envelope is refused BY NAME here, before a forward pass is spent on it, so it cannot make
    /// this seat file nothing — the pool is iterated and the honest one binds. A candidate that
    /// binds is retained under `foreign/`, write-once and a few kilobytes, so this node can serve
    /// it to the next seat that asks.
    fn fp_committed_output_ids_v1(
        &self,
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        pooled: &[Vec<u8>],
    ) -> Option<Vec<u32>> {
        self.fp_committed_answer_v1(backend, duty, pooled).map(|(_, ids)| ids)
    }

    /// [`Self::fp_committed_output_ids_v1`] with the job the ids bound under — the claim's own job,
    /// with certainty: the committed `output_root` is built over the job's context hash, so ids that
    /// recompute it under a candidate's job name that job as the claim's.
    fn fp_committed_answer_v1(
        &self,
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        pooled: &[Vec<u8>],
    ) -> Option<(kaspa_consensus_core::palw_freeprompt_v3::PalwFpMaterialV1, Vec<u32>)> {
        use kaspa_consensus_core::palw_freeprompt_v3::{palw_fp_committed_output_ids_decode_v1, palw_fp_job_material_decode_v1};
        let disk = self.fp_retained_payload_paths(&duty.claim_id).into_iter().filter_map(|path| std::fs::read(path).ok());
        let form = self.class_prompt_ids_form(duty.class_id);
        pooled.iter().cloned().chain(disk).find_map(|bytes| {
            let material = palw_fp_job_material_decode_v1(&bytes, form)?;
            let ids = palw_fp_committed_output_ids_decode_v1(&bytes, |capture| backend.fp_committed_output_ids(capture), form)?;
            // **The context is built from the ANSWER's own length, and the chain says whether that
            // was right** (ADR-0084 Decision 1, ADR-0074 Decision 7).
            //
            // `fp_output_root_v1` builds it at the job's CEILING. That is the producer's question,
            // not the run's answer: a claim that stopped early (`EndOfGeneration`, chain-legal by
            // `validate_stateless_v3`) committed its root under a context carrying the EXECUTED
            // count, so the ceiling context reproduces nothing and the seat rejected every honest
            // early-stopping claim's ids — which took the whole ADR-0077 D8 interval lane with it,
            // because the arm that calls this is gated on its `Some`. The commitment's own
            // invariant is `output_token_ids.len() == decode_tokens_executed`, so the length IS
            // the count, and comparing the rebuilt root against `duty.output_root` is the chain
            // confirming it. Nothing here is believed: a wrong length gives a wrong root.
            let ctx = backend.fp_job_context_for_executed_v1(&material.job, ids.len().min(u32::MAX as usize) as u32)?;
            let recomputed = backend.output_root_for_context_v1(&ctx, &ids)?;
            if recomputed != duty.output_root {
                warn!(
                    "[{PALW_PANEL}] claim {}: a served answer's ids recompute output root {recomputed} and the claim committed {} — \
                     not this claim's answer, refused before any replay (ADR-0084)",
                    duty.claim_id, duty.output_root
                );
                return None;
            }
            if kaspa_consensus_core::palw_freeprompt_v3::palw_fp_answer_decode_v1(&bytes, form).is_some() {
                self.persist_foreign_answer(&duty.claim_id, &bytes);
            }
            Some((material, ids))
        })
    }

    /// Every file a free-prompt payload for `claim` may be retained under, own retention first:
    /// the material and the answer envelope, then their foreign twins (ADR-0084 Decision 2).
    fn fp_retained_payload_paths(&self, claim: &Hash64) -> [std::path::PathBuf; 4] {
        let dir = &self.config.retention_dir;
        [
            crate::palw_producer::palw_retained_material_path(dir, claim),
            crate::palw_producer::palw_retained_answer_path(dir, claim),
            dir.join("foreign").join(format!("{claim}.material")),
            dir.join("foreign").join(format!("{claim}{}", crate::palw_producer::PALW_RETAINED_ANSWER_SUFFIX)),
        ]
    }

    /// Persist a foreign answer envelope under `retention/foreign/`, write-once, best-effort — a
    /// few kilobytes proven the claim's (its ids recompute the committed `output_root`), so this
    /// node can serve the next seat's pull for the claim.
    fn persist_foreign_answer(&self, claim: &Hash64, bytes: &[u8]) {
        let dir = self.config.retention_dir.join("foreign");
        let path = dir.join(format!("{claim}{}", crate::palw_producer::PALW_RETAINED_ANSWER_SUFFIX));
        if path.exists() {
            return;
        }
        if let Err(e) = std::fs::create_dir_all(&dir).and_then(|()| std::fs::write(&path, bytes)) {
            warn!("[{PALW_PANEL}] cannot retain the answer envelope for claim {claim}: {e}");
        }
    }

    /// **The attempt lane's answer ids, bound to the chain** (ADR-0084 Decision 4).
    ///
    /// Off a served `ATA1` envelope — whose anchor and prompt must be what THIS seat derived from
    /// the block, a cross-check and never a source — or off a capture this node holds, through
    /// the family seam. Either way the ids must recompute the claim's committed `output_root`
    /// under the anchor-derived context (ADR-0078 X6) before a forward pass is spent on them; a
    /// candidate that does not is refused by name and the next one is tried. A bound envelope is
    /// retained under `foreign/` so this node can serve the next seat's pull.
    fn attempt_committed_output_ids_v1(
        &self,
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        ctx: &kaspa_consensus_core::palw_v2::PalwJobContextV2,
        anchor: Hash64,
        prompt_ids: &[u32],
        pooled: &[Vec<u8>],
    ) -> Option<Vec<u32>> {
        use kaspa_consensus_core::palw_attempt_v2::palw_attempt_answer_decode_v1;
        let disk = self.fp_retained_payload_paths(&duty.claim_id).into_iter().filter_map(|path| std::fs::read(path).ok());
        pooled.iter().cloned().chain(disk).find_map(|bytes| {
            let envelope = palw_attempt_answer_decode_v1(&bytes);
            let ids = match &envelope {
                Some(answer) => {
                    if answer.anchor != anchor || answer.prompt_token_ids != prompt_ids {
                        warn!(
                            "[{PALW_PANEL}] claim {}: a served attempt answer names anchor {} and this seat derived {anchor} — not \
                             this claim's answer (ADR-0084)",
                            duty.claim_id, answer.anchor
                        );
                        return None;
                    }
                    answer.output_token_ids.clone()
                }
                None => backend.fp_committed_output_ids(&bytes)?,
            };
            let recomputed = backend.output_root_for_context_v1(ctx, &ids)?;
            if recomputed != duty.output_root {
                warn!(
                    "[{PALW_PANEL}] claim {}: a served answer's ids recompute output root {recomputed} and the claim committed {} — \
                     not this claim's answer, refused before any replay (ADR-0084)",
                    duty.claim_id, duty.output_root
                );
                return None;
            }
            if envelope.is_some() {
                self.persist_foreign_answer(&duty.claim_id, &bytes);
            }
            Some(ids)
        })
    }

    /// **Which held class wrote a raw family capture** (ADR-0084 Decision 4): the first registered
    /// class this node can resolve whose backend reads the bytes' shape. A raw capture names no
    /// class in the clear — its binding names the job context, and the context's profile is the
    /// class's — so the executor's own node, which retained the bytes, is the party that answers.
    /// Bounded by the class table's length, which is a handful of rows.
    fn backend_for_raw_capture_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        bytes: &[u8],
    ) -> Option<(
        Box<dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1>,
        kaspa_consensus_core::palw_backend::PalwCaptureShapeV1,
    )> {
        session.palw_v2_class_table().into_iter().find_map(|row| {
            let facts = session.palw_producer_facts_v2(row.class_id, None)?;
            let backend = self.resolve_backend(session, row.class_id, facts.artifact_root).ok()?;
            let shape = backend.capture_shape(bytes)?;
            // **The bytes decode under every base0 family's codec, so decoding is not identity.**
            // The floor's backend reads a graph-v5 tuple as happily as its own and then derives a
            // floor prompt for it — an opening over the wrong class, refused by the asking seat as
            // binding to nothing. The capture's own context names its class; the row must be it.
            if shape.job_context.shape_profile_id != row.class_id {
                return None;
            }
            Some((backend, shape))
        })
    }

    /// **What a pull for `claim` is answered with** (ADR-0084 Decision 2).
    ///
    /// The retained material — this node's own capture or a foreign one it proved — when it is
    /// within `PALW_MATERIAL_MAX_BYTES`, exactly as before. Otherwise the claim's answer envelope:
    /// the `<claim>.answer` the submitter staged beside the material (Decision 5), or one derived
    /// here from the capture through the family seam and cached under that name, once. The
    /// transport's "never serve what it would refuse" then never fires on an honest claim: a
    /// graph-v5 fold is ~700 MB and its envelope is a few kilobytes, and a seat on the interval
    /// lane needs exactly the envelope. `None` is the honest silence of a node holding nothing.
    ///
    /// Runs on a blocking thread (the transport arranges that): it stats and reads files.
    fn serve_material_or_answer(&self, claim: Hash64) -> Option<Vec<u8>> {
        use kaspa_p2p_flows::palw_gossip::PALW_MATERIAL_MAX_BYTES;
        let dir = &self.config.retention_dir;
        let own = crate::palw_producer::palw_retained_material_path(dir, &claim);
        let foreign = dir.join("foreign").join(format!("{claim}.material"));
        let (material_path, answer_path) = if own.exists() {
            (own, crate::palw_producer::palw_retained_answer_path(dir, &claim))
        } else if foreign.exists() {
            (foreign, dir.join("foreign").join(format!("{claim}{}", crate::palw_producer::PALW_RETAINED_ANSWER_SUFFIX)))
        } else {
            // No material at all: the envelope alone may still be here (a seat that proved one,
            // Decision 1's persistence), and it is what an interval-lane seat needs.
            let own_answer = crate::palw_producer::palw_retained_answer_path(dir, &claim);
            let foreign_answer = dir.join("foreign").join(format!("{claim}{}", crate::palw_producer::PALW_RETAINED_ANSWER_SUFFIX));
            return std::fs::read(own_answer).ok().or_else(|| std::fs::read(foreign_answer).ok());
        };
        let size = std::fs::metadata(&material_path).ok()?.len();
        // DRILL (ADR-0111): served as if no capture fit the cap, whatever its size.
        if size <= PALW_MATERIAL_MAX_BYTES as u64 && !self.config.drill_answer_only {
            return std::fs::read(&material_path).ok();
        }
        if let Ok(answer) = std::fs::read(&answer_path) {
            return Some(answer);
        }
        let bytes = std::fs::read(&material_path).ok()?;
        let answer = self.derive_answer_envelope_v1(&bytes)?;
        // Cached beside the material, written whole then renamed, so the next pull costs a read
        // of kilobytes and a reader never sees a half file. Best-effort: a failed cache is a
        // slower serve, not a refused one.
        let partial = answer_path.with_extension("answer.partial");
        if let Err(e) = std::fs::write(&partial, &answer).and_then(|()| std::fs::rename(&partial, &answer_path)) {
            warn!("[{PALW_PANEL}] cannot cache the answer envelope for claim {claim}: {e}");
        } else {
            info!(
                "[{PALW_PANEL}] claim {claim}: the retained material is {size} bytes, over the {PALW_MATERIAL_MAX_BYTES} byte transport \
                 cap — derived its answer envelope ({} bytes) and serving that instead (ADR-0084)",
                answer.len()
            );
        }
        Some(answer)
    }

    /// The answer envelope of a retained `FPC1` payload: its job and prompt, and the answer's ids
    /// read off the capture by the family that wrote it. `None` for a payload that is not an
    /// `FPC1`, a class this node does not hold, or a capture the family cannot read — a raw
    /// attempt-lane capture is Decision 4's, not this function's.
    fn derive_answer_envelope_v1(&self, bytes: &[u8]) -> Option<Vec<u8>> {
        let session = self.consensus_manager.consensus().unguarded_session();
        if let Some(payload) =
            kaspa_consensus_core::palw_freeprompt_v3::palw_fp_capture_decode_v1(bytes, self.payload_prompt_ids_form(bytes))
        {
            let facts = session.palw_producer_facts_v2(payload.material.job.class_id, None)?;
            let backend = self.resolve_backend(&session, payload.material.job.class_id, facts.artifact_root).ok()?;
            let ids = backend.fp_committed_output_ids(&payload.capture)?;
            return Some(kaspa_consensus_core::palw_freeprompt_v3::palw_fp_answer_encode_v1(
                &payload.material.job,
                &payload.material.prompt_token_ids,
                &ids,
            ));
        }
        // A raw family capture — the attempt lane's retention (ADR-0084 Decision 4): the anchor is
        // the capture's own job id, the prompt is what the anchor derives, the ids are the
        // family's to read.
        let (backend, shape) = self.backend_for_raw_capture_v1(&session, bytes)?;
        let anchor = shape.job_context.job_id;
        let (_, prompt) = backend.job_for_anchor(anchor).ok()?;
        let prompt_ids: Vec<u32> = prompt.iter().map(|t| *t as u32).collect();
        let ids = backend.fp_committed_output_ids(bytes)?;
        Some(kaspa_consensus_core::palw_attempt_v2::palw_attempt_answer_encode_v1(anchor, &prompt_ids, &ids))
    }

    /// **The seat's duty under ADR-0082 Decision 9: recompute the cache, fetch only the rows.**
    ///
    /// The order is the whole mechanism, and every step of it exists because the step before it
    /// would otherwise be something the executor gets to choose:
    ///
    /// 1. The intervals come from the claim's BEACON and this seat's index
    ///    ([`crate::palw_fp_seat::palw_fp_seat_draw_v1`]), and the COUNT they are drawn inside
    ///    comes from chain facts. An executor that could shrink the count could predict the draw.
    /// 2. For each drawn interval the seat reads which checkpoint the opening says it resumes from
    ///    and RECOMPUTES the job's prefix to that call on its own kernels — the prompt it already
    ///    holds and the committed output ids, teacher-forced. It then compares 64 bytes: the tiled
    ///    root of the state it computed against the root the claim committed. The history is never
    ///    fetched, which at 131,072 positions is 7.5 GB not moved per seat per claim.
    /// 3. A mismatch is NAMED — the checkpoint, the call it covers, and both roots — and the seat
    ///    files NOTHING. It is not a conviction and not an accusation: a seat convicts nobody
    ///    (ADR-0028), and a bonded challenger may open a court holding exactly what this seat now
    ///    holds.
    /// 4. Only then does the seat replay the interval, from its OWN state, comparing every
    ///    committed row exactly.
    ///
    /// `None` means this seat has not concluded anything about the claim — no openings yet, an
    /// opening that binds to nothing, or a fault that is the court's question — and the caller's
    /// existing tail (the whole-capture arms, then the half-window `Unavailable`) applies
    /// unchanged. `Some(Incapable)` is the honest answer of a seat that cannot run the class at
    /// all: a row nobody can seat certifies nothing (ADR-0075), and it is free.
    ///
    /// **Logging** (ADR-0077 SA-5): claim ids, interval indices, checkpoint indices, leaf indices
    /// and roots are chain facts and are logged; no prompt id, no output id and no rendered byte
    /// ever is.
    ///
    /// **Keyed on the CONTEXT, so both lanes run it** (ADR-0084 Decision 4). A free-prompt claim's
    /// context is the job's (`fp_job_context_v1`) and its anchor is the job id; an attempt claim's
    /// context and prompt come from the block's anchor (`job_for_anchor`), as the whole-capture
    /// arm derives them. Everything below — the draw's counts, the covered bound, the recompute,
    /// the opening's binding — reads the context, so the lane decides only where it came from.
    #[allow(clippy::too_many_arguments)]
    async fn interval_seat_outcome_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        network_domain: Hash64,
        current_daa: u64,
        ctx: &kaspa_consensus_core::palw_v2::PalwJobContextV2,
        anchor: Hash64,
        prompt_ids: &[u32],
        output_ids: &[u32],
        openings: &HashMap<(Hash64, u32), Vec<Vec<u8>>>,
        // RFC-0001 §A (G5): a free-prompt claim's JOB — its id is the claim's, so its decode rule is
        // the claim's — and `None` for an attempt. A V4 job's intervals are replayed under its
        // pipeline over `output_ids`; a V3 job keeps the V3 verifier byte for byte.
        fp_job: Option<&kaspa_consensus_core::palw_freeprompt_v3::PalwFreePromptJobV3>,
    ) -> Option<PalwReceiptVerdictV2> {
        use crate::palw_fp_seat::PalwFpChainCountsV1;
        use kaspa_consensus_core::palw_backend::PalwFpIntervalVerdictV1;

        let Ok(mut backend) = self.resolve_backend(session, duty.class_id, duty.artifact_root) else {
            return Some(PalwReceiptVerdictV2::Incapable);
        };
        // **Nothing this claim's replay resumes from was computed for another claim.** The state
        // the row check reads is keyed by the class, the context, the prompt and the covered call
        // — the four things an opening can name — and the answer's ids are not among them, because
        // the check is handed an opening and no ids. The state lives in this duty's own resolved
        // instance and is dropped with it, so no other duty, executor opening or court computation
        // can evict it between this seat's recompute and its row check: the only state this
        // claim's row check can find is the one this claim's own recompute put there, seconds
        // earlier and from this claim's ids. The forget at the claim boundary keeps that true if a
        // resolve ever hands back a kept instance.
        backend.fp_forget_seat_state_v1();
        // Both counts are the context's own — a free-prompt job's, built from the answer the chain
        // committed (ADR-0084 Decision 1), or the anchor-derived job's — never read off a capture,
        // which is the executor's to shape.
        //
        // **And the context itself is re-priced against the chain before a single interval is
        // drawn** (ADR-0074 Decision 5; mainnet audit 2026-09-06 C-3). Hash-binding the context to
        // the job through `fp_job_id_v3` was believed to be enough and is not: the job id is one
        // field of `PalwJobContextV2` and the two token counts are two others, so a producer may
        // commit a fifty-million-leaf execution and SERVE a two-call job carrying the same id.
        // The seat's interval count is then 1, the draw is `[0]`, and interval 0 is the only
        // interval such a producer ran — two forward passes for the claim's whole quanta. The
        // price is the one number the chain does hold, so it is what the context must reproduce.
        let counts =
            PalwFpChainCountsV1 { prompt_tokens: ctx.declared_prefill_tokens, decode_tokens_executed: ctx.exact_decode_tokens };
        let priced = backend.fp_context_work_leaves_v1(ctx);
        let Some(draw) =
            crate::palw_fp_seat::palw_fp_seat_draw_at_the_claims_price_v1(backend.as_ref(), network_domain, duty, counts, priced)
        else {
            if kaspa_consensus_core::palw_backend::palw_claim_prices_work_v1(duty.work_leaves)
                && priced.is_some_and(|leaves| leaves != duty.work_leaves)
            {
                warn!(
                    "[{PALW_PANEL}] claim {}: the served job's context prices at {:?} leaves and the chain priced this claim at {} — \
                     this is not the claim's job, and no interval of it is drawn (ADR-0074 Decision 5)",
                    duty.claim_id, priced, duty.work_leaves
                );
            }
            return None;
        };
        let roots = PalwClaimRootsV1 {
            execution_root: duty.execution_root,
            trace_root: duty.trace_root,
            anchor,
            attempt_draw: None,
            output_root: Some(duty.output_root),
            // ADR-0152 v3.1 J-1 (the 3a review's L-b): the pin the claim recorded.
            job_pin: duty.fp_job_pin_v1(),
        };
        // **The bound is the CLASS's, in the class's own cadence unit** (audit B, C-2). A
        // checkpoint leaf's `covered_decode_call` counts decode calls on a per-call class and
        // cache POSITIONS on a per-position one, and the two differ by the prefill — so a panel
        // that bounded every opening by the job's decode count refused every honest graph-v5
        // anchor before recomputing anything, and no quorum was reachable for the class. The
        // backend answers because the backend holds the profile; the real guard is still the
        // geometry re-derivation inside `verify_fp_interval_opening`.
        let covered_bound = backend.checkpoint_covered_bound_for_context_v1(ctx);
        // **ADR-0103 Decision 2: the route to an interval's start is the class's, derived.** A held
        // class whose whole context does not fit this ruleset's receipt window at its family's
        // replay rate is resumed from the state the executor serves — fetched, verified slice by
        // slice against the committed checkpoint, never replayed from unverified — instead of a
        // prefix recompute no window holds. Every other class recomputes (ADR-0082 Decision 9).
        let resumes = backend.fp_held_route_v1(self.window_receipt_daa_v1())
            == Some(kaspa_consensus_core::palw_held_context_v1::PalwHeldSeatRouteV1::Resume);
        let mut unanswered: Vec<u32> = Vec::new();
        let held: usize = draw.intervals.iter().filter(|i| openings.contains_key(&(duty.claim_id, **i))).count();
        self.config.telemetry.panel_openings_held(duty.class_id, held as u64);
        info!(
            "[{PALW_PANEL}] claim {}: interval seat — drew {:?} of {} interval(s), {held} opening(s) held",
            duty.claim_id, draw.intervals, draw.interval_count
        );
        // **The interval route's replays are RESERVED for their life** (DoS audit 2026-09-24, #4).
        // Every opening this seat holds is judged by a forward pass — the prefix recompute to the
        // interval's checkpoint (or the served state it resumes from), the interval's own replay,
        // and the naming replays behind a fault — and none of them took a reservation, so they
        // started beside a producer's attempt and a court's resume in this process whatever the
        // host held. Priced as the full seat of this context (its sink, the fold, is what these
        // routes keep; the prefix is at most the whole job's), taken only when an opening is held
        // (with none there is only a request to send), and a refusal defers the claim: nothing is
        // filed, and the caller's next arm takes its own reservation or none.
        let _held_for_the_intervals = if held > 0 {
            // The executor's kept walk and state are unreserved memory: released before a seat
            // reserves and walks, so a node never holds an idle executor walk beside a reserved
            // seat — the bound the process-wide forget used to give. It changes no executor answer:
            // a request in flight holds its own handle on the instance, and the next request
            // resolves a fresh one and walks from zero.
            self.release_executor_backend_v1();
            // Through the one door (the route-matrix re-audit's #5): a chain-registered class's
            // holding is found through its registration, never priced at zero bytes.
            // At the widest prefill run the ledger grants, on this duty's own instance — every replay
            // of the route below runs on it (int-10.2 A2).
            let backends = self.backends();
            match self.reserve_replay_at_widest_run_v1("interval-seat", backend.as_mut(), duty.class_id, duty.claim_id, |b| {
                backends.role_memory_need_for_backend_or_chain_v1(
                    b,
                    duty.class_id,
                    duty.artifact_root,
                    Some(ctx),
                    FULL_SEAT_V1,
                    |id| self.chain_carriage_v1(session, id),
                )
            }) {
                Ok((reserved, _)) => Some(reserved),
                Err(why) => {
                    crate::palw_backends::note_throttled_v1("panel-interval-ledger", || {
                        format!("[{PALW_PANEL}] interval seat of claim {} deferred: {why}", duty.claim_id)
                    });
                    return None;
                }
            }
        } else {
            None
        };

        for index in &draw.intervals {
            let candidates = openings.get(&(duty.claim_id, *index)).cloned().unwrap_or_default();
            // The resume state is asked for beside the interval, so one round trip brings both.
            let resume_packed =
                if resumes && *index > 0 { misaka_palw_base0::fp_interval::base0_fp_resume_request_index_v1(*index) } else { None };
            if candidates.is_empty() {
                unanswered.push(*index);
                unanswered.extend(resume_packed.filter(|p| !openings.contains_key(&(duty.claim_id, *p))));
                continue;
            }
            let mut answered = false;
            // Set when the interval waits on its resume state: the opening is held, and asking
            // for it again would be a second copy of bytes this seat already has.
            let mut awaiting_resume = false;
            for bytes in candidates {
                // **One context per claim** (ADR-0084 Decision 4), enforced rather than assumed.
                //
                // The family's own verification binds the opening to the claim's execution root,
                // its trace root, the job id and the price — and none of those pins the context's
                // two token counts, which are the numbers this seat's draw was sized by. An
                // opening whose binding carries a DIFFERENT context is evidence about a different
                // execution than the one this seat sampled, however honestly it walks. Refused
                // before a forward pass, and only on the free-prompt lane, where both contexts are
                // the same function of the same job; the attempt lane's context comes from the
                // block and is out of scope here.
                if duty.free_prompt {
                    match backend.fp_opening_job_context_v1(&bytes) {
                        Some(carried) if carried == *ctx => {}
                        _ => {
                            warn!(
                                "[{PALW_PANEL}] claim {}: an opening of interval {index} binds a context that is not the one this \
                                 seat derived from the served job — not this claim's evidence (ADR-0084 Decision 4)",
                                duty.claim_id
                            );
                            continue;
                        }
                    }
                }
                // What this opening says it resumes from. Every field of it is checked by the
                // replay below; reading it first is only how the seat learns how far to run.
                if let Some((checkpoint_index, covered, committed)) =
                    misaka_palw_base0::fp_interval::base0_fp_interval_opening_anchor_v1(&bytes)
                {
                    if covered == 0 || covered > covered_bound {
                        // An anchor outside the leg this job's class canonically files. Refused
                        // before a forward pass is spent on it: the cheap half of the guard the
                        // replay does anyway.
                        continue;
                    }
                    let (ctx_owned, prompt_owned, output_owned) = (ctx.clone(), prompt_ids.to_vec(), output_ids.to_vec());
                    let resumed = match resume_packed {
                        None => None,
                        Some(packed) => match openings.get(&(duty.claim_id, packed)).and_then(|v| v.first().cloned()) {
                            // Not held yet: ask, and conclude nothing about this interval this round.
                            None => {
                                unanswered.push(packed);
                                awaiting_resume = true;
                                break;
                            }
                            Some(state_bytes) => Some(state_bytes),
                        },
                    };
                    let Ok((returned, recomputed)) = (match resumed {
                        // The Resume route: the served state, verified against the committed
                        // checkpoint and held as this seat's own, so the interval check below
                        // replays from it exactly as from a recomputed one (ADR-0103 Invariant 6).
                        Some(state_bytes) => {
                            offload(backend, move |b| b.fp_accept_resume_v1(&state_bytes, &ctx_owned, &prompt_owned, covered)).await
                        }
                        None => {
                            offload(backend, move |b| {
                                b.checkpoint_root_for_context_v1(&ctx_owned, &prompt_owned, &output_owned, covered)
                            })
                            .await
                        }
                    }) else {
                        return None;
                    };
                    backend = returned;
                    if resume_packed.is_some()
                        && let Err(why) = &recomputed
                    {
                        // A state that does not verify is refused by name and never replayed from.
                        // Nothing is filed: an executor that served another state has served no
                        // evidence, and the interval goes back to the quorum's Unavailable arm.
                        warn!(
                            "[{PALW_PANEL}] claim {}: the state served for interval {index} does not verify against checkpoint \
                             {checkpoint_index} ({why}) — not replayed from (ADR-0103 Invariant 6)",
                            duty.claim_id
                        );
                        continue;
                    }
                    let recomputed = match recomputed {
                        Ok(root) => root,
                        Err(why) => {
                            // A seat that cannot recompute the class's state cannot judge the
                            // claim, and says so rather than filing an accusation. Free, and
                            // counting toward neither side of the quorum.
                            info!(
                                "[{PALW_PANEL}] claim {}: this node cannot recompute the state at checkpoint {checkpoint_index} \
                                 ({why}) — filing Incapable",
                                duty.claim_id
                            );
                            return Some(PalwReceiptVerdictV2::Incapable);
                        }
                    };
                    if recomputed != committed {
                        warn!(
                            "[{PALW_PANEL}] claim {}: checkpoint {checkpoint_index} (covering {covered}, the class's cadence unit) commits state \
                             root {committed} and this seat's own recompute reaches {recomputed} — filing nothing; the fault is the \
                             court's question, and this node holds the refutation's inputs",
                            duty.claim_id
                        );
                        // ADR-0098 Decision 2: recorded, or the challenger's half never prosecutes
                        // it. Every cache-altering lie before this interval lands HERE, which makes
                        // it the seat's strongest detector — and it was being thrown away. `(0, 0)`
                        // is a fault with no leaf address; the court's bisection finds the leaf.
                        self.note_seat_fault_v1(duty.claim_id, 0, 0);
                        return None;
                    }
                }
                // RFC-0001 §2.6 stage 2: a prefix-state claim (FP job version 11) names the K/V state its
                // prefix reached; the seat derives that state from the claim's own prompt ids (from its cache or
                // by recomputation) and a disagreement is a fault in the claim, filed as the court's question.
                if let Some(job) = fp_job.filter(|job| job.is_prefix_state()).cloned() {
                    let ids = prompt_ids.to_vec();
                    let Ok((returned, checked)) = offload(backend, move |b| b.verify_prefix_state_v1(&job, &ids)).await else {
                        return None;
                    };
                    backend = returned;
                    if let Err(why) = checked {
                        warn!("[{PALW_PANEL}] claim {}: its named prefix state does not hold ({why}) — filing nothing", duty.claim_id);
                        self.note_seat_fault_v1(duty.claim_id, 0, 0);
                        return None;
                    }
                }
                let (candidate, prompt_owned) = (bytes.clone(), prompt_ids.to_vec());
                let work_leaves = duty.work_leaves;
                let interval = *index;
                // RFC-0001 §A (G5): a V4 claim's rows are replayed under the claim's rule — its job's
                // pipeline over the committed answer — and a V3 claim's under the V3 verifier.
                let v4 = fp_job.filter(|job| job.decodes_under_v4_rules()).cloned().map(|job| (job, output_ids.to_vec()));
                let Ok((returned, verdict)) = offload(backend, move |b| match &v4 {
                    Some((job, answer)) => {
                        b.verify_fp_interval_opening_under_job_v1(&candidate, roots, interval, &prompt_owned, work_leaves, job, answer)
                    }
                    None => b.verify_fp_interval_opening(&candidate, roots, interval, &prompt_owned, work_leaves),
                })
                .await
                else {
                    return None;
                };
                backend = returned;
                match verdict {
                    PalwFpIntervalVerdictV1::Valid => {
                        answered = true;
                        break;
                    }
                    PalwFpIntervalVerdictV1::Fault { leaf_index } => {
                        warn!(
                            "[{PALW_PANEL}] claim {}: interval {index} does not replay at leaf {leaf_index} — filing nothing; a \
                             sampled verdict never slashes and the court's bisection is what convicts",
                            duty.claim_id
                        );
                        self.note_seat_fault_v1(duty.claim_id, leaf_index, 1);
                        return None;
                    }
                    PalwFpIntervalVerdictV1::FaultInRange { first_leaf_index, leaf_count } => {
                        warn!(
                            "[{PALW_PANEL}] claim {}: interval {index} does not replay in leaves [{first_leaf_index}, +{leaf_count}) — \
                             filing nothing; a sampled verdict never slashes, and the block is the court's address (ADR-0086 D3)",
                            duty.claim_id
                        );
                        self.note_seat_fault_v1(duty.claim_id, first_leaf_index, leaf_count);
                        // ADR-0086 Decision 6: ask for the block's leaves on the same lane, and name
                        // the leaf from them once they are held — the fault at leaf granularity is
                        // what a court narrows to. The level is the one the opening this seat just
                        // verified folds at, read off it, never derived here: a held class's is
                        // pinned at 12 whatever its ladder (ADR-0121 Decision 3), and the request
                        // names the block by the number that class counts in.
                        let served = misaka_palw_base0::fp_interval::Base0FpIntervalOpeningV4::decode_v1(&bytes).ok();
                        let retain_level = served.as_ref().map(|v4| v4.range.retain_level).unwrap_or_else(|| {
                            misaka_palw_base0::fp_capture::palw_base0_sparse_retain_level_v1(self.config.court.max_step_leaf_count())
                        });
                        // **A fault at an edge is named from the edges** (ADR-0121 §7). A block that
                        // straddles the interval's end is whole in no interval: no digest names it and
                        // the block naming refuses it. Both edges are asked for — the address cannot
                        // say which edge the lie is in — and named once both are held, by the range's
                        // own root walk.
                        if let Some(v4) = served.as_ref() {
                            let step_leaf_count = v4.binding.step_leaf_count;
                            let (first_block, end_block) = v4.range.whole_blocks_v1(step_leaf_count);
                            let size = 1u64 << v4.range.retain_level.min(63);
                            let at_edge = !first_leaf_index.is_multiple_of(size)
                                || !(first_block..end_block).contains(&(first_leaf_index >> v4.range.retain_level.min(63)));
                            if at_edge {
                                let (left, right) = v4.range.edges_v1(step_leaf_count);
                                let packed: Vec<u32> = [left, right]
                                    .into_iter()
                                    .filter(|(first, end)| first < end)
                                    .filter_map(|(first, _)| {
                                        misaka_palw_base0::fp_interval::base0_fp_block_request_number_v1(
                                            v4,
                                            first >> v4.range.retain_level.min(63),
                                        )
                                    })
                                    .filter_map(|number| {
                                        misaka_palw_base0::fp_interval::base0_fp_block_leaves_request_index_v1(interval, number)
                                    })
                                    .collect();
                                let held: Vec<Vec<u8>> = packed
                                    .iter()
                                    .filter_map(|p| openings.get(&(duty.claim_id, *p)).and_then(|v| v.first().cloned()))
                                    .collect();
                                if packed.is_empty() || held.len() < packed.len() {
                                    let missing: Vec<u32> =
                                        packed.iter().copied().filter(|p| !openings.contains_key(&(duty.claim_id, *p))).collect();
                                    let asked =
                                        self.request_fp_interval_openings(network_domain, duty.claim_id, &missing, current_daa).await;
                                    info!(
                                        "[{PALW_PANEL}] claim {}: asked the executor for the edges of interval {index} ({asked} signed \
                                         request(s), {} of {} held)",
                                        duty.claim_id,
                                        held.len(),
                                        packed.len()
                                    );
                                    return None;
                                }
                                let (candidate_for_naming, prompt_owned, output_owned) =
                                    (bytes.clone(), prompt_ids.to_vec(), output_ids.to_vec());
                                let Ok((_returned, named)) = offload(backend, move |b| {
                                    b.fp_name_the_edge_leaf_v1(
                                        &candidate_for_naming,
                                        &held,
                                        roots,
                                        interval,
                                        &prompt_owned,
                                        &output_owned,
                                        work_leaves,
                                    )
                                })
                                .await
                                else {
                                    return None;
                                };
                                match named {
                                    Ok(Some(leaf)) => {
                                        warn!(
                                            "[{PALW_PANEL}] claim {}: the served edges of interval {index} name leaf {leaf} — the \
                                             court's address (ADR-0121 §7)",
                                            duty.claim_id
                                        );
                                        self.note_seat_fault_v1(duty.claim_id, leaf, 1);
                                    }
                                    Ok(None) => warn!(
                                        "[{PALW_PANEL}] claim {}: every served edge leaf of interval {index} is this seat's own",
                                        duty.claim_id
                                    ),
                                    Err(e) => warn!(
                                        "[{PALW_PANEL}] claim {}: the served edges of interval {index} name no leaf: {e}",
                                        duty.claim_id
                                    ),
                                }
                                return None;
                            }
                        }
                        let block = first_leaf_index >> retain_level.min(63);
                        let number = match served.as_ref() {
                            Some(v4) => misaka_palw_base0::fp_interval::base0_fp_block_request_number_v1(v4, block),
                            None => Some(block),
                        };
                        if let Some(packed) = number.and_then(|number| {
                            misaka_palw_base0::fp_interval::base0_fp_block_leaves_request_index_v1(interval, number)
                        }) {
                            let served_block = openings.get(&(duty.claim_id, packed)).and_then(|v| v.first().cloned());
                            match served_block {
                                Some(block_bytes) => {
                                    let (candidate_for_naming, prompt_owned, output_owned) =
                                        (bytes.clone(), prompt_ids.to_vec(), output_ids.to_vec());
                                    let Ok((_returned, named)) = offload(backend, move |b| {
                                        b.fp_name_the_leaf_v1(
                                            &candidate_for_naming,
                                            &block_bytes,
                                            roots,
                                            interval,
                                            &prompt_owned,
                                            &output_owned,
                                            work_leaves,
                                        )
                                    })
                                    .await
                                    else {
                                        return None;
                                    };
                                    match named {
                                        Ok(Some(leaf)) => {
                                            warn!(
                                                "[{PALW_PANEL}] claim {}: the served block {block} of interval {index} names leaf {leaf} — the \
                                                 court's address (ADR-0086 D6)",
                                                duty.claim_id
                                            );
                                            self.note_seat_fault_v1(duty.claim_id, leaf, 1);
                                        }
                                        Ok(None) => warn!(
                                            "[{PALW_PANEL}] claim {}: every leaf of the served block {block} of interval {index} is this \
                                             seat's own — the executor served a block it did not commit; the address stays the block",
                                            duty.claim_id
                                        ),
                                        Err(e) => warn!(
                                            "[{PALW_PANEL}] claim {}: the served block {block} of interval {index} names no leaf: {e}",
                                            duty.claim_id
                                        ),
                                    }
                                }
                                None => {
                                    let asked =
                                        self.request_fp_interval_openings(network_domain, duty.claim_id, &[packed], current_daa).await;
                                    info!(
                                        "[{PALW_PANEL}] claim {}: asked the executor for block {block} of interval {index} ({asked} signed \
                                         request(s), index {packed:#x})",
                                        duty.claim_id
                                    );
                                }
                            }
                        }
                        return None;
                    }
                    PalwFpIntervalVerdictV1::Mismatch | PalwFpIntervalVerdictV1::Unverifiable => continue,
                }
            }
            if !answered && !awaiting_resume {
                unanswered.push(*index);
            }
        }

        if unanswered.is_empty() {
            if resumes {
                info!(
                    "[{PALW_PANEL}] claim {}: {} interval(s) replayed from state this seat verified against the committed \
                     checkpoints (the Resume route, ADR-0103 Decision 2)",
                    duty.claim_id,
                    draw.intervals.len()
                );
            } else {
                info!(
                    "[{PALW_PANEL}] claim {}: {} interval(s) replayed against this seat's own recomputed state — no history fetched",
                    duty.claim_id,
                    draw.intervals.len()
                );
            }
            return Some(PalwReceiptVerdictV2::Valid);
        }
        // Ask for what is missing and conclude nothing this round. The caller's tail is unchanged:
        // an interval that never arrives ends in the two-sided quorum's `Unavailable` arm at the
        // half-window, exactly as capture withholding does today.
        let asked = self.request_fp_interval_openings(network_domain, duty.claim_id, &unanswered, current_daa).await;
        info!(
            "[{PALW_PANEL}] claim {}: asked the executor for interval(s) {:?} ({asked} signed request(s))",
            duty.claim_id, unanswered
        );
        None
    }

    /// **A leaf's evidence, from this node's own retained capture** (ADR-0111 Decisions 1, 2 and
    /// 4) — the one builder behind the fast path's answer and the held DA court's disclosure, bound
    /// to the claim's roots as the CHAIN records them.
    fn retained_leaf_evidence_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        claim: Hash64,
        leaf: u64,
    ) -> Result<kaspa_consensus_core::palw_shard_court_v1::PalwLeafEvidenceV1, String> {
        let (backend, payload) = self.retained_fp_capture_v1(session, claim)?;
        let job = &payload.material.job;
        let (execution_root, trace_root, work_leaves) = session.palw_claim_roots_v2(claim).ok_or("the chain holds no such claim")?;
        // `output_root: None`: the chain's roots read (`palw_claim_roots_v2`) carries no output root,
        // and a leaf's evidence proves a step leaf against the execution root — not the answer.
        let roots = PalwClaimRootsV1 {
            execution_root,
            trace_root,
            anchor: kaspa_consensus_core::palw_freeprompt_v3::fp_job_id_v3(job),
            attempt_draw: None,
            output_root: None,
            job_pin: None,
        };
        kaspa_consensus_core::palw_leaf_evidence_v1::palw_leaf_evidence_from_capture_v1(
            backend.as_ref(),
            &payload.capture,
            &payload.material.prompt_token_ids,
            roots,
            work_leaves,
            leaf,
            self.class_prompt_ids_form(job.class_id),
        )
    }

    /// **This node's retained free-prompt capture of `claim`, with the backend of its class** —
    /// the one loader behind every answer an executor gives from its retention (ADR-0111 Decision
    /// 6): its own capture first, then one it holds for another executor.
    fn retained_fp_capture_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        claim: Hash64,
    ) -> Result<
        (
            std::sync::Arc<dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1>,
            kaspa_consensus_core::palw_freeprompt_v3::PalwFpCaptureV1,
        ),
        String,
    > {
        let bytes = self
            .retained_capture(&claim)
            .or_else(|| std::fs::read(self.config.retention_dir.join("foreign").join(format!("{claim}.material"))).ok())
            .ok_or("no retained capture for the claim")?;
        let payload =
            kaspa_consensus_core::palw_freeprompt_v3::palw_fp_capture_decode_v1(&bytes, self.payload_prompt_ids_form(&bytes))
                .ok_or("the retained material is not a free-prompt capture")?;
        let class_id = payload.material.job.class_id;
        let facts = session.palw_producer_facts_v2(class_id, None).ok_or("the chain names no such class")?;
        let backend = self.executor_backend_v1(session, class_id, facts.artifact_root)?;
        Ok((backend, payload))
    }

    /// The binding a retained capture commits, read off its interval 0 — which every family serves
    /// and which carries it.
    fn served_binding_v1(
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
        payload: &kaspa_consensus_core::palw_freeprompt_v3::PalwFpCaptureV1,
    ) -> Result<kaspa_consensus_core::palw_step_leg::PalwStepBindingV2, String> {
        let opened = backend.open_fp_interval(&payload.capture, 0, &payload.material.prompt_token_ids)?;
        let v4 = misaka_palw_base0::fp_interval::Base0FpIntervalOpeningV4::decode_v1(&opened)
            .map_err(|e| format!("interval 0 is not served in the form that carries the binding: {e:?}"))?;
        Ok(v4.binding)
    }

    /// **A held unit's disclosure, from this node's free-prompt retention** (ADR-0103 Decision 4;
    /// ADR-0111 Decisions 4 and 6): a leaf's evidence, a prompt tile, a state chunk or a run of step
    /// leaves, built by the ONE held builder (`palw_da_held_disclosure_from_capture_v1`, whose match
    /// names every unit the court can and has no catch-all) from the capture, its job's prompt and
    /// the claim's roots — the binding read off interval 0 where the answer does not carry its own.
    /// The v1 court's answer ([`Self::held_da_answer_v1`]) reads it; R-core's (P2-7) builds through
    /// the same builder ([`palw_fp_held_disclosure_v1`]) on the capture it verified, re-made if need be.
    fn fp_held_da_disclosure_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        claim: Hash64,
        missing: kaspa_consensus_core::palw_held_da_v1::PalwHeldMissingV1,
    ) -> Result<
        (kaspa_consensus_core::palw_step_leg::PalwStepBindingV2, kaspa_consensus_core::palw_held_da_v1::PalwHeldDisclosureV1),
        String,
    > {
        let (backend, payload) = self.retained_fp_capture_v1(session, claim)?;
        self.fp_held_da_disclosure_of_v1(session, claim, backend.as_ref(), &payload, missing)
    }

    /// [`Self::fp_held_da_disclosure_v1`] on a given free-prompt capture and its class's backend.
    fn fp_held_da_disclosure_of_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        claim: Hash64,
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
        payload: &kaspa_consensus_core::palw_freeprompt_v3::PalwFpCaptureV1,
        missing: kaspa_consensus_core::palw_held_da_v1::PalwHeldMissingV1,
    ) -> Result<
        (kaspa_consensus_core::palw_step_leg::PalwStepBindingV2, kaspa_consensus_core::palw_held_da_v1::PalwHeldDisclosureV1),
        String,
    > {
        let job = &payload.material.job;
        // `output_root: None`: the chain's roots read (`palw_claim_roots_v2`) carries no output root,
        // and a leaf's evidence proves a step leaf against the execution root — not the answer.
        // The roots are read by the leaf's arm only, and asked of the chain only for it.
        let (roots, work_leaves) = if matches!(missing, kaspa_consensus_core::palw_held_da_v1::PalwHeldMissingV1::StepLeaf { .. }) {
            let (execution_root, trace_root, work_leaves) =
                session.palw_claim_roots_v2(claim).ok_or("the chain holds no such claim")?;
            let anchor = kaspa_consensus_core::palw_freeprompt_v3::fp_job_id_v3(job);
            // `job_pin: None`: this builder proves a leaf against the execution root; the capture's job is
            // pinned where it is verified (R-core's answer, `PalwDaClaimFactsV1::roots_v1`), and the v1
            // court below the fence records no identity to pin.
            (
                PalwClaimRootsV1 { execution_root, trace_root, anchor, attempt_draw: None, output_root: None, job_pin: None },
                work_leaves,
            )
        } else {
            let none = Hash64::default();
            (
                PalwClaimRootsV1 {
                    execution_root: none,
                    trace_root: none,
                    anchor: none,
                    attempt_draw: None,
                    output_root: None,
                    job_pin: None,
                },
                0,
            )
        };
        palw_fp_held_disclosure_v1(backend, payload, roots, work_leaves, missing, self.class_prompt_ids_form(job.class_id))
    }

    /// **The held DA court's answer, in the unit accused** (ADR-0103 Decision 4; ADR-0111 Decisions
    /// 4 and 6), signed by the claim's bond: a leaf's evidence, a prompt tile, a state chunk or a run
    /// of step leaves, each built from this executor's retention ([`Self::fp_held_da_disclosure_v1`])
    /// — an executor that cannot answer is one the court slashes, so every unit the court can name
    /// has its answer there. The v1 court's (below `palw_rcore_plus`).
    fn held_da_answer_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        network_domain: Hash64,
        claim: Hash64,
        missing: kaspa_consensus_core::palw_held_da_v1::PalwHeldMissingV1,
    ) -> Result<PalwConsensusObjectV2, String> {
        use kaspa_consensus_core::palw_held_da_v1::{
            PALW_HELD_DA_MLDSA87_DISCLOSE_CONTEXT, PALW_HELD_DA_VERSION_V1, PalwHeldDisclosureCarriageV1,
            palw_held_da_disclosure_message_v1,
        };
        let (binding, disclosure) = self.fp_held_da_disclosure_v1(session, claim, missing)?;
        let mut carriage = PalwHeldDisclosureCarriageV1 {
            version: PALW_HELD_DA_VERSION_V1,
            claim,
            missing,
            binding,
            disclosure,
            signature: Vec::new(),
        };
        let domain = kaspa_consensus_core::palw_attempt_v2::palw_network_domain_v2_for(
            self.consensus_config.params.net.to_string().as_bytes(),
            Some(self.consensus_config.genesis.hash),
        );
        // The court verifies under the domain of the network's own id and genesis, which is what
        // `network_domain` is on this node; derived again here so the two cannot be told apart.
        debug_assert_eq!(domain, network_domain);
        let message = palw_held_da_disclosure_message_v1(domain.as_byte_slice(), &carriage);
        carriage.signature = self.sign(message.as_byte_slice(), PALW_HELD_DA_MLDSA87_DISCLOSE_CONTEXT).ok_or("no signing key")?;
        Ok(PalwConsensusObjectV2::MaterialDisclosedHeld { disclosure: Box::new(carriage) })
    }

    /// **Open event `(row, tile)` of a retained or re-made capture** (ADR-0062 D3; ADR-0152 DA-4) —
    /// nothing re-executed: the rows and ids kept at execution are what the claim committed. A
    /// free-prompt retention wraps the family capture with the job and its ids; the attempt lane
    /// retains the family capture bare (ADR-0084 Decision 4). The v1 court's responder; R-core's
    /// (P2-7) opens the capture it verified by the claim's own class ([`palw_da_unit_answer_v1`]).
    fn disclose_retained_event_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        class_id: Hash64,
        artifact_root: Hash64,
        bytes: &[u8],
        row: u32,
        tile: u8,
    ) -> Result<kaspa_consensus_core::palw_step_refute::PalwTraceEventDisclosureV1, String> {
        match kaspa_consensus_core::palw_freeprompt_v3::palw_fp_capture_decode_v1(bytes, self.class_prompt_ids_form(class_id)) {
            Some(payload) => self
                .resolve_backend(session, class_id, artifact_root)
                .and_then(|backend| backend.disclose_trace_event(&payload.capture, row, tile)),
            None => match self.backend_for_raw_capture_v1(session, bytes) {
                Some((backend, _)) => backend.disclose_trace_event(bytes, row, tile),
                None => Err("no held class reads the retained capture".to_string()),
            },
        }
    }

    /// **ADR-0152 DA-4 / X7 (P2-7): the tag-55 or legacy tag-158 objects that answer one claim's due units**,
    /// `duties` (one claim's, soonest deadline first), each signed by its duty's discloser — this
    /// node's bond: the producer, or a covering signer.
    ///
    /// The claim's facts are read off the chain here; everything heavy runs in ONE blocking task under
    /// ONE reservation of the memory ledger (`"da-answer"`, a full seat's figure for the class — the
    /// court's bound for its close, and an upper bound over a whole-job re-make and the held builders,
    /// which on a fold capture replay the anchor state): the copies this node kept are read and
    /// checked, the capture re-made if none verifies ([`palw_da_material_v1`]) and kept under
    /// `foreign/`, every unit answered from it ([`palw_da_claim_answers_v1`]), and the material dropped
    /// when the task ends. A refusal of the reservation is [`PalwDaClaimHoldV1::Ledger`], tried again
    /// the next tick; the duties arrive soonest deadline first, so the claim whose session ends first
    /// asks the ledger first. (The P2-7 review's MEDIUM: whole-job replays and held builders ran with
    /// no reservation, the held builders on the tick itself, beside a per-tick cache of every claim's
    /// whole capture.)
    ///
    /// The producer answers on the executor's kept instance (its walk, as the v1 held answer does); a
    /// covering signer on a fresh one through the one resolve door, which neither releases nor keeps
    /// the executor's (the review's LOW). Each object is built by the ONE builder the real-claim tests
    /// carry through the gate and the fold (`palw_da_built_answer_object_v1`), inside the ruleset's close
    /// ceiling (DA-8). One entry a duty, in order: `Ok(None)` for a unit a `Flat` answers.
    async fn rcore_da_answers_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        network_domain: Hash64,
        duties: &[&kaspa_consensus_core::palw_producer_v2::PalwDisclosureDutyV1],
        flat_queued: bool,
    ) -> Result<Vec<Result<Option<PalwConsensusObjectV2>, String>>, PalwDaClaimHoldV1> {
        use kaspa_consensus_core::palw_producer_v2::PalwDisclosureRoleV1;
        let Some(first) = duties.first() else { return Ok(Vec::new()) };
        let (claim, class_id, artifact_root) = (first.claim_id, first.class_id, first.artifact_root);
        let backend: Arc<dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1> = match first.role {
            PalwDisclosureRoleV1::Producer => self.executor_backend_v1(session, class_id, artifact_root),
            PalwDisclosureRoleV1::CoveringSigner => self.resolve_backend(session, class_id, artifact_root).map(Arc::from),
        }
        .map_err(PalwDaClaimHoldV1::Material)?;
        let (_, _, work_leaves) =
            session.palw_claim_roots_v2(claim).ok_or(PalwDaClaimHoldV1::Material("the chain holds no such claim".to_string()))?;
        let lane = if first.free_prompt {
            PalwDaLaneV1::FreePrompt { panel_da_admissible: self.consensus_config.params.palw_panel_da_admissible() }
        } else {
            let bond = &first.executor_bond;
            PalwDaLaneV1::Attempt {
                anchor: self
                    .job_anchor_for_claim(session, backend.as_ref(), network_domain, first.accepted_block, class_id, bond)
                    .unwrap_or_default(),
                attempt_draw: self.attempt_draw_for_claim(session, first.accepted_block),
                job: self.attempt_job_for_claim(session, backend.as_ref(), network_domain, first.accepted_block, class_id, bond),
            }
        };
        let facts = PalwDaClaimFactsV1 {
            claim_id: claim,
            class_id,
            executor_bond: first.executor_bond,
            execution_root: first.execution_root,
            trace_root: first.trace_root,
            work_leaves,
            form: self.class_prompt_ids_form(class_id),
            lane,
            job_pin: first.fp_job_pin_v1(),
        };
        let need = self.backends().role_memory_need_for_backend_or_chain_v1(
            backend.as_ref(),
            class_id,
            artifact_root,
            None,
            kaspa_consensus_core::palw_resource_profile_v1::PalwResourceRoleV1::FullSeat,
            |id| self.chain_carriage_v1(session, id),
        );
        let reserved = self.reserve_replay_v1("da-answer", &need, class_id, claim).map_err(PalwDaClaimHoldV1::Ledger)?;
        // Multipart serialization adds two complete encodings (the split buffer and its parts),
        // plus signature-message scratch and one bounded outgoing carrier per duty. Keep this
        // temporary reservation through signing/planning, alongside the replay reservation.
        let transport_max = self.config.court.max_close_bytes().min(
            u64::from(kaspa_consensus_core::palw_legacy_answer_chunks_v2::PALW_LEGACY_ANSWER_MAX_CHUNKS_V2)
                * u64::from(kaspa_consensus_core::palw_legacy_answer_chunks_v2::PALW_LEGACY_ANSWER_CHUNK_BYTES_V2),
        );
        let transport_bytes = transport_max.saturating_mul(3).saturating_add(
            (duties.len() as u64).saturating_mul(kaspa_consensus_core::palw_state_v2::PALW_OBJECT_CHUNK_MAX_BYTES as u64),
        );
        let _transport_reservation = if duties
            .iter()
            .any(|d| matches!(d.unit, kaspa_consensus_core::palw_da_rcore_v1::PalwDaUnitV1::LegacyHeldV2(_)))
        {
            Some(
                crate::palw_memory_ledger::host_ledger_v1()
                    .reserve(
                        crate::palw_memory_ledger::PalwMemoryReservationKeyV1 { role: "da-answer-transport", class_id, job: claim },
                        transport_bytes,
                    )
                    .map_err(|e| PalwDaClaimHoldV1::Ledger(format!("DA transport needs {transport_bytes} bytes: {e}")))?,
            )
        } else {
            None
        };
        // Every copy this node may hold, own retention first; a free-prompt claim's `.answer`
        // envelopes too, which carry its job.
        let dir = &self.config.retention_dir;
        let paths: Vec<PathBuf> = if first.free_prompt {
            self.fp_retained_payload_paths(&claim).to_vec()
        } else {
            vec![crate::palw_producer::palw_retained_material_path(dir, &claim), dir.join("foreign").join(format!("{claim}.material"))]
        };
        let foreign = dir.join("foreign");
        let units: Vec<kaspa_consensus_core::palw_da_rcore_v1::PalwDaUnitV1> = duties.iter().map(|duty| duty.unit).collect();
        let in_run_rows = first.in_run_rows;
        // The second IR fence's step leaves are answered by the claim's IR backend (RFC-0002 evidence
        // transport C): resolved here, once, when a unit asks for one — a class this node does not
        // hold as IR answers them with the unit's own error.
        let tir = if units.iter().any(|unit| unit.is_tir_fence2_v1()) {
            match self.backends().resolve_tir_v1(class_id, artifact_root) {
                Some(Ok(tir)) => Some(tir),
                Some(Err(why)) => return Err(PalwDaClaimHoldV1::Material(format!("the claim's IR backend does not build: {why}"))),
                None => None,
            }
        } else {
            None
        };
        let answer_form = facts.form;
        let (built, _held_for_the_answers) = offload_shared(backend, move |b| {
            let built = palw_da_claim_answers_v1(
                b,
                &facts,
                paths.iter().filter_map(|path| std::fs::read(path).ok()),
                |bytes| palw_da_keep_remade_v1(&foreign, &claim, bytes),
                &units,
                in_run_rows,
                flat_queued,
                tir.as_ref(),
            )?;
            Ok::<_, String>((built, reserved))
        })
        .await
        .map_err(PalwDaClaimHoldV1::Material)?
        .map_err(PalwDaClaimHoldV1::Material)?;
        if built.remade {
            info!(
                "[{PALW_PANEL}] claim {claim}: no kept copy reproduces its roots — its capture was re-made by replaying the claim's job \
                 and kept, to answer a data-availability session ({:?})",
                first.role
            );
        }
        let duties: Vec<_> = duties.iter().map(|d| (*d).clone()).collect();
        let session = session.clone();
        let keypair = self.keypair.clone();
        let maximum = self.config.court.max_close_bytes();
        tokio::task::spawn_blocking(move || {
            let _replay_guard = _held_for_the_answers;
            let _transport_guard = _transport_reservation;
            let sign = |message: &[u8], context: &[u8]| {
                keypair.as_ref().and_then(|kp| {
                    libcrux_ml_dsa::ml_dsa_87::sign(&kp.signing_key, message, context, [0u8; 32]).ok().map(|sig| sig.as_ref().to_vec())
                })
            };
            duties
                .iter()
                .zip(built.answers)
                .map(|(duty, answer)| match answer {
                    None => Ok(None),
                    Some(Err(why)) => Err(why),
                    Some(Ok(answer)) => {
                        let progress = if let kaspa_consensus_core::palw_da_rcore_v1::PalwDaUnitV1::LegacyHeldV2(unit) = duty.unit {
                            session.palw_legacy_answer_progress_v2((duty.claim_id, unit, duty.discloser))?
                        } else {
                            None
                        };
                        let object = palw_da_built_answer_carriage_v1(
                            &network_domain,
                            duty.claim_id,
                            duty.unit,
                            answer,
                            duty.discloser,
                            answer_form,
                            maximum,
                            false,
                            |message, context| sign(message, context),
                        )?;
                        da_answer_chunks::next_answer_object_v2(
                            object,
                            progress.as_ref(),
                            session.get_virtual_daa_score(),
                            duty.deadline_daa,
                            maximum,
                            &network_domain,
                            |message, context| sign(message, context),
                        )
                        .map(Some)
                    }
                })
                .collect()
        })
        .await
        .map_err(|e| PalwDaClaimHoldV1::Material(format!("DA transport task did not finish: {e}")))
    }

    const LEAF_PURSUITS_CAP: usize = 1_024;

    /// **ADR-0111 Decision 6, the seat's half.** A claim this seat found a fault in at a NAMED leaf
    /// (the block-leaves lane's answer, ADR-0086 Decision 6), with no accusation filed because it
    /// held no capture to build one from:
    ///
    /// 1. the executor's evidence, if it has answered — the one-move verdict at this seat's own
    ///    artifact root: guilty (or a fused site, whose accusation opens the dissection), the
    ///    accusation; clear, nothing, and the disagreement said once, because this seat's replay and
    ///    the court disagree about a leaf whose inputs they share, which is a determinism fault;
    /// 2. else the fast-path ask, once;
    /// 3. else, past `PALW_LEAF_EVIDENCE_FAST_PATH_DAA_V1`, the demand on chain, once — only where
    ///    the held regime and the DA court are in force, the only chains that take it.
    ///
    /// Returns the object to queue, keyed, and whether it is an accusation.
    async fn pursue_named_leaf_v1(
        &self,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        network_domain: Hash64,
        current_daa: u64,
        openings: &HashMap<(Hash64, u32), Vec<Vec<u8>>>,
        already_accused: bool,
    ) -> Option<(Hash64, PalwConsensusObjectV2, bool)> {
        use kaspa_consensus_core::palw_leaf_evidence_v1 as lev;
        use kaspa_consensus_core::palw_shard_court_v1::{PalwLeafEvidenceV1, PalwShardCourtVerdictV1};
        if already_accused {
            return None;
        }
        let (leaf, count) = self.seat_faults.lock().unwrap().address(&duty.claim_id)?;
        if count != 1 {
            return None; // a block or an unaddressed fault names no leaf yet
        }
        if self.leaf_pursuits.lock().unwrap().get(&duty.claim_id).is_some_and(|p| p.closed || p.leaf != leaf) {
            return None;
        }
        // The claim's binding, off any interval opening this seat holds for it; the chain checks it
        // against the claim's execution root when a demand lands, and so does this.
        let binding = openings
            .iter()
            .filter(|((claim, index), _)| *claim == duty.claim_id && lev::palw_leaf_evidence_request_decode_v1(*index).is_none())
            .flat_map(|(_, held)| held.iter())
            .find_map(|bytes| misaka_palw_base0::fp_interval::Base0FpIntervalOpeningV4::decode_v1(bytes).ok().map(|v4| v4.binding))
            .filter(|binding| binding.committed_execution_root == duty.execution_root)?;
        let interval = lev::PalwSeatIntervalGeometryV1::from_binding_v1(&binding)?.interval_of_leaf_v1(&binding, leaf)?;
        let index = lev::palw_leaf_evidence_request_index_v1(interval)?;
        let ladder = kaspa_consensus_core::palw_court_v2::palw_refutation_leaf_cap_v2(
            &self.config.court,
            self.consensus_config.params.palw_court_ladder.is_some_and(|f| f.is_active(current_daa)),
        );
        // ADR-0152 §4-ter: the CLASS's ladder past the fence (see `seat_refutation_ladder_v1`).
        let ladder = self.seat_refutation_ladder_v1(duty.class_id, ladder, current_daa);
        let domain = kaspa_consensus_core::palw_attempt_v2::palw_network_domain_v2_for(
            self.consensus_config.params.net.to_string().as_bytes(),
            Some(self.consensus_config.genesis.hash),
        );
        // 1. The executor's own evidence.
        let served = openings
            .get(&(duty.claim_id, index))
            .into_iter()
            .flatten()
            .filter_map(|bytes| borsh::from_slice::<PalwLeafEvidenceV1>(bytes).ok())
            .find(|evidence| evidence.leaf_index() == leaf && evidence.refutation.binding == binding);
        if let Some(evidence) = served {
            // t12 (`palw_audit_2026_09_23`): the chain binds the one move to the claim and refuses a
            // fused site's history, so the seat strips it and asks the verdict the chain will ask.
            let bound = self.consensus_config.params.palw_audit_2026_09_23_active_at(current_daa);
            let evidence = if bound { evidence.for_the_one_move_v2() } else { evidence };
            let bound_to = kaspa_consensus_core::palw_shard_court_v1::PalwOneMoveClaimV2 {
                execution_root: duty.execution_root,
                class_id: duty.class_id,
                artifact_root: duty.artifact_root,
            };
            match evidence.verdict_at_v2(&bound_to, ladder, bound) {
                Ok(PalwShardCourtVerdictV1::ExecutorGuilty | PalwShardCourtVerdictV1::NeedsDissection) => {
                    use kaspa_consensus_core::palw_shard_court_v1::{
                        PALW_SHARD_COURT_MLDSA87_ACCUSE_CONTEXT, palw_shard_court_session_id_v1,
                    };
                    let mut accusation = evidence.into_accusation_v1(
                        duty.claim_id,
                        duty.execution_root,
                        duty.trace_root,
                        duty.executor_bond,
                        duty.seat_bond,
                    );
                    if let Err(e) = accusation.validate_shape(ladder) {
                        warn!("[{PALW_PANEL}] claim {}: the accusation at leaf {leaf} is refused locally ({e})", duty.claim_id);
                        return None;
                    }
                    let session_id = palw_shard_court_session_id_v1(domain.as_byte_slice(), &accusation);
                    accusation.signature = self.sign(session_id.as_byte_slice(), PALW_SHARD_COURT_MLDSA87_ACCUSE_CONTEXT)?;
                    let object = PalwConsensusObjectV2::ShardCourtAccused { accusation: Box::new(accusation) };
                    if let Err(why) = kaspa_consensus_core::palw_lifecycle_objects_v2::palw_lifecycle_object_may_ride_v2(&object) {
                        warn!("[{PALW_PANEL}] claim {}: the accusation at leaf {leaf} cannot ride a carrier ({why})", duty.claim_id);
                        return None;
                    }
                    info!(
                        "[{PALW_PANEL}] claim {}: accusing leaf {leaf} in the one-move court on the executor's own evidence \
                         (session {session_id}) — ADR-0111's fast path",
                        duty.claim_id
                    );
                    self.leaf_pursuits
                        .lock()
                        .unwrap()
                        .entry(duty.claim_id)
                        .or_insert(LeafPursuitV1 { leaf, asked_daa: None, demanded: false, closed: false })
                        .closed = true;
                    return Some((session_id, object, true));
                }
                Ok(PalwShardCourtVerdictV1::FalseAccusation) => {
                    warn!(
                        "[{PALW_PANEL}] claim {}: the executor's evidence for leaf {leaf} recomputes — this seat's replay and the court \
                         disagree about a leaf whose inputs they share, which is a determinism fault, not the claim's; nothing filed",
                        duty.claim_id
                    );
                    self.leaf_pursuits
                        .lock()
                        .unwrap()
                        .entry(duty.claim_id)
                        .or_insert(LeafPursuitV1 { leaf, asked_daa: None, demanded: false, closed: false })
                        .closed = true;
                    return None;
                }
                Err(e) => {
                    info!(
                        "[{PALW_PANEL}] claim {}: the evidence served for leaf {leaf} does not adjudicate ({e}) — not an answer",
                        duty.claim_id
                    );
                }
            }
        }
        // 2. and 3. Ask once, then demand once.
        let pursuit = {
            let mut pursuits = self.leaf_pursuits.lock().unwrap();
            if pursuits.len() >= Self::LEAF_PURSUITS_CAP && !pursuits.contains_key(&duty.claim_id) {
                pursuits.clear();
            }
            *pursuits.entry(duty.claim_id).or_insert(LeafPursuitV1 { leaf, asked_daa: None, demanded: false, closed: false })
        };
        let Some(asked) = pursuit.asked_daa else {
            if self.request_leaf_evidence_v1(network_domain, duty.claim_id, index, leaf, current_daa).await {
                info!(
                    "[{PALW_PANEL}] claim {}: asked the executor for the evidence of leaf {leaf} (interval {interval}, index {index:#x}) \
                     — ADR-0111's fast path",
                    duty.claim_id
                );
                if let Some(p) = self.leaf_pursuits.lock().unwrap().get_mut(&duty.claim_id) {
                    p.asked_daa = Some(current_daa);
                }
            }
            return None;
        };
        let patience = asked.saturating_add(lev::PALW_LEAF_EVIDENCE_FAST_PATH_DAA_V1);
        let held_court = self.consensus_config.params.palw_held_context_active_at(current_daa)
            && crate::palw_producer::palw_da_court_in_force_v1(&self.consensus_config, current_daa);
        if pursuit.demanded || current_daa < patience || !held_court {
            return None;
        }
        use kaspa_consensus_core::palw_held_da_v1::{
            PALW_HELD_DA_MLDSA87_ACCUSE_CONTEXT, PALW_HELD_DA_VERSION_V1, PalwHeldAccusationV1, PalwHeldMissingV1,
            palw_held_da_accusation_message_v1,
        };
        let mut demand = PalwHeldAccusationV1 {
            version: PALW_HELD_DA_VERSION_V1,
            claim: duty.claim_id,
            missing: PalwHeldMissingV1::StepLeaf { leaf },
            accuser: duty.seat_bond,
            binding,
            signature: Vec::new(),
        };
        let message = palw_held_da_accusation_message_v1(domain.as_byte_slice(), &demand);
        demand.signature = self.sign(message.as_byte_slice(), PALW_HELD_DA_MLDSA87_ACCUSE_CONTEXT)?;
        let object = PalwConsensusObjectV2::DefaultAccusedHeld { accusation: Box::new(demand) };
        info!(
            "[{PALW_PANEL}] claim {}: no evidence of leaf {leaf} {} DAA after asking — demanding it on chain (ADR-0111 Decision 3)",
            duty.claim_id,
            current_daa.saturating_sub(asked)
        );
        if let Some(p) = self.leaf_pursuits.lock().unwrap().get_mut(&duty.claim_id) {
            p.demanded = true;
        }
        Some((message, object, false))
    }

    /// **RFC-0007 §II.8, the seat's ask for failed blocks**: one signed request per block on the interval lane, registered with the gossip center
    /// first so the answer is admitted. The signature is the lane's leaf-request signature over `(claim, index, root tag)`.
    async fn request_weight_blocks_v1(
        &self,
        network_domain: Hash64,
        claim: Hash64,
        artifact_root: Hash64,
        requests: &[(u32, misaka_palw_tir_sketch::refetch::TirBlockAddressV1)],
        requested_daa: u64,
    ) -> usize {
        let Some(kp) = self.keypair.as_ref() else { return 0 };
        let tag = kaspa_consensus_core::palw_weight_block_v1::palw_weight_block_root_tag_v1(&artifact_root);
        let mut asked = 0usize;
        for (index, _) in requests {
            let Some(signature) =
                crate::palw_fp_seat::palw_fp_sign_leaf_request_v1(&kp.signing_key, network_domain, claim, *index, tag, requested_daa)
            else {
                continue;
            };
            self.flow_context.palw_gossip().note_interval_pull_request(claim, *index);
            self.flow_context
                .request_palw_interval_opening(
                    claim,
                    *index,
                    kp.verification_key.as_ref().to_vec(),
                    signature,
                    requested_daa,
                    Some(tag),
                )
                .await;
            asked += 1;
        }
        asked
    }

    /// **RFC-0007 §II.7, one tick of the witness fetches**: each pending claim asks the producer for its witness chunks (once), reads the pool, and when the
    /// chunks are in decodes the witness and runs the sketch checker beside the replay (`mirror_served_v1`); a refusal at a weight product is picked up
    /// by the refetch tick that follows. A chunk nobody served by the patience is named in the log by its manifest index.
    async fn witness_fetch_tick_v1(&self, openings: &HashMap<(Hash64, u32), Vec<Vec<u8>>>, network_domain: Hash64, daa: u64) {
        let Some(sketch) = self.sketch.clone() else { return };
        let claims: Vec<Hash64> = self.witness_fetches.lock().unwrap().keys().copied().collect();
        for claim in claims {
            let Some(mut fetch) = self.witness_fetches.lock().unwrap().remove(&claim) else { continue };
            match fetch.step(openings, daa) {
                refetch::WitnessStepV1::Ask(indices) => {
                    let asked = self.request_fp_interval_openings(network_domain, claim, &indices, daa).await;
                    info!("[{PALW_PANEL}] claim {claim}: asked for {asked} witness chunk(s) (RFC-0007 §II.7)");
                    self.witness_fetches.lock().unwrap().insert(claim, fetch);
                }
                refetch::WitnessStepV1::Waiting => {
                    self.witness_fetches.lock().unwrap().insert(claim, fetch);
                }
                refetch::WitnessStepV1::Unavailable { chunk_index } => warn!(
                    "[{PALW_PANEL}] claim {claim}: UNAVAILABLE — witness chunk {chunk_index} of the manifest was not served; the served witness is not \
                     checked (the replay stands, RFC-0007 §II.7)"
                ),
                refetch::WitnessStepV1::Ready(image) => {
                    let Some(entry) = self.backends().tir_entry_v1(fetch.class_id, fetch.artifact_root) else { continue };
                    let (sketch, prompt, decode, reproduces) =
                        (sketch.clone(), fetch.prompt.clone(), fetch.decode, fetch.replay_reproduces);
                    tokio::task::spawn_blocking(move || {
                        match misaka_palw_tir_sketch::codec::decode(&image) {
                            Ok(witness) => {
                                if let Err(why) = sketch.mirror_served_v1(&entry, claim, &prompt, decode, &witness, reproduces, daa) {
                                    warn!("[{PALW_PANEL}] claim {claim}: the served witness did not check ({why})");
                                }
                            }
                            Err(why) => warn!(
                                "[{PALW_PANEL}] claim {claim}: the served witness is refused before any check — it does not decode ({why}); the witness is wrong, \
                                 not the claim (RFC-0007 §II.7)"
                            ),
                        };
                    });
                }
            }
        }
    }

    /// **RFC-0007 §II.8, one tick of the refetches**: pursuits are opened from the refused served witnesses the sketch service holds, stepped with
    /// the interval pool, and concluded — an accusation is recorded as a fault at its named leaf (the existing IR court takes it up), a cleared
    /// check and a withheld block are logged by name.
    async fn weight_refetch_tick_v1(&self, openings: &HashMap<(Hash64, u32), Vec<Vec<u8>>>, network_domain: Hash64, daa: u64) {
        let Some(sketch) = self.sketch.clone() else { return };
        for refused in sketch.take_refused_served_v1() {
            let Some(entry) = self.backends().tir_entry_v1(refused.class_id, refused.artifact_root) else { continue };
            let mut open = self.weight_refetch.lock().unwrap();
            if open.len() >= refetch::REFETCH_PURSUITS_CAP_V1 && !open.contains_key(&refused.claim) {
                continue;
            }
            let pursuit = refetch::WeightRefetchV1::new(refused.claim, refused.artifact_root, refused.failure.clone());
            open.entry(refused.claim).or_insert((pursuit, entry, std::sync::Arc::new(refused)));
        }
        let claims: Vec<Hash64> = self.weight_refetch.lock().unwrap().keys().copied().collect();
        for claim in claims {
            let Some((mut pursuit, entry, refused)) = self.weight_refetch.lock().unwrap().remove(&claim) else { continue };
            let root = pursuit.artifact_root;
            let (sketch_for_step, refused_for_step, entry_for_step, pool) =
                (sketch.clone(), refused.clone(), entry.clone(), openings.clone());
            let stepped = tokio::task::spawn_blocking(move || {
                let step = pursuit.step(&entry_for_step, &pool, daa, &|transport, failure| match sketch_for_step.escalate_v1(
                    &entry_for_step,
                    &refused_for_step,
                    failure,
                    transport,
                    daa,
                ) {
                    Ok(outcome) => outcome,
                    Err(why) => misaka_palw_tir_sketch::TirEscalationV1::Inconclusive(why),
                });
                (pursuit, step)
            })
            .await;
            let Ok((pursuit, step)) = stepped else { continue };
            match step {
                refetch::RefetchStepV1::Ask(requests) => {
                    let asked = self.request_weight_blocks_v1(network_domain, claim, root, &requests, daa).await;
                    info!("[{PALW_PANEL}] claim {claim}: asked for {asked} weight block(s) of the failed check (RFC-0007 §II.8)");
                    self.weight_refetch.lock().unwrap().insert(claim, (pursuit, entry, refused));
                }
                refetch::RefetchStepV1::Waiting => {
                    self.weight_refetch.lock().unwrap().insert(claim, (pursuit, entry, refused));
                }
                refetch::RefetchStepV1::Done(outcome) => match outcome {
                    misaka_palw_tir_sketch::TirEscalationV1::Accuse { pos, node, slot, .. } => {
                        warn!(
                            "[{PALW_PANEL}] claim {claim}: the failed check is confirmed — position {pos}, node {node}: the first committed row the \
                             seat derives differently is leaf {slot}; recorded as this seat's fault for the IR court (RFC-0007 §II.8)"
                        );
                        self.note_seat_fault_v1(claim, u64::from(slot), 1);
                    }
                    misaka_palw_tir_sketch::TirEscalationV1::Cleared(why) => {
                        info!(
                            "[{PALW_PANEL}] claim {claim}: the failed check is cleared by the refetch ({why:?}); nothing accused (RFC-0007 §II.8)"
                        )
                    }
                    misaka_palw_tir_sketch::TirEscalationV1::Unavailable { occurrence, node, block, param } => warn!(
                        "[{PALW_PANEL}] claim {claim}: UNAVAILABLE — weight block {block:?} (param {param:?}) of node {node} in occurrence {occurrence} \
                         was not served; no Valid is filed (RFC-0007 §II.8)"
                    ),
                    other => info!("[{PALW_PANEL}] claim {claim}: the failed check could not be refetched: {other:?}"),
                },
            }
        }
    }

    /// **ADR-0111 Decision 2, the seat's ask**: one signed leaf-evidence request on the interval
    /// lane, solicited first so the answer is admitted.
    async fn request_leaf_evidence_v1(
        &self,
        network_domain: Hash64,
        claim: Hash64,
        index: u32,
        leaf: u64,
        requested_daa: u64,
    ) -> bool {
        let Some(kp) = self.keypair.as_ref() else { return false };
        let Some(signature) =
            crate::palw_fp_seat::palw_fp_sign_leaf_request_v1(&kp.signing_key, network_domain, claim, index, leaf, requested_daa)
        else {
            return false;
        };
        self.flow_context.palw_gossip().note_interval_pull_request(claim, index);
        self.flow_context
            .request_palw_interval_opening(claim, index, kp.verification_key.as_ref().to_vec(), signature, requested_daa, Some(leaf))
            .await;
        true
    }

    /// **SEAT-R: the attempt lane's replay of the anchor's job, off the loop** ([`PalwSeatReplaysV1`])
    /// — the full seat's, and a replaying partial seat's (`PalwSeatRRoleV1`). Started once per claim —
    /// reserved for its life at the full-seat need of THIS job, as the awaited replay was — and polled
    /// every tick after; a start the slots or the ledger refuse waits for a later tick rather than
    /// being spent, so a busy host defers the replay and never forfeits it. A refusal is started once
    /// more while the time it took still fits before the claim's deadline
    /// ([`PalwSeatReplaysV1::retry_refused`]), and a replay this host's timing of the class says
    /// returns after the deadline is not started ([`PalwSeatReplaysV1::fits`]). Every step but
    /// `Licensed` hands the backend back for the full seat's fault finders — `Refuted` included.
    #[allow(clippy::too_many_arguments)]
    async fn attempt_seat_replay_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        seat_r_duty: PalwSeatRDutyV1,
        current_daa: u64,
        backend: Box<dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1>,
        ctx: &kaspa_consensus_core::palw_v2::PalwJobContextV2,
        prompt: &[usize],
        replays: &mut PalwSeatReplaysV1,
    ) -> (PalwSeatReplayStepV1, Option<Box<dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1>>) {
        let key = (duty.claim_id, ctx.job_id);
        let mut poll = replays.poll(&key, current_daa).await;
        if let PalwSeatReplayPollV1::Done { result: Err(e), fresh } = &poll
            && replays.retry_refused(&key, current_daa, seat_r_duty.deadline)
        {
            if *fresh {
                warn!("[{PALW_PANEL}] claim {}: the replay refused: {e} — starting it once more (SEAT-R)", duty.claim_id);
            }
            poll = PalwSeatReplayPollV1::Absent;
        }
        match poll {
            PalwSeatReplayPollV1::Running => (PalwSeatReplayStepV1::Waiting, None),
            PalwSeatReplayPollV1::Done { result, fresh } => {
                let step = palw_seat_replay_step_v1(&result, duty.execution_root, duty.trace_root, duty.work_leaves, duty.output_root);
                match (&result, &step) {
                    (Ok(roots), PalwSeatReplayStepV1::Licensed) if fresh => info!(
                        "[{PALW_PANEL}] claim {}: licensed by replay — the anchor's job reproduces the claim's roots ({} leaves \
                         replayed, priced {}); a seat's one Valid route ({:?}, SEAT-R)",
                        duty.claim_id,
                        roots.work_leaves.map(|w| w.to_string()).unwrap_or_else(|| "unpriced".into()),
                        duty.work_leaves,
                        seat_r_duty.role
                    ),
                    (Ok(roots), _) if fresh => warn!(
                        "[{PALW_PANEL}] claim {}: the anchor's job does NOT reproduce the claim's roots (execution {} vs claimed {}, \
                         trace {} vs {}, output {:?} vs {}, work {:?} vs priced {}) — nothing licenses it here; the full seat's fault \
                         finders run on (SEAT-R, SEAT-S2)",
                        duty.claim_id,
                        roots.execution_root,
                        duty.execution_root,
                        roots.trace_root,
                        duty.trace_root,
                        roots.output_root,
                        duty.output_root,
                        roots.work_leaves,
                        duty.work_leaves
                    ),
                    (Err(e), _) if fresh => {
                        warn!("[{PALW_PANEL}] claim {}: the replay refused: {e} — no verdict from it (SEAT-R)", duty.claim_id)
                    }
                    _ => {}
                }
                // **RFC-0007 Part II: the sketch checker's mirror, beside this replay** (behind `--palw-sketch-check`, off by default).
                // Once per claim, when the replay finishes: the checker's verdict on this seat's own witness of the job is compared with
                // the replay's, off the loop, and a disagreement is an alarm in the log and in the status line.
                if fresh
                    && result.is_ok()
                    && let Some(sketch) = self.sketch.clone()
                    && let Some(entry) = self.backends().tir_entry_v1(duty.class_id, duty.artifact_root)
                {
                    let reproduced = step == PalwSeatReplayStepV1::Licensed;
                    // **RFC-0007 §II.7: and the producer's served witness, beside it** — asked for by the tick that follows, checked when its chunks
                    // are in. Not this node's own claim (it would ask itself), and only a class whose attempts commit witness chunks.
                    if self.bond != Some(duty.executor_bond.0)
                        && let Some(facts) = session.palw_producer_facts_v2(duty.class_id, None)
                        && facts.witness_chunks > 0
                    {
                        let mut pending = self.witness_fetches.lock().unwrap();
                        if pending.len() < refetch::REFETCH_PURSUITS_CAP_V1 {
                            pending.entry(duty.claim_id).or_insert_with(|| {
                                refetch::WitnessFetchV1::new(
                                    duty.claim_id,
                                    duty.class_id,
                                    duty.artifact_root,
                                    facts.witness_chunks,
                                    prompt.to_vec(),
                                    ctx.exact_decode_tokens,
                                    reproduced,
                                )
                            });
                        }
                    }
                    let (claim, prompt, decode, daa) = (duty.claim_id, prompt.to_vec(), ctx.exact_decode_tokens, current_daa);
                    tokio::task::spawn_blocking(move || {
                        if let Err(why) = sketch.mirror_replay_v1(&entry, claim, &prompt, decode, reproduced, daa) {
                            warn!("[{PALW_PANEL}] claim {claim}: the sketch mirror did not run ({why})");
                        }
                    });
                }
                let backend = (step != PalwSeatReplayStepV1::Licensed).then_some(backend);
                (step, backend)
            }
            PalwSeatReplayPollV1::Absent => {
                if !replays.fits(&duty.class_id, current_daa, seat_r_duty.deadline) {
                    crate::palw_backends::note_throttled_v1("panel-replay-late", || {
                        format!(
                            "[{PALW_PANEL}] replay of claim {} not started: this host's last replay of its class would return \
                             after the receipt deadline (DAA {}, SEAT-R)",
                            duty.claim_id, seat_r_duty.deadline
                        )
                    });
                    return (PalwSeatReplayStepV1::NoVerdict, Some(backend));
                }
                if !replays.has_room(seat_r_duty.heavy) {
                    crate::palw_backends::note_throttled_v1("panel-replay-room", || {
                        format!(
                            "[{PALW_PANEL}] replay of claim {} waits: every replay slot{} is taken",
                            duty.claim_id,
                            if seat_r_duty.heavy { " a C7 class may hold" } else { "" }
                        )
                    });
                    return (PalwSeatReplayStepV1::Waiting, None);
                }
                let need = self.backends().role_memory_need_for_backend_or_chain_v1(
                    backend.as_ref(),
                    duty.class_id,
                    duty.artifact_root,
                    Some(ctx),
                    kaspa_consensus_core::palw_resource_profile_v1::PalwResourceRoleV1::FullSeat,
                    |id| self.chain_carriage_v1(session, id),
                );
                // **F2: a big replay on a slow seat waits for the lighter work** — a 3.37 GiB replay holds the
                // share's whole budget for its life (37-55 minutes on the 5.104 seats, 5 on an idle host),
                // and every floor replay and audit behind it waits on the ledger. Held back only while lighter
                // work is waiting, only on a seat that has found the class slow, and never within
                // `PALW_SEAT_BIG_URGENT_DAA_V1` of the claim's deadline.
                //
                // **int-10.3: the class's weight is judged UNPINNED** (`total + pinned`). Pinning (int-10.2 A1) took the
                // 8k's 1.68 GiB file off the reservation (3.37 → 1.70 GiB) but not off the CPU, and the gate is about how
                // long a replay holds a slow seat — measured on 10-02, 5.104's seats stopped deferring the 8k, took it at
                // 15–30 minutes a replay on 8 shared vCPUs and filed 1–8 receipts an hour. The unpinned figure is the one
                // F2's threshold was set against.
                if replays.big_replay_deferred(
                    &duty.class_id,
                    need.total_bytes().saturating_add(need.pinned_bytes),
                    seat_r_duty.deadline,
                    current_daa,
                ) {
                    crate::palw_backends::note_throttled_v1("panel-replay-big", || {
                        format!(
                            "[{PALW_PANEL}] replay of claim {} held back: it needs {} and this seat's last replay of the class took \
                             {} DAA, while lighter replays are waiting for the same memory — it starts when they are done or {} DAA \
                             before its deadline (DAA {}) (F2)",
                            duty.claim_id,
                            need.describe(),
                            replays.timed.get(&duty.class_id).copied().unwrap_or(0),
                            crate::palw_seat_schedule::PALW_SEAT_BIG_URGENT_DAA_V1,
                            seat_r_duty.deadline
                        )
                    });
                    return (PalwSeatReplayStepV1::Waiting, None);
                }
                // **At the widest prefill run the ledger grants** (int-10.2 A2): the need above is the
                // cap's (F2's question is how big the replay wants to be); the reservation narrows this
                // duty's own instance when the ledger cannot grant that, and the instance it leaves at
                // the width reserved is the one `replays.start` runs.
                let mut backend = backend;
                let backends = self.backends();
                let (reserved, need) =
                    match self.reserve_replay_at_widest_run_v1("full-seat", backend.as_mut(), duty.class_id, duty.claim_id, |b| {
                        backends.role_memory_need_for_backend_or_chain_v1(
                            b,
                            duty.class_id,
                            duty.artifact_root,
                            Some(ctx),
                            FULL_SEAT_V1,
                            |id| self.chain_carriage_v1(session, id),
                        )
                    }) {
                        Ok(taken) => taken,
                        Err(why) => {
                            crate::palw_backends::note_throttled_v1("panel-replay-ledger", || {
                                format!("[{PALW_PANEL}] replay of claim {} deferred: {why}", duty.claim_id)
                            });
                            return (PalwSeatReplayStepV1::Waiting, None);
                        }
                    };
                info!(
                    "[{PALW_PANEL}] claim {}: replaying the anchor's job off the loop for a verdict ({:?}, deadline DAA {}, SEAT-R), \
                     reserved {}",
                    duty.claim_id,
                    seat_r_duty.role,
                    seat_r_duty.deadline,
                    need.describe()
                );
                let (ctx, prompt) = (ctx.clone(), prompt.to_vec());
                replays.start(key, duty.class_id, seat_r_duty.heavy, current_daa, Some(reserved), backend, move |b| {
                    b.execute_for_verdict(&ctx, &prompt)
                });
                (PalwSeatReplayStepV1::Waiting, None)
            }
        }
    }

    /// **SEAT-R: the free-prompt lane's replay of the claim's job, off the loop** — the full seat's,
    /// and a replaying partial seat's (`PalwSeatRRoleV1`).
    ///
    /// A served job is not the chain's to name, so the pass first sorts what this seat holds for the
    /// claim — any payload spelling, the pool's and this node's retention — into distinct jobs
    /// (keyed by the job's id), and asks of each whether it is the claim's OWN: a job one of whose
    /// `FPC1` payloads carries a capture that reproduces the claim's roots under that job's id at the
    /// claim's price. The execution root commits the job's context, so no other job can reproduce
    /// them. Asked once per job and payload count ([`PalwSeatReplaysV1::own_job`]).
    ///
    /// * **The claim's own job first, and alone** (the SEAT-R review, LOW). Its bytes are kept as the
    ///   claim's evidence (`persist_foreign_material`, write-once and bounded) the moment it is
    ///   proven, before the replay decides, and a replay of it that does not reproduce the roots is
    ///   `Refuted`. While the seat holds it no other served job is started — none can reproduce the
    ///   roots, and a stranger's `FPM1` built from the duty's public fields would otherwise take a
    ///   replay slot on all five seats; one already started is only polled, so it frees its slot.
    /// * **No job proven the claim's** (a client that ships no capture): every distinct job is
    ///   replayed once, in pool order — a stranger's junk job is one more bounded replay (the pool
    ///   keeps four payloads a claim), never a refusal of the honest one.
    ///
    /// A refusal is started once more while the time it took still fits before the claim's deadline,
    /// and no replay is started that this host's timing of the class returns after it
    /// ([`PalwSeatReplaysV1::fits`]). Returns the payload that licensed, or what the pass came to.
    async fn fp_seat_replay_pass_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        seat_r_duty: PalwSeatRDutyV1,
        current_daa: u64,
        pooled: &[Vec<u8>],
        replays: &mut PalwSeatReplaysV1,
    ) -> (PalwSeatReplayStepV1, Option<Vec<u8>>) {
        use kaspa_consensus_core::palw_freeprompt_v3::{
            PalwFpMaterialV1, fp_job_id_v3, palw_fp_capture_decode_v1, palw_fp_job_material_decode_v1, palw_fp_material_encode_v1,
            palw_fp_seat_prompt_admit_v1,
        };
        let form = self.class_prompt_ids_form(duty.class_id);
        let Ok(probe) = self.resolve_backend(session, duty.class_id, duty.artifact_root) else {
            return (PalwSeatReplayStepV1::NoVerdict, None);
        };
        // The distinct jobs this seat holds, in pool order, each with every payload that spells it.
        let disk = self.fp_retained_payload_paths(&duty.claim_id).into_iter().filter_map(|path| std::fs::read(path).ok());
        let mut jobs: Vec<(Hash64, PalwFpMaterialV1, Vec<Vec<u8>>)> = Vec::new();
        for bytes in pooled.iter().cloned().chain(disk) {
            let Some(material) = palw_fp_job_material_decode_v1(&bytes, form) else { continue };
            if material.job.class_id != duty.class_id
                || material.job.executor_bond != duty.executor_bond.0
                || !self.fp_privacy_mode_judgeable(material.job.privacy_mode)
                || palw_fp_seat_prompt_admit_v1(&material.job, Some(&material.prompt_token_ids), form).is_err()
            {
                continue;
            }
            let job_id = fp_job_id_v3(&material.job);
            match jobs.iter_mut().find(|(id, _, _)| *id == job_id) {
                Some((_, _, payloads)) => payloads.push(bytes),
                None => jobs.push((job_id, material, vec![bytes])),
            }
        }
        // Whose each job is: asked again only when a payload has arrived since a `false`.
        let mut own: Vec<bool> = Vec::with_capacity(jobs.len());
        for (job_id, _, payloads) in &jobs {
            let key = (duty.claim_id, *job_id);
            let answer = match replays.own_job(&key, payloads.len()) {
                Some(answer) => answer,
                None => {
                    let roots = PalwClaimRootsV1 {
                        execution_root: duty.execution_root,
                        trace_root: duty.trace_root,
                        anchor: *job_id,
                        attempt_draw: None,
                        output_root: Some(duty.output_root),
                        // The 3a review's L-b: the pin the claim RECORDED (chain state, never the
                        // material), so a capture of another job under this id is not its own.
                        job_pin: duty.fp_job_pin_v1(),
                    };
                    let proof = payloads.iter().find(|bytes| {
                        palw_fp_capture_decode_v1(bytes, form).is_some_and(|payload| {
                            probe.verify_material(&payload.capture, roots) == PalwMaterialVerdictV1::Matches
                                && probe.capture_shape(&payload.capture).is_some_and(|shape| {
                                    kaspa_consensus_core::palw_backend::palw_opening_is_at_the_claims_price_v1(
                                        shape.step_leaf_count,
                                        duty.work_leaves,
                                    )
                                })
                        })
                    });
                    // The claim's evidence, kept before any replay decides.
                    if let Some(bytes) = proof {
                        self.persist_foreign_material(&duty.claim_id, bytes);
                    }
                    replays.note_own_job(key, proof.is_some(), payloads.len());
                    proof.is_some()
                }
            };
            own.push(answer);
        }
        let holds_own = own.iter().any(|own| *own);
        let mut order: Vec<usize> = (0..jobs.len()).collect();
        order.sort_by_key(|i| !own[*i]);
        let mut waiting = false;
        for index in order {
            let (job_id, material, _) = &jobs[index];
            let is_own = own[index];
            // Whether this job's replay can decide the claim: the claim's own, or any while none is.
            let decides = is_own || !holds_own;
            let key = (duty.claim_id, *job_id);
            let mut poll = replays.poll(&key, current_daa).await;
            if decides
                && let PalwSeatReplayPollV1::Done { result: Err(e), fresh } = &poll
                && replays.retry_refused(&key, current_daa, seat_r_duty.deadline)
            {
                if *fresh {
                    warn!(
                        "[{PALW_PANEL}] free-prompt replay for claim {} refused: {e} — starting it once more (SEAT-R)",
                        duty.claim_id
                    );
                }
                poll = PalwSeatReplayPollV1::Absent;
            }
            match poll {
                PalwSeatReplayPollV1::Running => waiting |= decides,
                PalwSeatReplayPollV1::Done { result: Ok(replayed), fresh } => {
                    let step = palw_seat_replay_step_v1(
                        &Ok(replayed),
                        duty.execution_root,
                        duty.trace_root,
                        duty.work_leaves,
                        duty.output_root,
                    );
                    if step == PalwSeatReplayStepV1::Licensed {
                        if fresh {
                            info!(
                                "[{PALW_PANEL}] claim {}: licensed by replay — the job reproduces the claim's roots and answer at its \
                                 price ({:?} leaves); a seat's one Valid route ({:?}, SEAT-R)",
                                duty.claim_id, replayed.work_leaves, seat_r_duty.role
                            );
                        }
                        // What is kept of a licence is the job it licensed, in its job-only spelling
                        // (`FPM1`): never a served payload's `FPC1` whose capture nothing checked — a
                        // peer racing the producer's gossip can plant one of the right job with a
                        // garbage capture, and a covering signer then answered its DA session from it
                        // (the P2-7 review's HIGH). A verified `FPC1` of this job is kept already
                        // (`proof`, above; the directory is write-once), and R-core's answer re-makes
                        // the capture from this one (`palw_da_material_v1`).
                        return (
                            PalwSeatReplayStepV1::Licensed,
                            Some(palw_fp_material_encode_v1(&material.job, &material.prompt_token_ids)),
                        );
                    }
                    if fresh {
                        warn!(
                            "[{PALW_PANEL}] claim {}: a served job's replay does not reproduce the claim's roots (execution {} vs {}, \
                             trace {} vs {}, output {:?} vs {}, work {:?} vs priced {}){}",
                            duty.claim_id,
                            replayed.execution_root,
                            duty.execution_root,
                            replayed.trace_root,
                            duty.trace_root,
                            replayed.output_root,
                            duty.output_root,
                            replayed.work_leaves,
                            duty.work_leaves,
                            if is_own { " — it is the claim's own job: nothing licenses the claim here" } else { "" }
                        );
                    }
                    // SEAT-S2: an answer the replay cannot name refutes nothing.
                    if is_own && step == PalwSeatReplayStepV1::Refuted {
                        return (PalwSeatReplayStepV1::Refuted, None);
                    }
                }
                PalwSeatReplayPollV1::Done { result: Err(e), fresh } => {
                    if fresh {
                        warn!("[{PALW_PANEL}] free-prompt replay for claim {} refused: {e} (SEAT-R)", duty.claim_id);
                    }
                }
                // Never a stranger's job beside the claim's own.
                PalwSeatReplayPollV1::Absent if !decides => {}
                PalwSeatReplayPollV1::Absent => {
                    if !replays.fits(&duty.class_id, current_daa, seat_r_duty.deadline) {
                        crate::palw_backends::note_throttled_v1("panel-replay-late", || {
                            format!(
                                "[{PALW_PANEL}] replay of claim {} not started: this host's last replay of its class would return \
                                 after the receipt deadline (DAA {}, SEAT-R)",
                                duty.claim_id, seat_r_duty.deadline
                            )
                        });
                        continue;
                    }
                    waiting = true;
                    if !replays.has_room(seat_r_duty.heavy) {
                        crate::palw_backends::note_throttled_v1("panel-replay-room", || {
                            format!(
                                "[{PALW_PANEL}] replay of claim {} waits: every replay slot{} is taken",
                                duty.claim_id,
                                if seat_r_duty.heavy { " a C7 class may hold" } else { "" }
                            )
                        });
                        continue;
                    }
                    let Ok(mut backend) = self.resolve_backend(session, duty.class_id, duty.artifact_root) else {
                        return (PalwSeatReplayStepV1::NoVerdict, None);
                    };
                    let Some(prompt_ids) = Self::fp_prompt_for_job(backend.as_ref(), material, form) else { continue };
                    let ctx = backend.fp_job_context_v1(&material.job);
                    // At the widest prefill run the ledger grants, on this duty's own instance (int-10.2 A2).
                    let backends = self.backends();
                    let (reserved, need) =
                        match self.reserve_replay_at_widest_run_v1("full-seat", backend.as_mut(), duty.class_id, duty.claim_id, |b| {
                            backends.role_memory_need_for_backend_or_chain_v1(
                                b,
                                duty.class_id,
                                duty.artifact_root,
                                ctx.as_ref(),
                                FULL_SEAT_V1,
                                |id| self.chain_carriage_v1(session, id),
                            )
                        }) {
                            Ok(taken) => taken,
                            Err(why) => {
                                crate::palw_backends::note_throttled_v1("panel-replay-ledger", || {
                                    format!("[{PALW_PANEL}] replay of claim {} deferred: {why}", duty.claim_id)
                                });
                                continue;
                            }
                        };
                    info!(
                        "[{PALW_PANEL}] claim {}: replaying {} off the loop for a verdict ({:?}, deadline DAA {}, SEAT-R), reserved {}",
                        duty.claim_id,
                        if is_own { "the claim's own job" } else { "a served job" },
                        seat_r_duty.role,
                        seat_r_duty.deadline,
                        need.describe()
                    );
                    let job = material.job.clone();
                    let prompt: Vec<usize> = prompt_ids.iter().map(|t| *t as usize).collect();
                    replays.start(key, duty.class_id, seat_r_duty.heavy, current_daa, Some(reserved), backend, move |b| {
                        // SEAT-S2: the free-prompt run's own output root — the family's rule over the ids
                        // this replay generated, under the executed context (the one rule the lane's
                        // commitment and `fp_committed_output_ids_v1` both use).
                        b.execute_free_prompt(&job, &prompt).map(|run| kaspa_consensus_core::palw_backend::PalwReplayRootsV1 {
                            execution_root: run.outcome.execution_root,
                            trace_root: run.facts.full_logits_trace_root,
                            work_leaves: Some(run.facts.step_leaf_count),
                            output_root: Some(run.outcome.output_root),
                        })
                    });
                }
            }
        }
        // Nothing held, every deciding job refused or late, or every one replayed and none the claim's.
        if waiting { (PalwSeatReplayStepV1::Waiting, None) } else { (PalwSeatReplayStepV1::NoVerdict, None) }
    }

    /// **SEAT-S4 past SEAT-R, one tick** ([`PalwSeatResumesV1`]): the C7 partial seat's resume of its
    /// own mask from served openings, each replayed off the loop in the SEAT-R slots under its own
    /// ledger reservation — the partial seat's figure priced as the streamed fold it is
    /// (`palw_partial_seat_streamed_need_v1`, the review's M3) — and the named openings asked for
    /// again at the tail's pace when a segment has none left to try.
    #[allow(clippy::too_many_arguments)]
    async fn seat_s4_resume_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        seat_r_duty: PalwSeatRDutyV1,
        current_daa: u64,
        network_domain: Hash64,
        ctx: &kaspa_consensus_core::palw_v2::PalwJobContextV2,
        prompt: &[usize],
        openings: &mut HashMap<(Hash64, u32), Vec<Vec<u8>>>,
        requested_intervals: &mut HashMap<(Hash64, u32), u64>,
        replays: &mut PalwSeatReplaysV1,
        resumes: &mut PalwSeatResumesV1,
    ) -> PalwSeatResumeStepV1 {
        let seats = duty.panel_seat_count.max(1);
        let assignment =
            kaspa_consensus_core::palw_verification_v2::palw_segment_assignment_v2(duty.panel_anchor, duty.claim_id, seats);
        let claim = PalwSeatResumeClaimV1 {
            claim: duty.claim_id,
            job_id: ctx.job_id,
            seat_count: seats,
            mask: assignment.mask_of(duty.seat_index as u16),
            now_daa: current_daa,
        };
        let step = resumes
            .step(&claim, openings, replays, |replays, key, segment, opening| {
                // A segment is at most the whole job: one this host's last whole replay of the class
                // says cannot return by the deadline is not started (it would hold the C7 slot, detached,
                // long after the chain stopped taking the receipt).
                if !replays.fits(&duty.class_id, current_daa, seat_r_duty.deadline) {
                    crate::palw_backends::note_throttled_v1("panel-segment-late", || {
                        format!(
                            "[{PALW_PANEL}] claim {} segment {segment}: not started — this host's last replay of the class would \
                             return after the receipt deadline (DAA {}, SEAT-S4)",
                            duty.claim_id, seat_r_duty.deadline
                        )
                    });
                    return false;
                }
                if !replays.has_room(seat_r_duty.heavy) {
                    crate::palw_backends::note_throttled_v1("panel-segment-room", || {
                        format!("[{PALW_PANEL}] claim {} segment {segment}: the resume waits — every replay slot is taken", duty.claim_id)
                    });
                    return false;
                }
                let Ok(mut backend) = self.resolve_backend(session, duty.class_id, duty.artifact_root) else { return false };
                // At the widest prefill run the ledger grants, on this duty's own instance (int-10.2 A2).
                let backends = self.backends();
                let partial = kaspa_consensus_core::palw_resource_profile_v1::PalwResourceRoleV1::PartialSeat { seat_count: seats, segment_index: segment };
                let reserved = match self.reserve_replay_at_widest_run_v1("partial-seat", backend.as_mut(), duty.class_id, duty.claim_id, |b| {
                    crate::palw_backends::palw_partial_seat_streamed_need_v1(backends.role_memory_need_for_backend_or_chain_v1(
                        b,
                        duty.class_id,
                        duty.artifact_root,
                        Some(ctx),
                        partial,
                        |id| self.chain_carriage_v1(session, id),
                    ))
                }) {
                    Ok((reserved, _)) => reserved,
                    Err(why) => {
                        crate::palw_backends::note_throttled_v1("panel-segment-ledger", || {
                            format!("[{PALW_PANEL}] claim {} segment {segment}: the resume waits — {why}", duty.claim_id)
                        });
                        return false;
                    }
                };
                info!(
                    "[{PALW_PANEL}] claim {}: resuming segment {segment} off the loop from a served opening (SEAT-S4, deadline DAA {})",
                    duty.claim_id, seat_r_duty.deadline
                );
                let segment_claim = kaspa_consensus_core::palw_segment_resume_v1::PalwSegmentClaimV1 {
                    execution_root: duty.execution_root,
                    trace_root: duty.trace_root,
                    seat_count: seats,
                    segment_index: segment,
                };
                let (ctx, prompt) = (ctx.clone(), prompt.to_vec());
                replays.start_segment(key, duty.class_id, seat_r_duty.heavy, current_daa, Some(reserved), backend, move |b| {
                    // Whose an `Err` is — the opening's, or this host's (finding 1) — as the family names it.
                    b.replay_segment_from_checkpoint_v1(&ctx, &prompt, &opening, segment_claim)
                        .map(|replay| replay.matches)
                        .map_err(palw_seat_s4_refusal_v1)
                });
                true
            })
            .await;
        if let PalwSeatResumeStepV1::Starved { missing, .. } = &step {
            let reask_daa = seat_reask_daa_v1(seat_r_duty.deadline.saturating_sub(duty.bound_daa));
            let fresh: Vec<u32> = missing
                .iter()
                .copied()
                .filter(|i| requested_intervals.get(&(duty.claim_id, *i)).is_none_or(|at| current_daa >= at.saturating_add(reask_daa)))
                .collect();
            if !fresh.is_empty() {
                for i in &fresh {
                    requested_intervals.insert((duty.claim_id, *i), current_daa);
                }
                self.request_fp_interval_openings(network_domain, duty.claim_id, &fresh, current_daa).await;
            }
        }
        step
    }

    /// **A free-prompt seat's job and context for the claim it judges** (the audit's SEAT-S review,
    /// L2): the job the answer's ids bound under — the claim's own, with certainty, since the committed
    /// `output_root` is built over the job's context — at the count the answer's length names
    /// ([`Self::fp_committed_answer_v1`]). Never the job's ceiling, which is every early-stopping
    /// claim's wrong context.
    ///
    /// **Only the answer's job** (the second pass, finding 1). A held job the answer did not
    /// authenticate — the first pooled `FPM1` of the duty's class and executor, priced at the claim's
    /// `work_leaves` — is anybody's to build from the duty's public fields and the claim's shape: under
    /// a stranger's job the family refuses the producer's honest opening (`NotTheSeatsJob`), the route
    /// dropped it and the seat, unserved, accused the producer at `X_ASK`. Holding no answer, the seat
    /// asks for the claim's material (the answer envelope carries the ids) and resumes nothing.
    fn fp_seat_job_v1(
        &self,
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        held: &[Vec<u8>],
    ) -> Option<(kaspa_consensus_core::palw_freeprompt_v3::PalwFpMaterialV1, kaspa_consensus_core::palw_v2::PalwJobContextV2)> {
        let (material, ids) = self.fp_committed_answer_v1(backend, duty, held)?;
        let ctx = backend.fp_job_context_for_executed_v1(&material.job, ids.len().min(u32::MAX as usize) as u32)?;
        // **The job the claim RECORDED, not only the one its answer authenticates** (the M2 Phase 3
        // review's H-2): a producer that commits job J, executes a same-shaped J′ and commits J′'s
        // roots serves J′'s material, whose answer authenticates — and a seat resuming under J′'s
        // context would sign a Valid that J1-FP (`AnyValid`) convicts. The claim's pin
        // (`palw_fp_job_pin_v1(commitment)`, read off chain state as the duty's `job_identity`) must be
        // the context's own. `None` — no pin recorded (below `palw_offence_attribution`) — is the old path.
        if let Some(pin) = duty.fp_job_pin_v1()
            && kaspa_consensus_core::palw_fp_execution_v3::palw_fp_job_pin_of_context_v1(&ctx) != pin
        {
            return None;
        }
        Some((material, ctx))
    }

    /// **N-5: whether a licence already stands for `claim` in this node's receipt pools** — one of
    /// the three doors the collector assembles (`palw_v2_receipt_coverage_assemble`,
    /// `palw_v2_optimistic_assemble`, `palw_v2_receipt_quorum_assemble`) answering over what this
    /// node holds. A seat holding no verified material then files its `Unavailable` at once rather
    /// than at the material wait's cap: the claim is about to leave `PanelBound`, and with it the
    /// duty that could carry the receipt. Asked only while such a seat waits, and only when the
    /// pools hold two receipts or more.
    fn palw_licence_stands_v1(
        session: &kaspa_consensusmanager::ConsensusProxy,
        claim: Hash64,
        v2: &crate::palw_receipt_pool::PalwReceiptPoolV1<PalwSeatReceiptV2>,
        v3: &crate::palw_receipt_pool::PalwReceiptPoolV1<PalwSeatReceiptV3>,
        facts: &crate::palw_receipt_pool::ReceiptChainFactsV1,
    ) -> bool {
        let (whole, segmented) = (v2.candidates(&claim, facts), v3.candidates(&claim, facts));
        if whole.len() + segmented.len() < 2 {
            return false;
        }
        session.palw_v2_receipt_coverage_assemble(claim, segmented.clone()).is_some()
            || session.palw_v2_optimistic_assemble(claim, segmented).is_some()
            || session.palw_v2_receipt_quorum_assemble(claim, whole).is_some()
    }

    /// **ADR-0152 Q-7: start this seat's S3 sampling of a claim, off the loop** — the `Sampled` route
    /// (`palw_seat_sampled_due_v1` decides when; `palw_seat_s3_sample_v1` is the sampling). `Ok(None)`:
    /// this node holds no capture of the claim's to sample. `Err(())`: the memory ledger refused — the
    /// sampling replays a segment per site, so it reserves the partial seat's need of the longest
    /// segment for its life, as SEAT-S4's resume does for one segment, and a later tick may fit.
    fn seat_s3_sampling_start_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        network_domain: Hash64,
        pooled: &[Vec<u8>],
    ) -> Result<Option<tokio::task::JoinHandle<PalwSeatS3SampleV1>>, ()> {
        let Ok(mut backend) = self.resolve_backend(session, duty.class_id, duty.artifact_root) else { return Ok(None) };
        let captures = self.seat_s3_captures_v1(session, backend.as_ref(), duty, network_domain, pooled);
        if captures.is_empty() {
            return Ok(None);
        }
        let seats = duty.panel_seat_count.max(1);
        let last = kaspa_consensus_core::palw_verification_v2::palw_segment_count_v2(seats).saturating_sub(1);
        // At the widest prefill run the ledger grants, on this duty's own instance (int-10.2 A2).
        let backends = self.backends();
        let partial =
            kaspa_consensus_core::palw_resource_profile_v1::PalwResourceRoleV1::PartialSeat { seat_count: seats, segment_index: last };
        let reserved = match self.reserve_replay_at_widest_run_v1("s3-sampler", backend.as_mut(), duty.class_id, duty.claim_id, |b| {
            backends.role_memory_need_for_backend_or_chain_v1(b, duty.class_id, duty.artifact_root, None, partial, |id| {
                self.chain_carriage_v1(session, id)
            })
        }) {
            Ok((reserved, _)) => reserved,
            Err(why) => {
                crate::palw_backends::note_throttled_v1("panel-s3-ledger", || {
                    format!("[{PALW_PANEL}] claim {}: the S3 sampling waits — {why}", duty.claim_id)
                });
                return Err(());
            }
        };
        let (anchor, claim, seat_index) = (duty.panel_anchor, duty.claim_id, duty.seat_index as u16);
        Ok(Some(tokio::task::spawn_blocking(move || {
            let _held_for_the_sampling = reserved;
            captures
                .iter()
                .map(|(capture, roots)| palw_seat_s3_sample_v1(backend.as_ref(), capture, *roots, anchor, claim, seat_index, seats))
                .find(|sampled| *sampled != PalwSeatS3SampleV1::Unchecked)
                .unwrap_or(PalwSeatS3SampleV1::Unchecked)
        })))
    }

    /// **The captures this node holds of a claim, each with the roots SEAT-S3 checks it against**
    /// (ADR-0152 PE-3): the claim's committed roots and the job the claim answered — for an attempt,
    /// the anchor its block derives and ADR-0117's draw at the block's height, the same pair the
    /// material arms verify under; for a free-prompt claim, its job's own id, off a `FPC1` payload of
    /// the claim's class and executor. From the pool and this node's retention; at most
    /// [`PALW_SEAT_S3_CAPTURES_V1`]. Nothing is trusted here — `palw_seat_s3_sample_v1` verifies each
    /// before it reads a byte of its shape.
    fn seat_s3_captures_v1(
        &self,
        session: &kaspa_consensusmanager::ConsensusProxy,
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        network_domain: Hash64,
        pooled: &[Vec<u8>],
    ) -> Vec<(Vec<u8>, PalwClaimRootsV1)> {
        let roots = |anchor: Hash64, attempt_draw: Option<bool>| PalwClaimRootsV1 {
            execution_root: duty.execution_root,
            trace_root: duty.trace_root,
            anchor,
            attempt_draw,
            output_root: Some(duty.output_root),
            // H-2 (M2 Phase 3) on SEAT-S3's path too: a free-prompt capture signs a `Sampled` only if
            // its context reproduces the claim's recorded pin; `None` for an attempt.
            job_pin: duty.fp_job_pin_v1(),
        };
        if duty.free_prompt {
            let form = self.class_prompt_ids_form(duty.class_id);
            let disk = self.fp_retained_payload_paths(&duty.claim_id).into_iter().filter_map(|path| std::fs::read(path).ok());
            return pooled
                .iter()
                .cloned()
                .chain(disk)
                .filter_map(|bytes| {
                    let payload = kaspa_consensus_core::palw_freeprompt_v3::palw_fp_capture_decode_v1(&bytes, form)?;
                    let job = &payload.material.job;
                    (job.class_id == duty.class_id && job.executor_bond == duty.executor_bond.0).then(|| {
                        let anchor = kaspa_consensus_core::palw_freeprompt_v3::fp_job_id_v3(job);
                        (payload.capture.clone(), roots(anchor, None))
                    })
                })
                .take(PALW_SEAT_S3_CAPTURES_V1)
                .collect();
        }
        let Some(anchor) =
            self.job_anchor_for_claim(session, backend, network_domain, duty.accepted_block, duty.class_id, &duty.executor_bond)
        else {
            return Vec::new();
        };
        let claim_roots = roots(anchor, self.attempt_draw_for_claim(session, duty.accepted_block));
        let disk = [
            self.retained_capture(&duty.claim_id),
            std::fs::read(self.config.retention_dir.join("foreign").join(format!("{}.material", duty.claim_id))).ok(),
        ];
        pooled
            .iter()
            .cloned()
            .chain(disk.into_iter().flatten())
            .take(PALW_SEAT_S3_CAPTURES_V1)
            .map(|bytes| (bytes, claim_roots))
            .collect()
    }

    /// ADR-0133 S1/S3: a partial seat resumes assigned segments (or S3 sites) from published
    /// checkpoints. Only the designated full-replay seat returns `FullReplay`. A partial seat
    /// that cannot open waits; it does not walk the job from genesis.
    ///
    /// **Past SEAT-R a partial seat's resume abstains here** (`Abstain`), before S3 or S1 reads a
    /// byte — the audit's SEAT-S review, C1: S3 attested the whole mask from a pooled capture nothing
    /// checked against the claim, and `replay_layer_site_v3` leaves that check to its caller. A
    /// replaying partial seat has already run the whole replay by then, and a C7 partial seat takes
    /// SEAT-S4's verified route (`seat_s4_resume_v1`), which reads no pooled capture and samples no
    /// site. Below SEAT-R this path is what it was, byte for byte.
    #[allow(clippy::too_many_arguments)]
    async fn palw_v2_try_partial_resume_v1(
        &self,
        duty: &kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2,
        backend: &dyn kaspa_consensus_core::palw_backend::PalwExecutionBackendV1,
        job: &kaspa_consensus_core::palw_v2::PalwJobContextV2,
        prompt: &[usize],
        current_daa: u64,
        network_domain: Hash64,
        held: &[Vec<u8>],
        openings: &HashMap<(Hash64, u32), Vec<Vec<u8>>>,
        requested_intervals: &mut HashMap<(Hash64, u32), u64>,
    ) -> PalwV2SeatPathV1 {
        use kaspa_consensus_core::palw_layer_sample_v3::{PALW_LAYER_SAMPLE_V3_SITES, palw_layer_sample_v3};
        use kaspa_consensus_core::palw_segment_resume_v1::palw_segment_opening_request_index_v1;
        use kaspa_consensus_core::palw_verification_v2::{palw_segment_assignment_v2, palw_segment_count_v2};
        let seats = duty.panel_seat_count.max(1);
        let assignment = palw_segment_assignment_v2(duty.panel_anchor, duty.claim_id, seats);
        if duty.seat_index as u16 == assignment.full_seat {
            return PalwV2SeatPathV1::FullReplay;
        }
        // SEAT-R (and SEAT-S3 with it): the served opening and the pooled capture are bound to
        // nothing the claim committed, so neither the S3 sites nor the S1 segments are a licence.
        if palw_seat_r_in_force_v1(&self.consensus_config.params, current_daa) {
            return PalwV2SeatPathV1::Abstain;
        }
        let mask = assignment.mask_of(duty.seat_index as u16);
        let capture = held.iter().find(|bytes| {
            backend.open_segment_checkpoint_v1(bytes, seats, 0).is_ok()
                || kaspa_consensus_core::palw_freeprompt_v3::palw_fp_capture_decode_v1(
                    bytes,
                    self.class_prompt_ids_form(duty.class_id),
                )
                .is_some()
        });
        if self.consensus_config.params.palw_verification_s3_at(current_daa)
            && let Some(bytes) = capture
        {
            let shape = backend.capture_shape(bytes);
            let layers = shape.as_ref().map(|s| s.layer_count).unwrap_or(0);
            let positions = job.declared_prefill_tokens.saturating_add(job.exact_decode_tokens.saturating_sub(1));
            if layers > 0 && positions > 0 {
                let sites = palw_layer_sample_v3(
                    duty.panel_anchor,
                    duty.claim_id,
                    duty.seat_index as u16,
                    layers,
                    positions,
                    PALW_LAYER_SAMPLE_V3_SITES,
                );
                if !sites.is_empty() {
                    let mut all_match = true;
                    for site in &sites {
                        match backend.replay_layer_site_v3(bytes, *site, seats) {
                            Ok(true) => {}
                            Ok(false) => {
                                self.note_seat_fault_v1(duty.claim_id, 0, 0);
                                return PalwV2SeatPathV1::Faulted;
                            }
                            Err(_) => {
                                all_match = false;
                                break;
                            }
                        }
                    }
                    if all_match {
                        return PalwV2SeatPathV1::Attested(mask);
                    }
                }
            }
        }
        let k = palw_segment_count_v2(seats);
        let mut missing = Vec::new();
        for index in 0..k {
            if !mask.covers(index) {
                continue;
            }
            let req = palw_segment_opening_request_index_v1(seats, index);
            let opening = capture
                .and_then(|bytes| backend.open_segment_checkpoint_v1(bytes, seats, index).ok())
                .or_else(|| openings.get(&(duty.claim_id, req)).and_then(|v| v.first()).cloned());
            let Some(opening) = opening else {
                missing.push(req);
                continue;
            };
            // **Reserved for the segment's replay** (ADR-0151 follow-up, item 3): this segment's
            // partial-seat need — the prefix to its end, plus the opening it decodes from — taken
            // from the ledger for the replay's life and returned when the segment is done. A
            // refusal waits for a later tick; the deadline runs, as it does for every other hold.
            let session = self.consensus_manager.consensus().unguarded_session();
            let need = self.backends().role_memory_need_for_backend_or_chain_v1(
                backend,
                duty.class_id,
                duty.artifact_root,
                Some(job),
                kaspa_consensus_core::palw_resource_profile_v1::PalwResourceRoleV1::PartialSeat {
                    seat_count: seats,
                    segment_index: index,
                },
                |id| self.chain_carriage_v1(&session, id),
            );
            let _held_for_the_segment = match self.reserve_replay_v1("partial-seat", &need, duty.class_id, duty.claim_id) {
                Ok(reserved) => reserved,
                Err(why) => {
                    crate::palw_backends::note_throttled_v1("panel-segment-ledger", || {
                        format!("[{PALW_PANEL}] claim {} segment {index}: the resume waits — {why}", duty.claim_id)
                    });
                    return PalwV2SeatPathV1::Waiting;
                }
            };
            // SEAT-S4: the opening is authenticated against the CLAIM's roots and this seat's own
            // segment before a step replays; a refusal is `Err` (nothing served), never `Valid`.
            let segment_claim = kaspa_consensus_core::palw_segment_resume_v1::PalwSegmentClaimV1 {
                execution_root: duty.execution_root,
                trace_root: duty.trace_root,
                seat_count: seats,
                segment_index: index,
            };
            match backend.replay_segment_from_checkpoint_v1(job, prompt, &opening, segment_claim) {
                Ok(replay) if replay.matches => {}
                Ok(_) => {
                    self.note_seat_fault_v1(duty.claim_id, 0, 0);
                    return PalwV2SeatPathV1::Faulted;
                }
                Err(_) => return PalwV2SeatPathV1::Waiting,
            }
        }
        if !missing.is_empty() {
            let fresh: Vec<u32> = missing
                .into_iter()
                .filter(|i| requested_intervals.get(&(duty.claim_id, *i)).is_none_or(|at| current_daa >= at.saturating_add(25)))
                .collect();
            if !fresh.is_empty() {
                for i in &fresh {
                    requested_intervals.insert((duty.claim_id, *i), current_daa);
                }
                self.request_fp_interval_openings(network_domain, duty.claim_id, &fresh, current_daa).await;
            }
            return PalwV2SeatPathV1::Waiting;
        }
        PalwV2SeatPathV1::Attested(mask)
    }

    /// **Ask the network for the openings this seat's draw names** (ADR-0077 Decision 8, the seat
    /// half of P-08).
    ///
    /// One signed request per drawn interval, each registered with the gossip center first so the
    /// answer is admitted (the lane refuses anything unsolicited). The signature is this bond's,
    /// under [`crate::palw_fp_seat::PALW_FP_OPENING_REQUEST_MLDSA87_CONTEXT`] — the same key the
    /// seat's receipts use and a different context, so neither signature can stand in for the
    /// other.
    ///
    /// A node that cannot sign does not ask. Asking unsigned would be asking to be refused by
    /// every SA-2 server on the network, and the refusal would look like withholding.
    pub async fn request_fp_interval_openings(
        &self,
        network_domain: Hash64,
        claim: Hash64,
        intervals: &[u32],
        requested_daa: u64,
    ) -> usize {
        let Some(kp) = self.keypair.as_ref() else { return 0 };
        let mut asked = 0usize;
        for index in intervals {
            let Some(signature) = crate::palw_fp_seat::palw_fp_sign_opening_request_v1(
                &kp.signing_key,
                network_domain,
                claim,
                Some(*index),
                requested_daa,
            ) else {
                continue;
            };
            self.flow_context.palw_gossip().note_interval_pull_request(claim, *index);
            self.flow_context
                .request_palw_interval_opening(claim, *index, kp.verification_key.as_ref().to_vec(), signature, requested_daa, None)
                .await;
            asked += 1;
        }
        asked
    }

    /// **A signed request for `count` inventory rows** under the row-request index (RFC-0006 D-S6): the leaf-request signature scheme
    /// carries the count where a leaf evidence request carries its leaf, so one signature is one run, not a standing right.
    pub async fn request_tir_rows_v1(
        &self,
        network_domain: Hash64,
        claim: Hash64,
        index: u32,
        count: u32,
        requested_daa: u64,
    ) -> bool {
        self.request_tir_rows_v1_at(network_domain, claim, index, count, requested_daa).await
    }

    /// The signed ask both row and run requests ride: the leaf-request scheme with the count in the leaf slot.
    async fn request_tir_rows_v1_at(&self, network_domain: Hash64, claim: Hash64, index: u32, count: u32, requested_daa: u64) -> bool {
        let Some(kp) = self.keypair.as_ref() else { return false };
        let Some(signature) = crate::palw_fp_seat::palw_fp_sign_leaf_request_v1(
            &kp.signing_key,
            network_domain,
            claim,
            index,
            u64::from(count),
            requested_daa,
        ) else {
            return false;
        };
        self.flow_context.palw_gossip().note_interval_pull_request(claim, index);
        self.flow_context
            .request_palw_interval_opening(
                claim,
                index,
                kp.verification_key.as_ref().to_vec(),
                signature,
                requested_daa,
                Some(u64::from(count)),
            )
            .await;
        true
    }

    /// **RFC-0009 stage B: the material from ANY evidence provider, root-checked before it is handed on.**
    ///
    /// The claim's roots are the CHAIN's (`trace_root`, `output_root`, `execution_root`, the chunk count and the retention it obliges): a
    /// provider's manifest that disagrees with them is another execution's evidence, whoever signed for it. Each chunk is checked against the
    /// manifest; the reassembled bytes are then injected into the same inbox a peer's answer enters, so the seat's own `verify_material` and
    /// re-execution still judge them. A miss costs nothing: the producer pull that follows is unchanged. Provider silence is never evidence of
    /// anything (no slash rests on it — see `misaka_palw_remote::evidence::evidence_responsibility_v1`).
    async fn pull_material_from_evidence_providers(&self, network_domain: Hash64, claim: Hash64) {
        let session = self.consensus_manager.consensus().unguarded_session();
        let Some((state, _, _)) = session.palw_derived_artifacts_v1(claim) else { return };
        let roots = misaka_palw_remote::evidence::ClaimRoots {
            network_domain,
            trace_root: state.trace_root,
            output_root: state.output_root,
            execution_root: state.execution_root,
            trace_chunk_count: state.trace_chunk_count,
            retention_deadline: state.trace_retention_daa,
        };
        let dirs = self.config.evidence_provider_dirs.clone();
        let claim_hex = claim.to_string();
        let fetched = tokio::task::spawn_blocking(move || {
            misaka_palw_remote::evidence::fs::fetch_claim_material(
                &dirs,
                &claim_hex,
                &roots,
                &misaka_palw_remote::evidence::ManifestLimits::default(),
                claim,
            )
        })
        .await;
        match fetched {
            Ok(Ok((bytes, report))) => {
                let admitted = self.flow_context.palw_gossip().inject_local_material(claim, &bytes);
                info!(
                    "[{PALW_PANEL}] claim {claim}: {} byte(s) of material from evidence provider(s) {:?} ({admitted:?}); {} failed attempt(s) on the way",
                    bytes.len(),
                    report.served_by,
                    report.failures.len()
                );
            }
            // No provider offered an admissible manifest, or a chunk would not verify: say so once per pull, and fall through to the producer.
            Ok(Err(why)) => info!("[{PALW_PANEL}] claim {claim}: no evidence-provider material ({why})"),
            Err(join) => warn!("[{PALW_PANEL}] claim {claim}: the evidence-provider fetch did not finish ({join})"),
        }
    }

    /// **The signed whole-capture pull** (ADR-0077 SA-2's last sentence). The attempt lane keeps
    /// the whole-capture transport — Decision 8 retires it on the FREE-PROMPT lane only — so the
    /// pull stays, with a bond in front of it. Falls back to the unsigned form for a node with no
    /// key, which is a node that files no receipts either.
    pub async fn request_material_signed(&self, network_domain: Hash64, claim: Hash64, requested_daa: u64) {
        self.flow_context.palw_gossip().note_pull_request(claim);
        // RFC-0009 stage B: a provider may already hold the material — ask the directories too, before and beside the producer pull.
        if !self.config.evidence_provider_dirs.is_empty() {
            self.pull_material_from_evidence_providers(network_domain, claim).await;
        }
        let signed = self.keypair.as_ref().and_then(|kp| {
            crate::palw_fp_seat::palw_fp_sign_opening_request_v1(&kp.signing_key, network_domain, claim, None, requested_daa)
                .map(|signature| (kp.verification_key.as_ref().to_vec(), signature))
        });
        match signed {
            Some((pubkey, signature)) => self.flow_context.request_palw_material_signed(claim, pubkey, signature, requested_daa).await,
            None => self.flow_context.request_palw_material(claim).await,
        }
    }
}

/// Where the production code ends: `seat_s_tests` pins read the source before it. Since 87f93cd14 split the inline
/// test module out, that is the out-of-line `mod tests;` declaration below.
#[cfg(test)]
const MARKER_SEAT_S: &str = "#[cfg(test)]\nmod tests;";

#[cfg(test)]
mod tests;

#[cfg(test)]
mod accepted_objects_walk_tests;

#[cfg(test)]
mod seat_reask_tests {
    use super::seat_reask_daa_v1;

    /// A seat asks at least twice before it may accuse: the first pull at the bind and a re-ask
    /// strictly inside the half window, at every window a ruleset can set — and a long window keeps
    /// the old 25-DAA cadence. The 2026-09-20 drill's window was 40: one ask, then `Unavailable`.
    #[test]
    fn a_seat_asks_twice_before_it_may_accuse() {
        assert_eq!(seat_reask_daa_v1(40), 10, "the devnet's receipt window");
        assert_eq!(seat_reask_daa_v1(600), 25, "a long window re-asks exactly as before");
        for window in 4..=2_000u64 {
            let reask = seat_reask_daa_v1(window);
            assert!((1..=25).contains(&reask));
            assert!(reask < window / 2, "window {window}: the second ask at +{reask} is not before the accusation at +{}", window / 2);
        }
    }
}

#[cfg(test)]
mod seat_duty_panel_key_tests {
    use super::{
        PalwPanelService, SeatDutyPanelKeyV1, receipt_pool_kept_v1, seat_duty_is_due_v1, seat_duty_panel_key_v1,
        seat_duty_standing_keys_v1,
    };
    use crate::palw_receipt_pool::{
        OwnFiledV1, OwnRebroadcastV1, PalwReceiptPoolV1, ReceiptChainFactsV1, VerifyBudgetV1, own_receipts_due_v1,
    };
    use kaspa_consensus_core::palw_panel_v2::{
        PALW_RECEIPT_V3_MLDSA87_CONTEXT, PalwReceiptPoolFactsV1, PalwReceiptVerdictV2, PalwSeatReceiptV2, PalwSeatReceiptV3,
        palw_receipt_message_v3,
    };
    use kaspa_consensus_core::palw_producer_v2::PalwSeatDutyV2;
    use kaspa_consensus_core::palw_state_v2::PalwBondKeyV2;
    use kaspa_consensus_core::palw_verification_v2::PalwSegmentMaskV2;
    use kaspa_consensus_core::tx::TransactionOutpoint;
    use kaspa_hashes::Hash64;
    use std::collections::{HashMap, HashSet};
    use std::time::{Duration, Instant};

    fn duty(claim: u64, bound_daa: u64, anchor: u64) -> PalwSeatDutyV2 {
        let h = Hash64::from_u64_word;
        PalwSeatDutyV2 {
            accepted_block: h(1),
            claim_id: h(claim),
            class_id: h(2),
            artifact_root: h(3),
            seat_bond: PalwBondKeyV2(TransactionOutpoint::new(h(4), 0)),
            executor_bond: PalwBondKeyV2(TransactionOutpoint::new(h(5), 0)),
            execution_root: h(6),
            trace_root: h(7),
            output_root: h(8),
            bound_daa,
            receipt_deadline: bound_daa + 600,
            panel_anchor: h(anchor),
            seat_index: 2,
            panel_seat_count: 5,
            pwu: 1_000,
            quanta: 0,
            free_prompt: false,
            work_leaves: 0,
            job_identity: Hash64::default(),
            tir_shard: None,
        }
    }

    fn at_seat(mut duty: PalwSeatDutyV2, seat_index: u8, panel_seat_count: u16) -> PalwSeatDutyV2 {
        duty.seat_index = seat_index;
        duty.panel_seat_count = panel_seat_count;
        duty
    }

    /// **A seat answers each PANEL once** (the 2026-09-24 licence-stall fix). Two sibling blocks at
    /// the anchor slot bind two panels for one claim at one DAA; keyed by `(claim, bound_daa)` the
    /// seat that answered the first was told "already answered" by the second and never filed for
    /// it. The anchor tells them apart; the redraw's DAA still does; and the same panel seen again on
    /// a later tick is the same duty.
    #[test]
    fn a_rebound_panel_is_a_new_duty_and_the_same_panel_is_not() {
        let first = seat_duty_panel_key_v1(&duty(9, 120, 0xA1));
        assert_ne!(first, seat_duty_panel_key_v1(&duty(9, 120, 0xA2)), "a sibling panel at the same DAA is a new duty");
        assert_ne!(first, seat_duty_panel_key_v1(&duty(9, 720, 0xA1)), "a redraw is a new duty");
        assert_ne!(first, seat_duty_panel_key_v1(&duty(8, 120, 0xA1)), "another claim is another duty");
        assert_eq!(first, seat_duty_panel_key_v1(&duty(9, 120, 0xA1)), "the same panel is answered once");
    }

    /// **A seat moved within a panel re-files** (the launch review of the licence-stall fix, LOW
    /// (b)). Two siblings that differ in the registry draw different panels from one anchor at one
    /// DAA; the seat's mask is a function of its index and the panel's size, so a receipt to its
    /// old place is not one to its new. Keyed by `(claim, bound_daa, anchor)` alone the moved seat
    /// was "already answered" and filed nothing.
    #[test]
    fn a_seat_moved_within_a_panel_refiles() {
        let mut answered: HashSet<SeatDutyPanelKeyV1> = HashSet::new();
        let before = duty(9, 120, 0xA1);
        assert!(seat_duty_is_due_v1(&before, &answered, 130));
        answered.insert(seat_duty_panel_key_v1(&before));
        assert!(!seat_duty_is_due_v1(&before, &answered, 131), "the same place, answered");
        assert!(seat_duty_is_due_v1(&at_seat(before.clone(), 3, 5), &answered, 131), "moved to another index: a new duty");
        assert!(seat_duty_is_due_v1(&at_seat(before.clone(), 2, 6), &answered, 131), "a panel of another size: a new duty");
        assert!(!seat_duty_is_due_v1(&at_seat(before.clone(), 3, 5), &answered, 721), "…inside its receipt window only");
    }

    /// **The duty loop across a sibling swap and an A→B→A reorg** (the secondary test the launch
    /// review asked for). The seat files on panel A; the tip moves to sibling B (another anchor at
    /// the same DAA, and the seat at another index in it) and the seat files on B; the tip moves back
    /// to A and the seat does NOT file again — A was answered, its receipt is still held — but A's
    /// re-send resumes, because A is the standing duty again, while B's stops.
    #[test]
    fn the_duty_loop_refiles_across_a_sibling_swap_and_not_back_across_an_a_b_a_reorg() {
        let panel_a = duty(9, 120, 0xA1);
        let panel_b = at_seat(duty(9, 120, 0xB1), 4, 5);
        let mut answered: HashSet<SeatDutyPanelKeyV1> = HashSet::new();
        let mut filed: HashMap<SeatDutyPanelKeyV1, OwnFiledV1> = HashMap::new();
        let t0 = Instant::now();
        let file = |duty: &PalwSeatDutyV2, answered: &mut HashSet<SeatDutyPanelKeyV1>, filed: &mut HashMap<_, _>| {
            answered.insert(seat_duty_panel_key_v1(duty));
            filed.insert(
                seat_duty_panel_key_v1(duty),
                OwnFiledV1 {
                    claim: duty.claim_id,
                    verdict: PalwReceiptVerdictV2::Valid,
                    signed_daa: 125,
                    segments: None,
                    schedule: OwnRebroadcastV1::filed(t0),
                },
            );
        };
        // The tip holds A.
        let due: Vec<PalwSeatDutyV2> = [panel_a.clone()].into_iter().filter(|d| seat_duty_is_due_v1(d, &answered, 125)).collect();
        assert_eq!(due.len(), 1);
        file(&panel_a, &mut answered, &mut filed);
        // The tip moves to sibling B: a new panel, a new place — the seat judges it.
        assert!(seat_duty_is_due_v1(&panel_b, &answered, 126), "the sibling is a new duty");
        file(&panel_b, &mut answered, &mut filed);
        let standing_b: HashSet<SeatDutyPanelKeyV1> = [seat_duty_panel_key_v1(&panel_b)].into();
        let late = t0 + Duration::from_secs(31);
        assert_eq!(own_receipts_due_v1(&filed, &standing_b, late, 8), vec![seat_duty_panel_key_v1(&panel_b)], "only B re-sends");
        // And back to A: answered already (the claim stayed live, so the sweep kept the key), so no
        // second filing — but A's re-send is due again, and B's is not.
        assert!(!seat_duty_is_due_v1(&panel_a, &answered, 127), "A is not filed twice");
        let standing_a: HashSet<SeatDutyPanelKeyV1> = [seat_duty_panel_key_v1(&panel_a)].into();
        assert_eq!(own_receipts_due_v1(&filed, &standing_a, late, 8), vec![seat_duty_panel_key_v1(&panel_a)], "only A re-sends");
        // Once the claim leaves `PanelBound` no panel of it stands, and nothing re-sends.
        assert!(own_receipts_due_v1(&filed, &HashSet::new(), late, 8).is_empty());
    }

    /// **An S2 licence after a seat DA pause is not a new duty** (the M4 review's LOW on the duty key).
    /// The panel binds at 120; a seat DA session pauses the claim before this seat answers, and DA-5
    /// shifts the phase's bound DAA to 150 when it closes — so the seat answers under the key at 150
    /// (a receipt signed before 150 is refused by the licence doors, which is why a shift is a new
    /// duty, and still is). An S2 licence then keeps the seat on duty under the panel record's own
    /// bound DAA, 120 (`palw_seat_duties_v2`, what the supplementary doors read): the receipt filed at
    /// 150 answers it — no second signature, no second filing — and its re-send stands. A later shift,
    /// a redraw (a new anchor at a later DAA) and a sibling (another anchor at the same DAA) are
    /// still new duties.
    #[test]
    fn an_s2_licence_after_a_seat_da_pause_is_not_a_new_duty() {
        let shifted = duty(9, 150, 0xA1);
        let licensed = duty(9, 120, 0xA1);
        let mut answered: HashSet<SeatDutyPanelKeyV1> = HashSet::new();
        assert!(seat_duty_is_due_v1(&shifted, &answered, 160));
        answered.insert(seat_duty_panel_key_v1(&shifted));
        assert!(!seat_duty_is_due_v1(&licensed, &answered, 170), "the S2 licence does not make the seat re-sign");
        assert!(seat_duty_is_due_v1(&duty(9, 180, 0xA1), &answered, 181), "a later shift is answered again");
        assert!(seat_duty_is_due_v1(&duty(9, 720, 0xA2), &answered, 721), "a redraw is a new duty");
        assert!(seat_duty_is_due_v1(&duty(9, 150, 0xB1), &answered, 170), "a sibling is a new duty");

        let t0 = Instant::now();
        let filed: HashMap<SeatDutyPanelKeyV1, OwnFiledV1> = [(
            seat_duty_panel_key_v1(&shifted),
            OwnFiledV1 {
                claim: shifted.claim_id,
                verdict: PalwReceiptVerdictV2::Valid,
                signed_daa: 160,
                segments: None,
                schedule: OwnRebroadcastV1::filed(t0),
            },
        )]
        .into();
        let standing = seat_duty_standing_keys_v1(std::slice::from_ref(&licensed), filed.keys());
        let late = t0 + Duration::from_secs(31);
        assert_eq!(own_receipts_due_v1(&filed, &standing, late, 8), vec![seat_duty_panel_key_v1(&shifted)], "its re-send stands");
        let redrawn = seat_duty_standing_keys_v1(&[duty(9, 720, 0xA2)], filed.keys());
        assert!(own_receipts_due_v1(&filed, &redrawn, late, 8).is_empty(), "a redrawn panel's duty stands for none of it");
    }

    /// **The kept set is chain facts only** (LOW (a)): this tick's duties and this node's own
    /// filings. A claim the network sent receipts for — however many — is not kept, and so stays
    /// under the pool's ceiling.
    #[test]
    fn the_kept_set_ignores_gossip() {
        let h = Hash64::from_u64_word;
        let seat = PalwBondKeyV2(TransactionOutpoint::new(h(4), 0));
        let mut v2: PalwReceiptPoolV1<PalwSeatReceiptV2> = PalwReceiptPoolV1::new(h(999));
        let mut v3: PalwReceiptPoolV1<PalwSeatReceiptV3> = PalwReceiptPoolV1::new(h(999));
        let mut facts = ReceiptChainFactsV1::default();
        facts.refresh(
            PalwReceiptPoolFactsV1 { panels: Vec::new(), seat_keys: vec![(seat, vec![0; kaspa_txscript::MLDSA87_PK_LEN])] },
            &[seat].into(),
        );
        let receipt = |claim: u64| PalwSeatReceiptV2 {
            claim: h(claim),
            verdict: PalwReceiptVerdictV2::Valid,
            seat_bond: seat,
            signed_daa: 7,
            signature: vec![1; kaspa_txscript::MLDSA87_SIG_LEN],
        };
        // Gossip: receipts for claims 0x61 and 0x62, pooled unchecked (no budget).
        let mut spent = VerifyBudgetV1::new(0, 0);
        let never = |_: &[u8], _: &[u8], _: &[u8], _: &[u8]| false;
        for claim in [0x61, 0x62] {
            assert!(v2.admit(receipt(claim), &facts, &never, &mut spent, 10, &HashSet::new()).kept());
            let v3_receipt = PalwSeatReceiptV3 { receipt: receipt(claim), segments: PalwSegmentMaskV2::single(0) };
            assert!(v3.admit(v3_receipt, &facts, &never, &mut spent, 10, &HashSet::new()).kept());
        }
        assert!(receipt_pool_kept_v1(&[], &v2, &v3).is_empty(), "nothing a peer sent is kept");
        // A duty and an own filing are.
        v3.insert_own(PalwSeatReceiptV3 { receipt: receipt(0x71), segments: PalwSegmentMaskV2::single(0) }, 700);
        let kept = receipt_pool_kept_v1(&[duty(0x72, 120, 0xA1)], &v2, &v3);
        assert_eq!(kept, [h(0x71), h(0x72)].into());
    }

    /// **The re-send is a new signature over the same receipt** (fix (4)). The filing signs with an
    /// all-zero `rnd` — ML-DSA-87's deterministic variant, whose re-signing is the same bytes and so
    /// a relay-once `Duplicate` everywhere. The hedged re-sign is new bytes that verify under the
    /// same key and message.
    #[test]
    fn the_hedged_resend_is_a_new_signature_over_the_same_receipt() {
        let kp = libcrux_ml_dsa::ml_dsa_87::generate_key_pair([0x42; 32]);
        let key = kp.verification_key.as_ref().to_vec();
        let message = palw_receipt_message_v3(
            Hash64::from_u64_word(999),
            Hash64::from_u64_word(9),
            PalwReceiptVerdictV2::Valid,
            125,
            PalwSegmentMaskV2::single(1),
        );
        let deterministic = |_: ()| {
            libcrux_ml_dsa::ml_dsa_87::sign(&kp.signing_key, message.as_byte_slice(), PALW_RECEIPT_V3_MLDSA87_CONTEXT, [0u8; 32])
                .unwrap()
                .as_ref()
                .to_vec()
        };
        assert_eq!(deterministic(()), deterministic(()), "the filing's signature is deterministic");
        let first = PalwPanelService::sign_hedged(&kp.signing_key, message.as_byte_slice(), PALW_RECEIPT_V3_MLDSA87_CONTEXT).unwrap();
        let again = PalwPanelService::sign_hedged(&kp.signing_key, message.as_byte_slice(), PALW_RECEIPT_V3_MLDSA87_CONTEXT).unwrap();
        assert_ne!(first, again, "fresh randomness each time");
        assert_ne!(first, deterministic(()));
        for signature in [&first, &again] {
            assert!(super::verify_receipt_signature_v1(&key, message.as_byte_slice(), signature, PALW_RECEIPT_V3_MLDSA87_CONTEXT));
        }
    }
}

#[cfg(test)]
mod replay_rule_tests {
    use super::replay_licenses_v1;
    use kaspa_consensus_core::palw_backend::PalwReplayRootsV1;
    use kaspa_hashes::Hash64;

    fn roots(work: Option<u64>) -> PalwReplayRootsV1 {
        PalwReplayRootsV1 {
            execution_root: Hash64::from_u64_word(0xE),
            trace_root: Hash64::from_u64_word(0x7),
            work_leaves: work,
            output_root: None,
        }
    }

    /// An attempt-lane claim prices no leaves; the replay's own count is the class's space.
    #[test]
    fn an_unpriced_claim_is_licensed_by_its_roots_alone() {
        assert!(replay_licenses_v1(&roots(Some(6_630_544)), Hash64::from_u64_word(0xE), Hash64::from_u64_word(0x7), 0));
        assert!(replay_licenses_v1(&roots(None), Hash64::from_u64_word(0xE), Hash64::from_u64_word(0x7), 0));
    }

    /// A priced claim must reproduce its work too — the roots match but the WORK does not is the
    /// free-prompt arm's refusal, and this rule is the same one.
    #[test]
    fn a_priced_claim_must_reproduce_its_work() {
        assert!(replay_licenses_v1(&roots(Some(30)), Hash64::from_u64_word(0xE), Hash64::from_u64_word(0x7), 30));
        assert!(!replay_licenses_v1(&roots(Some(31)), Hash64::from_u64_word(0xE), Hash64::from_u64_word(0x7), 30));
        assert!(
            replay_licenses_v1(&roots(None), Hash64::from_u64_word(0xE), Hash64::from_u64_word(0x7), 30),
            "a family that prices no leaves is judged on its roots"
        );
    }

    #[test]
    fn a_root_that_does_not_reproduce_is_never_licensed() {
        assert!(!replay_licenses_v1(&roots(Some(30)), Hash64::from_u64_word(0xF), Hash64::from_u64_word(0x7), 0));
        assert!(!replay_licenses_v1(&roots(Some(30)), Hash64::from_u64_word(0xE), Hash64::from_u64_word(0x8), 30));
    }
}

