#[cfg(test)]
mod held_class_form_pin {
    /// The whole call starting at `s` (which begins with the callee's name), by its parentheses.
    fn call_extent(s: &str) -> &str {
        let open = s.find('(').expect("a call");
        let mut depth = 0usize;
        for (i, c) in s[open..].char_indices() {
            match c {
                '(' => depth += 1,
                ')' => {
                    depth -= 1;
                    if depth == 0 {
                        return &s[..open + i + 1];
                    }
                }
                _ => {}
            }
        }
        s
    }

    /// **ADR-0118 Decision 3, pinned where it lives: every payload this panel decodes, every
    /// prompt it derives and every carriage a seat builds reads the claim's CLASS's form.** A held
    /// class commits Merkle ids on a network minted flat, so a reader that took the network's form
    /// would refuse every held claim's ids and file nothing. The network's form is read in exactly
    /// the places that are the network's: the backend registry and the SDK (whose backends keep
    /// their class's form), the two class-form doors themselves, the canonical claim's carrier (the
    /// chain's stateless check holds no class), and a bisection's close (the chain's close check;
    /// no held class is ever bisected).
    #[test]
    fn every_panel_reader_takes_the_claims_class_form() {
        let whole = include_str!("palw_panel.rs");
        let source = &whole[..whole.find("#[cfg(test)]\nmod tests").expect("the unit tests follow the code")];
        let uses: Vec<&str> = source.lines().filter(|l| l.contains("self.config.prompt_ids_form")).map(str::trim).collect();
        // Six: the node registry's one constructor (`PalwBackendRegistry::for_node_v1`, which read it
        // twice before the producer and the panel shared it), the two class-form doors, the
        // canonical claim's carrier — built by two builders since G14's original public pledge
        // (`build_fp_commitment_tx_original_public_v1` beside `build_fp_commitment_tx_under_params_v1`;
        // both feed the chain's stateless check, which holds no class) — and a bisection's close.
        assert_eq!(uses.len(), 6, "a new reader of the network's form — read the class's instead (ADR-0118 D3): {uses:#?}");
        assert!(source.contains("fn class_prompt_ids_form(&self, class_id: Hash64)"), "the one door");
        for callee in [
            "palw_fp_capture_decode_v1(",
            "palw_fp_material_decode_v1(",
            "palw_fp_job_material_decode_v1(",
            "palw_fp_answer_decode_v1(",
            "palw_fp_committed_output_ids_decode_v1(",
            "palw_fp_seat_prompt_admit_v1(",
            "fp_prompt_for_job(",
            "fp_capture_view(",
            "palw_leaf_evidence_from_capture_v1(",
        ] {
            let calls: Vec<&str> = source.match_indices(callee).map(|(at, _)| call_extent(&source[at..])).collect();
            assert!(!calls.is_empty(), "{callee} is still read here");
            for call in calls {
                assert!(!call.contains("self.config.prompt_ids_form"), "{callee} reads the network's form: {call}");
            }
        }
    }
}

#[cfg(test)]
mod attn_opening_cap_pin {
    use super::attn_root_claim_is_openable_v1;
    use kaspa_consensus_core::config::params::{PALW_RC_HELD_FENCE_DAA, Params};
    use kaspa_consensus_core::network::{NetworkId, NetworkType};
    use kaspa_consensus_core::palw_step::PALW_STEP_MAX_LEAVES;

    /// **ADR-0119 Decision 4, on the node: a root claim is filed exactly when the court will open
    /// it.** Before testnet-11's held regime the court opens a fused site's rows to `2^22` and no
    /// further, so the panel files no root claim past it (the evidence builds at the backend's
    /// ladder now, and would otherwise be filed and refused); from the regime's height the court
    /// opens them at the claim's ladder, and testnet-11's dense row — `6,630,544` leaves at its
    /// canonical 512 — is answered. The root claim is the one move filed without a dry run, so the
    /// arm asks this before it signs.
    #[test]
    fn a_root_claim_is_filed_exactly_when_the_court_opens_its_rows() {
        let t11 = Params::from(NetworkId::with_suffix(NetworkType::Testnet, 11));
        let fence = PALW_RC_HELD_FENCE_DAA.expect("testnet-11 schedules the regime");
        let dense_v5_canonical = 6_630_544;
        assert!(attn_root_claim_is_openable_v1(&t11, fence - 1, PALW_STEP_MAX_LEAVES), "inside the structural cap, always");
        assert!(!attn_root_claim_is_openable_v1(&t11, fence - 1, PALW_STEP_MAX_LEAVES + 1), "one past it, not before the regime");
        assert!(!attn_root_claim_is_openable_v1(&t11, fence - 1, dense_v5_canonical));
        assert!(attn_root_claim_is_openable_v1(&t11, fence, dense_v5_canonical), "from the regime's height, the dense row");
        let mut dormant = t11.clone();
        dormant.palw_held_context = None;
        assert!(!attn_root_claim_is_openable_v1(&dormant, u64::MAX, dense_v5_canonical), "no regime, no raise");

        let whole = include_str!("palw_panel.rs");
        let source = &whole[..whole.find("#[cfg(test)]\nmod tests").expect("the unit tests follow the code")];
        let root = &source[source.find("AttnMove::Root => {").expect("the root arm")..];
        let asked = root.find("attn_root_claim_is_openable_v1(params, current_daa, evidence.binding.step_leaf_count)").expect("asked");
        assert!(asked < root.find("self.sign(&message").expect("signed"), "asked before the root claim is signed");
    }
}

#[cfg(test)]
mod own_claim_event_tests {
    use super::own_claim_events_v1;
    use kaspa_consensus_core::palw_producer_v2::PalwClaimRowV1;
    use kaspa_consensus_core::palw_state_v2::{PalwBondKeyV2, PalwClaimPhaseV2 as P, PalwVoidReasonV2 as R};
    use kaspa_consensus_core::tx::{TransactionId, TransactionOutpoint};
    use kaspa_hashes::Hash64;

    fn row(id: u8, phase: P) -> PalwClaimRowV1 {
        PalwClaimRowV1 {
            claim_id: Hash64::from_bytes([id; 64]),
            free_prompt: false,
            quanta: 0,
            quanta_spent: 0,
            class_id: Hash64::from_bytes([7; 64]),
            executor_bond: PalwBondKeyV2(TransactionOutpoint::new(TransactionId::from_u64_word(1), 0)),
            phase,
            accepted_daa: 100,
            accepted_block: Default::default(),
            rebound_daa: None,
            seats: Vec::new(),
            bound_daa: None,
            deadline_daa: Some(700),
            reserved: 0,
            committed: Some(0),
            reservation_split: None,
            escrowed_reward: 0,
            payout_pending: None,
            work_leaves: 0,
            open_courts: 0,
            exec_lane: None,
        }
    }

    /// **One line per change, in the operator's stage names** — ADR-0122 Decision 8's chain half:
    /// a claim seen first prints its stage, an unchanged one prints nothing, a change prints once,
    /// and a void carries its reason as a value a program reads.
    #[test]
    fn each_phase_change_of_an_own_claim_prints_one_event() {
        let mut seen = Default::default();
        let first = own_claim_events_v1(&mut seen, &[row(1, P::Provisional)]);
        assert_eq!(first.len(), 1);
        assert!(first[0].starts_with("event work=0101010101010101 lane=block stage=ON_CHAIN phase_daa=100"), "{}", first[0]);
        assert!(own_claim_events_v1(&mut seen, &[row(1, P::Provisional)]).is_empty(), "unchanged prints nothing");
        let bound = own_claim_events_v1(&mut seen, &[row(1, P::PanelBound { bound_daa: 120 })]);
        assert!(bound[0].contains("stage=WAITING_RECEIPTS phase_daa=120"), "{}", bound[0]);
        let void = own_claim_events_v1(&mut seen, &[row(1, P::Voided { voided_daa: 800, reason: R::ReceiptTimeout })]);
        assert!(void[0].contains("stage=VOIDED phase_daa=800 reason=receipt_timeout"), "{}", void[0]);
        assert!(own_claim_events_v1(&mut seen, &[]).is_empty(), "a retired claim leaves quietly");
        assert!(seen.is_empty(), "and is forgotten");
    }
}

